// ═══════════════════════════════════════════════════════════════════════════
//  DUPLICATE DETECTION — runs at load time, logs to browser console.
//  Protects against the historical bug where the same machine appeared in
//  multiple categories (e.g. a telehandler placed in MACHINES.boom by mistake)
//  or the same machine existed twice in one category with slightly different
//  IDs. Prints a visible warning if any duplicate name or id is found.
// ═══════════════════════════════════════════════════════════════════════════
(function _noyoCheckMachineDuplicates() {
  try {
    const byName = {};
    const byId = {};
    const cats = [
      "forklift",
      "telehandler",
      "scissor",
      "boom",
      "material",
      "pushAround",
      "verticalMast",
      "palletJack",
      "earthworks",
    ];
    cats.forEach((cat) => {
      const arr = MACHINES[cat];
      if (!Array.isArray(arr)) return;
      arr.forEach((m) => {
        if (!m) return;
        if (m.name) (byName[m.name] = byName[m.name] || []).push({ cat, id: m.id });
        if (m.id)   (byId[m.id]     = byId[m.id]     || []).push({ cat, name: m.name });
      });
    });
    const dupNames = Object.entries(byName).filter(([, v]) => v.length > 1);
    const dupIds   = Object.entries(byId).filter(([, v]) => v.length > 1);
    if (dupNames.length || dupIds.length) {
      console.warn("⚠️ Noyo: duplicate machine entries detected — please deduplicate in app.js");
      dupNames.forEach(([n, occ]) =>
        console.warn(`  Duplicate name: "${n}"`, occ)
      );
      dupIds.forEach(([i, occ]) =>
        console.warn(`  Duplicate id:   "${i}"`, occ)
      );
    } else {
      const total = cats.reduce((n, c) => n + (MACHINES[c] ? MACHINES[c].length : 0), 0);
      console.log("\u2713 Noyo: machine database OK — no duplicates (" + total + " entries)");
    }
  } catch (e) {
    console.warn("Noyo duplicate-check failed:", e);
  }
})();

