// Type-based fallback photos
const TYPE_PHOTOS = {
  // Proper fallback photos per machine category — manufacturer press images
  forklift:
    "https://www.toyotamaterialhandling.com.au/images/products/8FGU25-8FGU30.jpg",
  telehandler:
    "https://www.manitou.com/uploads/tx_apcmanitoumedia/MT-1440-145-PS-ST5-S1.jpg",
  scissor:
    "https://www.genielift.com/images/default-source/aerial-products/scissor-lifts/genie-gs-1930-electric-scissor-lift.jpg",
  boom: "https://www.jlg.com/content/dam/jlg/en-us/products/boom-lifts/articulating/450aj/jlg-450aj-articulating-boom-lift.jpg",
  material:
    "https://www.genielift.com/images/default-source/aerial-products/material-lifts/genie-sla10.jpg",
  pushAround:
    "https://www.genielift.com/images/default-source/aerial-products/aerial-work-platforms/genie-awp-30s.jpg",
};

function getMachinePhoto(m, type) {
  return MACHINE_PHOTOS[m.id] || TYPE_PHOTOS[type] || TYPE_PHOTOS.forklift;
}

// =====================================================================
// MACHINE MATCHING LOGIC
// =====================================================================
// ─── Helpers ────────────────────────────────────────────────────────────────

// Pick up to `maxPer` machines per brand from a sorted pool, until we have `total`
// ── getCapacityAtPoint — MODULE LEVEL so _buildTeleCapacityPanel can call it ──
function getCapacityAtPoint(m, needH, needR, useStabs) {
  // ZONE LOOKUP — load charts define constant-capacity zones, not gradients.
  // Each {h, r, kg} point is the OUTER BOUNDARY of that zone at that height.
  // We find the first boundary point where reach <= boundary.r → return that zone's kg.
  // Between height rows: take the minimum (more conservative) zone from the two bounding rows.
  //
  // STABILISERS: For machines with separate retracted/extended load charts:
  //   - loadMatrix     = stabilisers RETRACTED (on tyres) — more conservative
  //   - loadMatrixStabs = stabilisers EXTENDED — larger working envelope
  // useStabs=true selects loadMatrixStabs when present. Default = false (conservative).
  // For machines without a stabs matrix, useStabs is ignored.
  const matrix = (useStabs && m.loadMatrixStabs && m.loadMatrixStabs.length)
    ? m.loadMatrixStabs
    : m.loadMatrix;
  if (
    (!matrix || !matrix.length) &&
    m.liftChart &&
    Array.isArray(m.liftChart) &&
    m.liftChart.length
  ) {
    const ratedKg =
      (m.liftCapacity || m.capacity || 0) > 100
        ? m.liftCapacity || m.capacity || 0
        : (m.liftCapacity || m.capacity || 0) * 1000;
    const lm = m.liftChart.map((p) => ({
      h: p.height,
      r: p.reach,
      kg: Math.round(p.capacity > 100 ? p.capacity : p.capacity * 1000),
    }));
    const byReach = [...lm].sort((a, b) => a.r - b.r);
    if (needR > byReach[byReach.length - 1].r) return 0;
    const lo = byReach.filter((p) => p.r <= needR).pop() ?? byReach[0];
    const hi =
      byReach.filter((p) => p.r >= needR)[0] ?? byReach[byReach.length - 1];
    const tr = hi.r === lo.r ? 0 : (needR - lo.r) / (hi.r - lo.r);
    const capAtMaxH = Math.round(lo.kg + (hi.kg - lo.kg) * tr);
    const maxHAtR = lo.h + (hi.h - lo.h) * tr;
    if (needH > maxHAtR) return 0;
    const htFrac = maxHAtR > 0 ? Math.min(needH / maxHAtR, 1.0) : 0;
    return Math.round(ratedKg - (ratedKg - capAtMaxH) * Math.pow(htFrac, 0.65));
  }
  if (!matrix || !matrix.length) return null;
  const heights = [...new Set(matrix.map((p) => p.h))].sort(
    (a, b) => a - b,
  );
  if (needH > heights[heights.length - 1]) return 0;
  const clampH = Math.max(
    heights[0],
    Math.min(needH, heights[heights.length - 1]),
  );
  const h0 = heights.filter((h) => h <= clampH).pop() ?? heights[0];
  const h1 =
    heights.filter((h) => h >= clampH)[0] ?? heights[heights.length - 1];

  // Zone lookup: find which zone reach falls in (step function, no interpolation)
  function zoneAtRow(targetH, r) {
    const row = matrix
      .filter((p) => p.h === targetH)
      .sort((a, b) => a.r - b.r);
    if (!row.length) return null;
    // Outside envelope (beyond max reach at this height)
    if (r > row[row.length - 1].r * 1.02) return 0;
    // Walk zone boundaries: first boundary where r <= boundary.r is the zone we're in
    for (const pt of row) {
      if (r <= pt.r) return pt.kg;
    }
    return row[row.length - 1].kg;
  }

  const cap0 = zoneAtRow(h0, needR);
  const cap1 = zoneAtRow(h1, needR);
  if (cap0 === null && cap1 === null) return null;
  if (cap0 === null) return cap1;
  if (cap1 === null) return cap0;
  if (h1 === h0) return cap0;
  // Between height rows: return the more conservative (lower) zone value
  // This matches what a physical chart would show — at an intermediate height,
  // the machine's actual zone is no better than the most conservative bounding row.
  return Math.min(cap0, cap1);
}

// Generic size signature — normalises key working-envelope dimensions across
// machine types (forklift / telehandler / scissor / boom). Returns 0 for any
// dimension a machine doesn't have, so comparisons only count shared dims.
function _machineSizeSig(m) {
  if (!m) return { cap: 0, ht: 0, reach: 0, wt: 0 };
  const rawCap = m.liftCapacity || m.capacity || 0;
  return {
    cap: rawCap > 100 ? rawCap : rawCap * 1000, // always kg
    ht:
      m.liftHeight || m.platformHeight || m.workingHeight || m.workHeight || 0,
    reach: m.maxReach || m.maxHorizontalReach || 0,
    wt: m.machineWeight || m.weight || m.operatingWeightKg || 0,
  };
}

// Closeness of candidate `m` to anchor — returns 0..1 (1 = identical size).
// Only dimensions present on BOTH machines contribute. If neither machine has
// any comparable dim, returns 0.5 (neutral — don't influence ranking).
function _sizeClosenessToAnchor(m, anchor) {
  const a = _machineSizeSig(anchor);
  const b = _machineSizeSig(m);
  const ratios = [];
  if (a.cap > 0 && b.cap > 0)
    ratios.push(Math.min(a.cap, b.cap) / Math.max(a.cap, b.cap));
  if (a.ht > 0 && b.ht > 0)
    ratios.push(Math.min(a.ht, b.ht) / Math.max(a.ht, b.ht));
  if (a.reach > 0 && b.reach > 0)
    ratios.push(Math.min(a.reach, b.reach) / Math.max(a.reach, b.reach));
  if (!ratios.length) return 0.5;
  return ratios.reduce((s, x) => s + x, 0) / ratios.length;
}

function diversePick(sortedPool, total, maxPer, preferredBrand) {
  if (!sortedPool || !sortedPool.length) return [];

  const brandCount = {};
  const picked = [];

  // ── Count distinct brands in the pool ────────────────────────────────
  // When 4+ brands are available, enforce strict maxPer (no relaxation
  // fallback). This guarantees brand diversity when it's actually
  // achievable — previously the fallback at the bottom of this function
  // would relax the cap and produce e.g. 3×Liftlux + 2×Haulotte even
  // though Genie/JLG/Skyjack machines existed in the pool and should
  // have been surfaced instead.
  const distinctBrands = new Set();
  sortedPool.forEach((m) => {
    if (m && m.brand) distinctBrands.add(m.brand);
  });
  const strictDiversity = distinctBrands.size >= 4;

  // ── Position 0: always the highest-scored machine (= best match). ──────────
  // This anchors the rest of the result set.
  const anchor = sortedPool[0];
  picked.push(anchor);
  brandCount[anchor.brand] = 1;

  // ── Positions 1..N: re-rank remaining candidates by a blend of their own
  //    score AND their size-closeness to the anchor. This stops secondary-brand
  //    picks from being over-sized machines just because they happened to
  //    out-score that brand's closer-in-size alternatives on terrain / features.
  //    Net effect: 3rd/4th/5th results lean toward same-size-class other-brand
  //    machines rather than bigger ones.
  const rest = sortedPool.slice(1);
  if (rest.length) {
    const scores = rest.map((m) => m.score || m._score || 0);
    const maxS = Math.max(...scores);
    const minS = Math.min(...scores);
    const range = Math.max(maxS - minS, 1);

    const ranked = rest
      .map((m) => {
        const norm = ((m.score || m._score || 0) - minS) / range; // 0..1
        const close = _sizeClosenessToAnchor(m, anchor); // 0..1
        // 55% weight to original score (keeps the scorer's quality signal
        // dominant) + 45% to size closeness (pulls in same-class alternatives).
        return { m, combined: norm * 0.55 + close * 0.45 };
      })
      .sort((a, b) => b.combined - a.combined);

    // ── Round 1: one machine per brand (strict cap) ────────────────────
    for (const entry of ranked) {
      if (picked.length >= total) break;
      const b = entry.m.brand;
      // Preferred brand gets a much higher cap so multiple can appear
      const cap =
        preferredBrand && b && b.toLowerCase().includes(preferredBrand)
          ? Math.min(total, 4)
          : maxPer;
      if ((brandCount[b] || 0) >= cap) continue;
      brandCount[b] = (brandCount[b] || 0) + 1;
      picked.push(entry.m);
    }

    // ── Round 2+: allow repeats ONLY when pool lacks 4 distinct brands ──
    // When 4+ brands exist and we've reached `total` picks already, we're
    // done. When 4+ brands exist but we couldn't fill `total` without
    // repeating a brand, we stop anyway — strict diversity wins over
    // hitting the target count. When <4 brands exist, fall through to
    // relax the cap so the result set still fills up.
    if (picked.length < total && !strictDiversity) {
      for (const entry of ranked) {
        if (picked.includes(entry.m)) continue;
        if (picked.length >= total) break;
        picked.push(entry.m);
      }
    }
  }

  return picked;
}

// Find the best "one step up" machine not already in results
function findNextUp(sortedPool, results, keyFn) {
  if (!results || !results.length || !results[0]) return null;
  const bestVal = keyFn(results[0]) || 0;
  if (!bestVal) return null;
  // Use ID set to avoid showing the same machine twice (spread objects fail reference equality)
  const usedIds = new Set(results.map((m) => m.id));
  const usedBrands = new Set(results.map((m) => m.brand));
  // "One size up" = more than 15% above the best matched machine's key value, not already shown
  let up = sortedPool.find(
    (m) =>
      !usedIds.has(m.id) &&
      keyFn(m) > bestVal * 1.15 &&
      !usedBrands.has(m.brand),
  );
  if (!up)
    up = sortedPool.find(
      (m) => !usedIds.has(m.id) && keyFn(m) > bestVal * 1.15,
    );
  return up || null;
}

// ─── Result Sort/Filter State ────────────────────────────────────────────────
let _sortMatches = []; // full result set for current search
