// ═══════════════════════════════════════════════════════════════
// QUOTE CART SYSTEM
// ═══════════════════════════════════════════════════════════════

// In-memory quote cart and inbox
var quoteCart = []; // [{id, name, emoji, type}]
// ═══════════════════════════════════════════════════════════════
// FIRESTORE — persistent cloud quote storage
// All quote requests and responses stored in Firebase Firestore.
// Multi-device, real-time, no API key management needed.
// ═══════════════════════════════════════════════════════════════

const CLOUD_ENABLED = true;

// ── Local cache (keeps UI snappy while Firestore syncs) ──────
const INBOX_STORAGE_KEY = "noyo_quote_inbox_v1";
function _cacheInbox(data) {
  try {
    localStorage.setItem(INBOX_STORAGE_KEY, JSON.stringify(data));
  } catch (e) {}
}
function _readCache() {
  try {
    const r = localStorage.getItem(INBOX_STORAGE_KEY);
    return r ? JSON.parse(r) : [];
  } catch (e) {
    return [];
  }
}

// ── Save quote inbox — Firestore PRIMARY, localStorage cache ──
function saveInbox() {
  _cacheInbox(quoteInbox); // local cache for instant reads
  if (!currentUser || !currentUser.uid) return;
  (async () => {
    try {
      await _fbDb
        .collection("quote_inboxes")
        .doc(currentUser.uid)
        .set(
          {
            quotes: _stripUndefined(quoteInbox),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
          },
          { merge: true },
        );
    } catch (e) {
      if (navigator.onLine !== false)
        console.warn("Firestore inbox save failed:", e.message);
    }
  })();
}

// loadInbox: always try Firestore first, fall back to cache
function loadInbox() {
  // Return cache immediately for fast startup — Firestore sync happens after login
  return _readCache();
}

// ── Smart merge helper (same logic as before) ─────────────────
function _mergeInboxArrays(remote, local) {
  if (!Array.isArray(remote)) return Array.isArray(local) ? local : [];
  if (!Array.isArray(local)) return remote;
  const map = new Map();
  local.forEach((req) => {
    if (req && req.id) map.set(req.id, req);
  });
  remote.forEach((remReq) => {
    if (!remReq || !remReq.id) return;
    const locReq = map.get(remReq.id);
    if (!locReq) {
      map.set(remReq.id, remReq);
      return;
    }
    const remRespCount = (remReq.responses || []).length;
    const locRespCount = (locReq.responses || []).length;
    const winner = locRespCount >= remRespCount ? locReq : remReq;
    const loser = locRespCount >= remRespCount ? remReq : locReq;
    const merged = { ...loser, ...winner };
    const allResp = [...(remReq.responses || []), ...(locReq.responses || [])];
    const seenComp = new Map();
    allResp.forEach((r) => {
      const key = (r.company || "") + "|" + (r.ts || "");
      if (!seenComp.has(key)) seenComp.set(key, r);
    });
    merged.responses = [...seenComp.values()];
    merged.responded = locReq.responded || remReq.responded || false;
    map.set(remReq.id, merged);
  });
  return [...map.values()];
}

// ── Load inbox from Firestore ─────────────────────────────────
async function loadInboxFromFirebase() {
  if (!currentUser || !currentUser.uid) return loadInbox();
  try {
    // Rental companies read from shared_enquiries — enquiries submitted by all customers
    // Customers/admins read from their own quote_inboxes
    const isRentalCo =
      currentUser.role === "rental" || currentUser.role === "admin_rental";
    const isAdmin = currentUser.role === "admin";

    if (isRentalCo && !isAdmin) {
      // Load shared enquiries for rental company view
      const sharedSnap = await _fbDb
        .collection("shared_enquiries")
        .limit(300)
        .get();
      const sharedArr = sharedSnap.docs
        .map((d) => ({ id: d.id, ...d.data() }))
        .sort((a, b) => (b.ts || 0) - (a.ts || 0));
      // Also read quote_requests for backward compat with pre-fix submissions
      let legacyArr = [];
      try {
        const legacySnap = await _fbDb
          .collection("quote_requests")
          .limit(300)
          .get();
        legacyArr = legacySnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      } catch (e) {}
      // Merge with own inbox (admin broadcast direct writes)
      const ownSnap = await _fbDb
        .collection("quote_inboxes")
        .doc(currentUser.uid)
        .get();
      const ownArr = ownSnap.exists ? ownSnap.data().quotes || [] : [];
      const merged = _mergeInboxArrays(
        [...sharedArr, ...legacyArr, ...ownArr],
        _readCache(),
      );
      quoteInbox = merged;
      _cacheInbox(merged);
      return quoteInbox;
    }

    // Admin reads ALL enquiries from shared_enquiries + own inbox
    if (isAdmin) {
      const sharedSnap = await _fbDb
        .collection("shared_enquiries")
        .limit(500)
        .get();
      const sharedArr = sharedSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      let legacyArr = [];
      try {
        const legacySnap = await _fbDb
          .collection("quote_requests")
          .limit(500)
          .get();
        legacyArr = legacySnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      } catch (e) {}
      const ownSnap2 = await _fbDb
        .collection("quote_inboxes")
        .doc(currentUser.uid)
        .get();
      const ownArr2 = ownSnap2.exists ? ownSnap2.data().quotes || [] : [];
      // For admin: Firestore responses ALWAYS win over local cache
      // Build a map from Firestore data first, then layer in local-only items
      const firestoreMap = new Map();
      [...sharedArr, ...legacyArr, ...ownArr2].forEach((r) => {
        if (!r || !r.id) return;
        const existing = firestoreMap.get(r.id);
        const rCount = (r.responses || []).length;
        const eCount = existing ? (existing.responses || []).length : -1;
        if (!existing || rCount >= eCount) firestoreMap.set(r.id, r);
      });
      // Add any local-only items (not yet in Firestore)
      const cached2 = _readCache() || [];
      cached2.forEach((r) => {
        if (r && r.id && !firestoreMap.has(r.id)) firestoreMap.set(r.id, r);
      });
      const merged2 = [...firestoreMap.values()];
      quoteInbox = merged2;
      _cacheInbox(merged2);
      return quoteInbox;
    }

    const snap = await _fbDb
      .collection("quote_inboxes")
      .doc(currentUser.uid)
      .get();
    const remoteArr = snap.exists ? snap.data().quotes || [] : [];
    // Also read from shared_enquiries to pick up rental company responses
    // Filter to only this customer's own enquiries (by email)
    let sharedCustomerArr = [];
    const custEmail = (currentUser.email || "").toLowerCase();
    try {
      const sharedSnap = await _fbDb
        .collection("shared_enquiries")
        .where("email", "==", custEmail)
        .limit(100)
        .get();
      sharedCustomerArr = sharedSnap.docs.map((d) => ({
        id: d.id,
        ...d.data(),
      }));
    } catch (e) {
      // Fallback if no index: load all and filter client-side
      try {
        const allSnap = await _fbDb
          .collection("shared_enquiries")
          .limit(300)
          .get();
        sharedCustomerArr = allSnap.docs
          .map((d) => ({ id: d.id, ...d.data() }))
          .filter((r) => (r.email || "").toLowerCase() === custEmail);
      } catch (e2) {}
    }
    const localArr = _readCache();
    const merged = _mergeInboxArrays(
      [...remoteArr, ...sharedCustomerArr],
      localArr,
    );
    quoteInbox = merged;
    _cacheInbox(merged);
    return quoteInbox;
  } catch (e) {
    console.warn("Firestore inbox load failed, using local cache:", e.message);
    const cached = _readCache();
    if (Array.isArray(cached) && cached.length > 0) quoteInbox = cached;
    return quoteInbox;
  }
}

// ── Save individual quote to Firestore quotes collection ──────
// Clean object for Firestore — removes undefined fields (Firestore rejects them)
// Preserves Firestore special objects (Timestamps, FieldValues etc)
function _stripUndefined(obj) {
  if (obj === undefined) return null;
  if (obj === null || typeof obj !== "object") return obj;
  // Preserve Firestore special objects (FieldValue, Timestamp, GeoPoint etc)
  if (
    obj.constructor &&
    obj.constructor.name !== "Object" &&
    obj.constructor.name !== "Array"
  )
    return obj;
  if (Array.isArray(obj))
    return obj.map((item) =>
      item === undefined ? null : _stripUndefined(item),
    );
  const clean = {};
  for (const key of Object.keys(obj)) {
    const val = obj[key];
    if (val !== undefined) {
      clean[key] = _stripUndefined(val);
    }
  }
  return clean;
}

async function saveQuoteToFirebase(quote) {
  saveInbox();
  if (!quote || !quote.id) return;
  try {
    const FieldValue = firebase.firestore.FieldValue;
    const docRef = _fbDb.collection("shared_enquiries").doc(quote.id);

    // Read current Firestore responses (what other companies have already written)
    let firestoreResponses = [];
    try {
      const snap = await docRef.get();
      if (snap.exists) firestoreResponses = snap.data().responses || [];
    } catch (e) {}

    // Merge local responses with Firestore responses
    // Per company: newest timestamp wins — no filtering, no name matching needed
    const merged = [...firestoreResponses];
    for (const localResp of quote.responses || []) {
      const existingIdx = merged.findIndex(
        (r) => r.company === localResp.company,
      );
      if (existingIdx >= 0) {
        if ((localResp.ts || 0) >= (merged[existingIdx].ts || 0)) {
          merged[existingIdx] = localResp; // replace with newer
        }
      } else {
        merged.push(localResp); // new company — add it
      }
    }

    // Write everything back — strip undefined fields before writing (Firestore rejects them)
    const cleanQuote = _stripUndefined({
      ...quote,
      responses: merged,
      responded: merged.length > 0,
    });
    cleanQuote.updatedAt = FieldValue.serverTimestamp();
    await docRef.set(cleanQuote, { merge: true });

    const _coNames = merged.map((r) => r.company || "?").join(", ");
    console.log(
      "[Noyo] ✅ Firestore write OK:",
      quote.id,
      "| responses:",
      merged.length,
      "|",
      _coNames,
    );
    if (
      currentUser &&
      (currentUser.role === "rental" || currentUser.role === "admin_rental")
    ) {
      showToast(
        "✅ Quote sent to Firestore — customer will see it on refresh (" +
          merged.length +
          " response" +
          (merged.length !== 1 ? "s" : "") +
          " total)",
        "#15803D",
        5000,
      );
    }
  } catch (e) {
    console.error("[Noyo] ❌ saveQuoteToFirebase FAILED:", e.message);
    showToast(
      "⚠️ Quote saved locally but cloud sync failed — check connection",
      "#EF4444",
      6000,
    );
  }
}

