// ══════════════════════════════════════════════════════════════════
// ADMIN RESYNC — pushes all local quoteInbox items to shared_enquiries
// Run from console: noyoResync()  OR use the Admin button
// ══════════════════════════════════════════════════════════════════
async function noyoResync() {
  if (!currentUser || currentUser.role !== "admin") {
    console.warn("Must be logged in as admin");
    return;
  }
  if (!quoteInbox.length) {
    console.log("No enquiries in local inbox to sync");
    return;
  }
  console.log(
    `[Noyo] Syncing ${quoteInbox.length} enquiries to shared_enquiries...`,
  );
  let ok = 0,
    fail = 0;
  for (const req of quoteInbox) {
    try {
      const _rClean = _stripUndefined({ ...req, resynced: true });
      _rClean.resyncedAt = firebase.firestore.FieldValue.serverTimestamp();
      await _fbDb
        .collection("shared_enquiries")
        .doc(req.id)
        .set(_rClean, { merge: true });
      ok++;
    } catch (e) {
      fail++;
      console.error(`[Noyo] Failed to sync ${req.id}:`, e.message);
    }
  }
  console.log(`[Noyo] Resync complete: ${ok} ok, ${fail} failed`);
  if (fail > 0) {
    console.error(
      "[Noyo] → Some writes failed. Check Firebase Console → Firestore → Rules",
    );
    alert(
      `Resync: ${ok} ok, ${fail} FAILED. Check browser console for details. You need to deploy firestore.rules to Firebase Console.`,
    );
  } else {
    alert(
      `✅ Resync complete! ${ok} enquiries now in Firestore. Sarah should refresh her Quote Requests.`,
    );
  }
}
window.noyoResync = noyoResync;

