// Haversine distance in km between two [lat, lng] pairs
function _haversineKm(a, b) {
  const R = 6371;
  const dLat = ((b[0] - a[0]) * Math.PI) / 180;
  const dLng = ((b[1] - a[1]) * Math.PI) / 180;
  const x =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((a[0] * Math.PI) / 180) *
      Math.cos((b[0] * Math.PI) / 180) *
      Math.sin(dLng / 2) *
      Math.sin(dLng / 2);
  return R * 2 * Math.atan2(Math.sqrt(x), Math.sqrt(1 - x));
}

// Approximate road distance using a regionally-calibrated circuity factor.
// Validated against Google Maps for key Australian outback routes.
// Note: radius CHECKS (enquiryVisibleToCompany) still use raw Haversine for
// consistency with stored radius values. This function is for DISPLAY only.
function _roadDistKm(a, b) {
  const air = _haversineKm(a, b);
  const lat1 = a[0],
    lng1 = a[1],
    lat2 = b[0],
    lng2 = b[1];
  const midLat = (lat1 + lat2) / 2;
  const midLng = (lng1 + lng2) / 2;
  const dLng = Math.abs(lng1 - lng2);
  const dLat = Math.abs(lat1 - lat2);

  let factor = 1.28; // default — general Australian regional roads

  // ── NT highways (Stuart, Barkly, Flinders) — very straight ────────────────
  // Both points in NT or crossing NT/QLD boundary (Barkly Hwy is almost straight)
  if (midLng >= 129 && midLng <= 142 && midLat >= -27 && midLat <= -10) {
    factor = 1.15;
  }

  // ── WA inland north–south (Great Northern Hwy, North West Coastal Hwy) ────
  // Both points in WA roughly same longitude band
  else if (midLng >= 113 && midLng <= 122 && dLng < 8) {
    factor = air > 800 ? 1.2 : 1.28;
  }

  // ── QLD inland east–west highways (Capricorn, Landsborough, Flinders) ─────
  // Both points roughly same latitude, inland QLD — these highways are very direct
  else if (midLat >= -25 && midLat <= -18 && dLat < 3 && dLng > 3) {
    factor = 1.08;
  }

  // ── QLD Bowen Basin → coast (through Clarke/Connors Range) ────────────────
  // Short inland→coast hop (< 400km air), inland lng 147-149, coast lng 149.5+
  // Must check AFTER east-west highways to avoid catching Longreach→Rocky
  else if (
    air < 400 &&
    midLat >= -25 &&
    midLat <= -18 &&
    ((lng1 >= 146 && lng1 <= 149.3 && lng2 > 149.3) ||
      (lng2 >= 146 && lng2 <= 149.3 && lng1 > 149.3))
  ) {
    factor = 1.6; // Clarke/Connors Range adds significant distance
  }

  // ── SA / western NSW outback — very indirect roads ─────────────────────────
  else if (midLng >= 138 && midLng <= 146 && midLat >= -36 && midLat <= -28) {
    factor = 1.45;
  }

  // ── Coastal NSW / QLD — mostly follows Pacific Hwy, moderate bends ─────────
  else if (midLng >= 150 && midLat >= -38 && midLat <= -15) {
    factor = air < 400 ? 1.24 : 1.2;
  }

  // ── VIC / southern NSW general ────────────────────────────────────────────
  else if (midLat <= -34 && midLat >= -40 && midLng >= 140 && midLng <= 152) {
    factor = 1.3;
  }

  return Math.round(air * factor);
}

// Get city centroid — try exact match then partial match
function _getCityCentroid(cityName) {
  if (!cityName) return null;
  const key = Object.keys(CITY_CENTROIDS).find(
    (k) =>
      k.toLowerCase() === cityName.toLowerCase() ||
      cityName.toLowerCase().includes(k.toLowerCase()) ||
      k.toLowerCase().includes(cityName.toLowerCase()),
  );
  return key ? CITY_CENTROIDS[key] : null;
}

// ── Core routing function ────────────────────────────────────────────────────
// ARCHITECTURE: Customer's HOME city/suburb is IRRELEVANT to routing.
// Routing is 100% driven by the SITE SUBURB/CITY entered on the enquiry form.
// Rental companies are matched by Haversine distance from their depot to the site.
// ── Resolve the current logged-in rental user to their company record ────────
// Priority: exact email match → localStorage-registered depot data → BLOCK ALL.
// Deliberately avoids domain-based matching (e.g. @noyo.com.au would wrongly
// match the hardcoded Noyo Equipment Hire company record based in Sydney).
// CRITICAL: if no depot location can be resolved, we return a zero-radius sentinel
// so enquiries from other cities never bleed through to the wrong company.
function _resolveUserCompany() {
  if (!currentUser) return null;

  function _ruralPrefs(email, co) {
    const storedOptIn = loadAccountField(email, "ruralOptIn");
    const storedRuralKm = loadAccountField(email, "ruralRadiusKm");
    const optIn = storedOptIn === "1" || (co && co.ruralOptIn === true);
    const ruralKm = storedRuralKm
      ? parseInt(storedRuralKm, 10)
      : co && co.ruralRadiusKm
        ? co.ruralRadiusKm
        : 0;
    return { ruralOptIn: optIn, ruralRadiusKm: ruralKm };
  }

  // 1. Exact email match in RENTAL_COMPANIES (highest priority — definitive depot)
  const byEmail = RENTAL_COMPANIES.find(
    (c) => c.email && c.email.toLowerCase() === currentUser.email.toLowerCase(),
  );
  if (byEmail) {
    const storedRadius = loadAccountField(currentUser.email, "serviceRadiusKm");
    const storedSuburb = loadAccountField(currentUser.email, "suburb") || "";
    const storedCity = loadAccountField(currentUser.email, "city") || "";
    const rural = _ruralPrefs(currentUser.email, byEmail);
    if (storedRadius || storedCity || storedSuburb) {
      return {
        ...byEmail,
        ...rural,
        baseCity: storedCity || byEmail.baseCity,
        baseSuburb: storedSuburb || byEmail.baseSuburb || "",
        serviceRadiusKm: storedRadius
          ? parseInt(storedRadius, 10) || byEmail.serviceRadiusKm
          : byEmail.serviceRadiusKm,
      };
    }
    return { ...byEmail, ...rural };
  }

  // 2. Build from localStorage (self-registered rental co. via login panel)
  const city = loadAccountField(currentUser.email, "city") || "";
  const suburb = loadAccountField(currentUser.email, "suburb") || "";
  const radius =
    parseInt(
      loadAccountField(currentUser.email, "serviceRadiusKm") || "75",
      10,
    ) || 75;
  const company = loadAccountField(currentUser.email, "company") || "";
  const rural2 = {
    ruralOptIn: loadAccountField(currentUser.email, "ruralOptIn") === "1",
    ruralRadiusKm: parseInt(
      loadAccountField(currentUser.email, "ruralRadiusKm") || "0",
      10,
    ),
  };
  if (city || suburb) {
    return {
      id: "rc-" + currentUser.email.replace(/[^a-z0-9]/gi, "-"),
      name: company || currentUser.name || "",
      email: currentUser.email,
      baseCity: city,
      baseSuburb: suburb,
      serviceRadiusKm: radius,
      cities: city ? [city] : [],
      ...rural2,
    };
  }

  // 3. No usable location data — return zero-radius sentinel.
  //    This BLOCKS all enquiries rather than showing everything, preventing
  //    cross-city leakage when a rental account has not set up their depot.
  return {
    id: "rc-no-depot",
    name: currentUser.name || "",
    email: currentUser.email,
    baseCity: "",
    serviceRadiusKm: 0,
    cities: [],
  };
}

function enquiryVisibleToCompany(req, company) {
  // Withdrawn enquiries are never visible to rental companies
  if (req.withdrawn) return false;

  // Zero-radius sentinel — no depot configured, block all enquiries
  if (company.serviceRadiusKm === 0 && !company.baseCity) return false;

  const isRural = !!req.isRural;

  // ── RURAL GATE: if this is a rural enquiry, company must have opted in ──────
  if (isRural) {
    const storedOptIn = company.email
      ? loadAccountField(company.email, "ruralOptIn")
      : null;
    const optedIn = storedOptIn === "1" || company.ruralOptIn === true;
    if (!optedIn) return false;

    const storedRuralKm = company.email
      ? loadAccountField(company.email, "ruralRadiusKm")
      : null;
    const ruralRadiusKm = storedRuralKm
      ? parseInt(storedRuralKm, 10)
      : company.ruralRadiusKm || 500;

    // Resolve company depot coords once
    let depotCoord = null;
    const depotSuburb =
      company.baseSuburb ||
      (company.email && loadAccountField(company.email, "suburb")) ||
      "";
    if (depotSuburb) {
      const sr = AU_SUBURB_CITY[depotSuburb.toLowerCase().trim()];
      if (sr) depotCoord = _getCityCentroid(sr[0]);
    }
    if (!depotCoord) {
      const depotCity =
        (company.email && loadAccountField(company.email, "city")) ||
        company.baseCity ||
        (company.cities && company.cities[0]) ||
        "";
      if (!depotCity) return true;
      depotCoord = _getCityCentroid(depotCity);
      if (!depotCoord) return true;
    }

    // Multi-cluster: visible if company depot is within ruralRadiusKm of ANY selected cluster
    const selectedClusters =
      Array.isArray(req.clusters) && req.clusters.length > 0
        ? req.clusters
        : [{ city: req.city || req.cluster || "", state: req.state || "" }];

    return selectedClusters.some(function (cl) {
      const clCoord = _getCityCentroid(cl.city);
      if (!clCoord) return false;
      return _haversineKm(depotCoord, clCoord) <= ruralRadiusKm;
    });
  }

  // ── METRO GATE: normal metro/suburban routing ──────────────────────────────
  const siteCity = req.city || req.cluster || "";
  if (!siteCity) return true; // no location data — show to everyone

  const siteCoord = _getCityCentroid(siteCity);
  if (!siteCoord) return true; // unknown city — show to everyone

  // Company's metro service radius
  let radiusKm = company.serviceRadiusKm || 75;
  if (company.email) {
    const stored = loadAccountField(company.email, "serviceRadiusKm");
    if (stored) radiusKm = parseInt(stored, 10) || radiusKm;
  }

  // Company's depot — prefer suburb (more precise) then city
  let depotCoord = null;
  const depotSuburb =
    company.baseSuburb ||
    (company.email && loadAccountField(company.email, "suburb")) ||
    "";
  if (depotSuburb) {
    // Try to get suburb-level city, then use that centroid
    const suburbResult = AU_SUBURB_CITY[depotSuburb.toLowerCase().trim()];
    if (suburbResult) {
      depotCoord = _getCityCentroid(suburbResult[0]);
    }
  }
  if (!depotCoord) {
    // Fallback: use stored city or baseCity
    const depotCity =
      (company.email && loadAccountField(company.email, "city")) ||
      company.baseCity ||
      (company.cities && company.cities[0]) ||
      "";
    if (!depotCity) return true;
    depotCoord = _getCityCentroid(depotCity);
    if (!depotCoord) return true;
  }

  const distKm = _haversineKm(depotCoord, siteCoord);
  return distKm <= radiusKm;
}

function inboxAcceptQuote(reqId, responseIdx) {
  const req = quoteInbox.find((r) => r.id === reqId);
  if (!req || !req.responses[responseIdx]) return;
  const acceptedCompany = req.responses[responseIdx].company;
  (req.responses || []).forEach((r, i) => {
    if (i === responseIdx) {
      r.accepted = true;
      r.rejected = false;
    } else {
      r.rejected = true;
      r.accepted = false;
      r.autoRejected = true;
    }
  });
  req.acceptedBy = acceptedCompany;
  req.acceptedAt = Date.now();
  req.responded = true;
  saveInbox();
  saveQuoteToFirebase(req);
  renderQuoteInbox();
  renderMyQuotes();
  showToast(
    `✅ Quote from ${acceptedCompany} accepted! Others notified.`,
    "#16A34A",
  );
}

function inboxRejectQuote(reqId, responseIdx) {
  const req = quoteInbox.find((r) => r.id === reqId);
  if (!req || !req.responses[responseIdx]) return;
  req.responses[responseIdx].rejected = true;
  req.responses[responseIdx].accepted = false;
  saveInbox();
  saveQuoteToFirebase(req);
  renderQuoteInbox();
  showToast("Quote declined", "#64748B");
}

// ── Plan quota banner rendered above the RC inbox ─────────────────────
function _renderPlanBanner() {
  const el = document.getElementById("rc-plan-banner");
  if (!el) return;
  const isRcRole =
    currentUser && ["rental", "staff", "manager"].includes(currentUser.role);
  if (!isRcRole) {
    el.style.display = "none";
    return;
  }

  const p = _rcPlan();
  if (!p || !p.hasSubscription) {
    // No plan — show upgrade prompt
    el.style.display = "block";
    el.innerHTML = `
      <div style="background:linear-gradient(135deg,#0052CC,#003D99);color:#fff;border-radius:12px;padding:.9rem 1.1rem;display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap">
        <div>
          <div style="font-weight:900;font-size:.95rem;margin-bottom:.15rem">🔒 No Active Plan</div>
          <div style="font-size:.78rem;opacity:.85">Subscribe to receive and unlock enquiries from customers in your service area.</div>
        </div>
        <button onclick="openSubscribeModal()" style="background:#fff;color:#0052CC;border:none;border-radius:9px;padding:.55rem 1.2rem;font-family:'Nunito',sans-serif;font-weight:900;font-size:.85rem;cursor:pointer;white-space:nowrap">
          View Plans →
        </button>
      </div>`;
    return;
  }

  const { cfg, included, used, remaining } = p;
  const pct = Math.round((used / included) * 100);
  const barFill = Math.min(100, pct);
  const urgent = remaining <= 2;
  const barColor = urgent
    ? "#EF4444"
    : remaining <= Math.ceil(included * 0.3)
      ? "#F59E0B"
      : "#16A34A";
  const extraCost = cfg.extraPrice;

  el.style.display = "block";

  el.innerHTML = `
    <div style="background:${cfg.badge};border:1.5px solid ${urgent ? "#FCA5A5" : "#E2E8F0"};border-radius:12px;padding:.8rem 1.1rem;margin-bottom:.8rem">
      <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.5rem;margin-bottom:.5rem">
        <div style="display:flex;align-items:center;gap:.6rem">
          <span style="font-weight:900;font-size:.9rem;color:${cfg.color}">📦 ${cfg.label} Plan</span>
          <span style="font-size:.75rem;color:#64748B">$${cfg.price}/mo</span>
          ${urgent ? '<span style="background:#FEF2F2;color:#DC2626;font-size:.72rem;font-weight:800;padding:.1rem .45rem;border-radius:20px;border:1px solid #FCA5A5">⚠️ Almost out</span>' : ""}
        </div>
        <div style="display:flex;align-items:center;gap:.5rem">
          <span style="font-size:.82rem;font-weight:700;color:${remaining === 0 ? "#DC2626" : cfg.color}">${remaining} enquir${remaining === 1 ? "y" : "ies"} left</span>
          <span style="font-size:.75rem;color:#94A3B8">of ${included} this month</span>
          <button onclick="openSubscribeModal()" style="background:none;border:1.5px solid ${cfg.color};border-radius:8px;padding:.22rem .65rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.73rem;color:${cfg.color};cursor:pointer">Manage</button>
        </div>
      </div>
      <div style="background:#E2E8F0;border-radius:99px;height:6px;overflow:hidden">
        <div style="background:${barColor};width:${barFill}%;height:100%;border-radius:99px;transition:width .4s"></div>
      </div>
      ${remaining === 0 ? `<div style="margin-top:.45rem;font-size:.77rem;color:#DC2626;font-weight:700">All included enquiries used — extra enquiries $${extraCost} each. <button onclick="openExtraEnquiryModal()" style="background:none;border:none;color:#0052CC;font-weight:800;font-size:.77rem;cursor:pointer;text-decoration:underline">Top up now</button></div>` : ""}
    </div>`;
}

function renderQuoteInbox() {
  const list = document.getElementById("quote-inbox-list");
  const badge = document.getElementById("inbox-badge");
  if (!list || !badge) return;
  const pending = quoteInbox.filter((r) => !r.responded);
  if (badge) badge.textContent = pending.length;
  if (badge) badge.style.display = pending.length ? "inline" : "none";

  // ── Plan quota banner ──────────────────────────────────────────────
  _renderPlanBanner();

  if (quoteInbox.length === 0) {
    list.innerHTML =
      '<div style="padding:1.5rem;text-align:center;color:#94A3B8;font-size:.9rem">No pending enquiries.</div>';
    return;
  }

  // Determine current user's company (for cluster filtering)
  const isAdmin = currentUser && currentUser.role === "admin";
  let userCompany = null;
  if (currentUser && !isAdmin) {
    userCompany = _resolveUserCompany();
  }

  // Filter by cluster — only show relevant enquiries
  // Also: never show the current user's OWN enquiries here (they sent them as a customer)
  const currentUserEmail = (currentUser?.email || "").toLowerCase();
  const rawVisible = isAdmin
    ? [...quoteInbox].filter(
        (req) => (req.email || "").toLowerCase() !== currentUserEmail,
      )
    : [...quoteInbox].filter(
        (req) =>
          (!userCompany || enquiryVisibleToCompany(req, userCompany)) &&
          (req.email || "").toLowerCase() !== currentUserEmail,
      );

  // Sort: active+urgent first (ascending time left), then active (ascending time left), then responded, then expired
  const _now0 = Date.now();
  const visibleRequests = rawVisible.sort((a, b) => {
    const aActive = !a.responded && a.expires - _now0 > 0;
    const bActive = !b.responded && b.expires - _now0 > 0;
    const aExpired = !a.responded && a.expires - _now0 <= 0;
    const bExpired = !b.responded && b.expires - _now0 <= 0;
    const aMsLeft = a.expires - _now0;
    const bMsLeft = b.expires - _now0;
    const aUrgent =
      aActive && workingMinsRemaining(_now0, a.expires, a.state) < 120;
    const bUrgent =
      bActive && workingMinsRemaining(_now0, b.expires, b.state) < 120;

    // Tier 1: urgent active (sorted by time left ascending — most urgent first)
    if (aUrgent && !bUrgent) return -1;
    if (!aUrgent && bUrgent) return 1;
    // Tier 2: active (sorted by time left ascending)
    if (aActive && !bActive) return -1;
    if (!aActive && bActive) return 1;
    // Tier 3: responded (newest first)
    if (a.responded && bExpired) return -1;
    if (aExpired && b.responded) return 1;
    // Within same tier: sort by time left ascending (or ts descending for responded)
    if (aActive && bActive) return aMsLeft - bMsLeft;
    return (b.ts || 0) - (a.ts || 0);
  });

  if (visibleRequests.length === 0) {
    list.innerHTML =
      '<div style="padding:1.5rem;text-align:center;color:#94A3B8;font-size:.9rem">No enquiries in your service area yet.</div>';
    return;
  }

  list.innerHTML = visibleRequests
    .map((req) => {
      const now = Date.now();
      const msLeft = req.expires - now;
      // TEMPORARY — pending Stripe integration, all rental cos see customer
      // contact details on every enquiry without needing to purchase a lead.
      // Once Stripe is wired up, revert to the paid-reveal model:
      //   const isLeadPurchased = isAdmin || (req.leadsPurchased || []).includes(currentUser?.email);
      const isLeadPurchased = true;

      // Urgency — used for both timer badge and card styling
      const isActive = !req.responded && msLeft > 0;
      const isExpired = !req.responded && msLeft <= 0;
      let urgentCard = false;

      // Timer badge
      let timerHtml;
      if (req.responded) {
        timerHtml = '<span class="blind-enq-timer done">✓ Responded</span>';
      } else if (msLeft <= 0) {
        timerHtml =
          '<span class="blind-enq-timer" style="color:#94a3b8;background:#f1f5f9">Expired</span>';
      } else {
        const wMins = workingMinsRemaining(now, req.expires, req.state);
        const wHrs = Math.floor(wMins / 60),
          wMin = wMins % 60;
        const urgent = wMins < 120; // < 2 working hours
        urgentCard = urgent;
        timerHtml = `<span class="blind-enq-timer ${urgent ? "" : "ok"}">⏱ ${wHrs}h ${wMin}m working time left</span>`;
      }

      // BLINDED machine rows — show type, specs, duration only
      const machinesHtml = (req.machines || [])
        .map((m) => {
          const jr = m.jobRequirements || {};
          const specParts = [
            jr.liftHeightM && `📏 ${jr.liftHeightM}m lift`,
            jr.loadWeightKg && `⚖️ ${jr.loadWeightKg} kg`,
            jr.forwardReachM && `↔️ ${jr.forwardReachM}m reach`,
            jr.terrain && `⛰️ ${jr.terrain}`,
            jr.crewSize && `👷 ${jr.crewSize}`,
          ]
            .filter(Boolean)
            .join(" · ");
          const durLabel =
            {
              "half-day": "Half day",
              "1-day": "1 day",
              "2-3-days": "2–3 days",
              "1-week": "1 week",
              "2-weeks": "2 weeks",
              "1-month": "1 month",
              "3-months": "3 months",
              "6-months": "6 months",
              "12-months-plus": "12+ months",
            }[m.duration || ""] ||
            m.duration ||
            "";
          return `<div class="blind-machine-row">
        <div class="blind-machine-emoji">${m.emoji || "🏗️"}</div>
        <div class="blind-machine-info">
          <div class="blind-machine-name">${m.name || m.id || "Unknown machine"}</div>
          ${specParts ? `<div class="blind-machine-specs">${specParts}</div>` : ""}
          ${durLabel ? `<div class="blind-machine-dur">⏳ ${durLabel}</div>` : ""}
          ${m.tynes && m.tynes.length ? `<div style="margin-top:.3rem;display:flex;flex-wrap:wrap;gap:.25rem">${m.tynes.map((t) => `<span style="background:#EFF6FF;border:1px solid #BFDBFE;border-radius:5px;padding:.1rem .45rem;font-size:.72rem;font-weight:700;color:#1D4ED8">🔱 Tyne: ${t}</span>`).join("")}</div>` : ""}
          ${m.attachments && m.attachments.length ? `<div style="margin-top:.25rem;display:flex;flex-wrap:wrap;gap:.25rem">${m.attachments.map((a) => `<span style="background:#F0FDF4;border:1px solid #86EFAC;border-radius:5px;padding:.1rem .45rem;font-size:.72rem;font-weight:700;color:#15803D">🔧 ${a} — quote separately</span>`).join("")}</div>` : ""}
        </div>
      </div>`;
        })
        .join("");

      // Suburb + cluster — always visible
      const suburbDisplay = req.suburb || req.siteAddress || req.city || "—";
      // Calculate distance from this company's depot to the job site (for rental company view)
      let distBadge = "";
      if (!isAdmin && userCompany) {
        const depotCity =
          userCompany.baseCity ||
          (userCompany.cities && userCompany.cities[0]) ||
          "";
        const depotCoord = _getCityCentroid(depotCity);
        const siteCoord = _getCityCentroid(req.city || req.cluster || "");
        if (depotCoord && siteCoord) {
          const km = _roadDistKm(depotCoord, siteCoord); // approx road distance
          const radiusKm = userCompany.serviceRadiusKm || 75;
          const pct = Math.min(100, Math.round((km / radiusKm) * 100));
          const col =
            km <= radiusKm * 0.5
              ? "#166534"
              : km <= radiusKm * 0.8
                ? "#92400E"
                : "#991B1B";
          const bg =
            km <= radiusKm * 0.5
              ? "#DCFCE7"
              : km <= radiusKm * 0.8
                ? "#FEF3C7"
                : "#FEE2E2";
          distBadge = `<span style="background:${bg};color:${col};border-radius:20px;font-size:.72rem;font-weight:800;padding:.2rem .6rem">🚛 ~${km} km road (approx)</span>`;
        }
      }
      const suburbHtml = `<div style="margin:.6rem 0;display:flex;align-items:center;gap:.5rem;flex-wrap:wrap">
      <span class="blind-suburb">📍 ${suburbDisplay}${req.state ? ", " + req.state : ""}</span>
      ${req.city && req.city !== suburbDisplay ? `<span class="blind-enq-cluster">🏙️ ${req.city}</span>` : ""}
      ${req.isRural ? `<span style="background:linear-gradient(135deg,#FFF7ED,#FEF3C7);color:#C2410C;border:2px solid #F97316;border-radius:20px;font-size:.72rem;font-weight:800;padding:.2rem .7rem;box-shadow:0 1px 4px rgba(249,115,22,.25)">🏗️ Rural/Remote${req.clusters && req.clusters.length > 1 ? " · " + req.clusters.map((c) => c.city).join(", ") : req.ruralNearestKm ? " · ~" + req.ruralNearestKm + "km" : ""}</span>` : ""}
      ${distBadge}
    </div>`;

      // Hire start date — visible
      const dateHtml = req.date
        ? `<div style="font-size:.8rem;color:#64748b;margin-bottom:.4rem">📅 Hire start: ${req.date}</div>`
        : "";

      // LOCKED contact details section
      // TEMPORARY — pending Stripe integration. Currently `isLeadPurchased` is
      // forced to true above, so every rental co sees customer contact details
      // on every enquiry. Once Stripe is wired up, the "Lead Purchased" label
      // will be accurate again (only purchased leads unlock).
      const lockedHtml = isLeadPurchased
        ? `<div class="lead-reveal-section" style="margin:.7rem 0">
          <div style="font-size:.72rem;font-weight:800;color:#166534;text-transform:uppercase;letter-spacing:.05em;margin-bottom:.5rem">👤 Customer Contact Details</div>
          <div class="lead-reveal-row"><span class="lead-reveal-icon">👤</span><span class="lead-reveal-label">Customer</span><span class="lead-reveal-value">${req.customer}</span></div>
          ${req.company && req.company !== "—" ? `<div class="lead-reveal-row"><span class="lead-reveal-icon">🏢</span><span class="lead-reveal-label">Company</span><span class="lead-reveal-value">${req.company}</span></div>` : ""}
          <div class="lead-reveal-row"><span class="lead-reveal-icon">📧</span><span class="lead-reveal-label">Email</span><span class="lead-reveal-value" style="color:#0052cc">${req.email || "—"}</span></div>
          <div class="lead-reveal-row"><span class="lead-reveal-icon">📱</span><span class="lead-reveal-label">Mobile</span><span class="lead-reveal-value">${req.mobile || "—"}</span></div>
          ${req.siteAddress ? `<div class="lead-reveal-row"><span class="lead-reveal-icon">📍</span><span class="lead-reveal-label">Site address</span><span class="lead-reveal-value">${req.siteAddress}</span></div>` : ""}
          ${req.abn ? `<div class="lead-reveal-row"><span class="lead-reveal-icon">🔢</span><span class="lead-reveal-label">ABN</span><span class="lead-reveal-value" style="font-family:monospace">${req.abn}</span></div>` : ""}
        </div>`
        : `<div class="blind-locked-row">
          <div class="blind-locked-icon">🔒</div>
          <div class="blind-locked-text">
            <strong>Customer contact details are private</strong>
            Purchase this lead to unlock the customer's name, email, mobile, company, and full site address.
          </div>
        </div>`;

      // Actions
      // TEMPORARY — contact details now always visible at the top of the enquiry
      // card via the unlocked lockedHtml block. The gated reveal button is no
      // longer needed. Once Stripe is wired up and paid-reveal gating returns,
      // revert this to the previous `showContacts = !!myRespObj` flow.
      const contactRevealHtml = "";

      const actionsHtml = req.responded
        ? (() => {
            // If RC responded but customer made no decision and accept window has closed
            const _rcNoDecision =
              !req.acceptedBy &&
              req.customerAcceptExpires &&
              Date.now() > req.customerAcceptExpires;
            const _rcNoDecisionFresh =
              _rcNoDecision &&
              Date.now() - req.customerAcceptExpires < 5 * 24 * 3600000; // within 5 days
            const _noDecisionBanner = _rcNoDecision
              ? `<div style="margin-top:.4rem;padding:.45rem .75rem;background:${_rcNoDecisionFresh ? "#FFFBEB" : "#F8FAFC"};border:1.5px solid ${_rcNoDecisionFresh ? "#FCD34D" : "#E2E8F0"};border-radius:9px;display:flex;align-items:center;gap:.5rem">
                <span style="font-size:1rem">${_rcNoDecisionFresh ? "⏳" : "🔒"}</span>
                <div>
                  <div style="font-weight:800;color:${_rcNoDecisionFresh ? "#B45309" : "#64748B"};font-size:.78rem">${_rcNoDecisionFresh ? "Awaiting customer decision — Noyo is following up" : "No decision made"}</div>
                  <div style="font-size:.72rem;color:#94A3B8;margin-top:.1rem">${_rcNoDecisionFresh ? "The customer has not yet accepted or declined. We will contact them." : "The customer did not respond in time. This enquiry is now closed."}</div>
                </div>
              </div>`
              : "";
            return `<div style="display:flex;flex-direction:column;gap:.3rem"><div class="qrc-responded">✓ Response sent</div>${_noDecisionBanner}${contactRevealHtml}</div>`;
          })()
        : msLeft <= 0
          ? '<div style="color:#94A3B8;font-size:.82rem">Window expired</div>'
          : `<div class="qrc-actions">
            <button class="btn-broadcast" onclick="broadcastEnquiryToRentalCos('${req.id}')">📤 Broadcast to All Rental Cos</button>
            ${isLeadPurchased ? `<button class="btn-respond" onclick="openRespondModal('${req.id}')">💬 Respond with Quote</button>` : ""}
            <button class="btn-decline" onclick="declineQuote('${req.id}')">✕ Decline</button>
           </div>`;

      // Buy lead button (if not yet purchased and not admin)
      const buyLeadHtml =
        !isLeadPurchased && !isAdmin && msLeft > 0 && !req.responded
          ? `<button class="btn-buy-lead" onclick="openBuyLeadModal('${req.id}')">
           🔓 Unlock Contact Details &amp; Quote Directly
           <span class="buy-lead-price">$29</span>
         </button>`
          : "";

      const isMyAccepted =
        req.acceptedBy && req.acceptedBy === currentUser?.name;
      const isOtherAccepted =
        req.acceptedBy && req.acceptedBy !== currentUser?.name;

      // Show my rating if this hire has been rated
      const myRating =
        (req.responses || []).find((r) => r.company === currentUser?.name) &&
        req._ratedRental
          ? (() => {
              const s = getCompanyRatingSummary(currentUser?.name);
              return s && s.count > 0
                ? `<div style="background:#FFFBEB;border:1px solid #FDE68A;border-radius:8px;padding:.4rem .7rem;font-size:.78rem;margin:.4rem 0;display:flex;align-items:center;gap:.6rem;flex-wrap:wrap">
            <span style="font-weight:700;color:#92400E">⭐ Customer rated this hire:</span>
            <span style="font-weight:800;color:#B45309">${req._ratedRental.toFixed?.(1) || req._ratedRental}/5</span>
          </div>`
                : "";
            })()
          : "";

      return `<div class="blind-enquiry-card" style="${
        isMyAccepted
          ? "border:2px solid #86EFAC;background:linear-gradient(135deg,#F0FDF4,#fff)"
          : urgentCard
            ? "border:2.5px solid #EF4444;background:linear-gradient(135deg,#FFF5F5,#fff);box-shadow:0 4px 20px rgba(239,68,68,.18)"
            : isActive
              ? "border:1.5px solid #FCD34D;background:linear-gradient(135deg,#FFFBEB,#fff)"
              : isOtherAccepted
                ? "opacity:.65"
                : ""
      }">
      ${
        urgentCard
          ? `<div style="background:#EF4444;color:#fff;padding:.45rem 1rem;border-radius:10px 10px 0 0;margin:-.05rem;font-size:.82rem;font-weight:800;display:flex;align-items:center;gap:.5rem">
        <span>🚨</span> Urgent — response window closing soon. Act now to send a quote.
      </div>`
          : isActive && !urgentCard
            ? `<div style="background:#F59E0B;color:#fff;padding:.35rem 1rem;border-radius:10px 10px 0 0;margin:-.05rem;font-size:.78rem;font-weight:800;display:flex;align-items:center;gap:.4rem">
        <span>⏳</span> Active enquiry — awaiting your response.
      </div>`
            : ""
      }
      ${
        isMyAccepted
          ? `<div style="background:#16A34A;color:#fff;padding:.5rem 1rem;border-radius:10px 10px 0 0;margin:-.05rem;font-size:.82rem;font-weight:800;display:flex;align-items:center;gap:.5rem">
        <span>🎉</span> Hire accepted by customer! Contact them to arrange delivery.
        <span style="margin-left:auto;font-size:.75rem;opacity:.85">${req.customer || ""} · ${req.mobile || req.email || ""}</span>
      </div>`
          : ""
      }
      ${
        isOtherAccepted
          ? `<div style="background:#F1F5F9;padding:.4rem 1rem;border-radius:10px 10px 0 0;font-size:.78rem;font-weight:700;color:#64748B">
        ✕ Another company's quote was accepted for this job
      </div>`
          : ""
      }
      <div class="blind-enq-header">
        <div style="display:flex;align-items:center;gap:.6rem;flex-wrap:wrap">
          <span class="blind-enq-ref">${req.id}</span>
          ${req.cluster ? `<span class="blind-enq-cluster">📍 ${req.cluster}</span>` : ""}
          ${req.date ? `<span style="font-size:.82rem;color:#334155;font-weight:700;background:#F0FDF4;border:1px solid #86EFAC;border-radius:8px;padding:.2rem .6rem">📅 Hire start: ${req.date}</span>` : ""}
          ${req.ts ? `<span style="font-size:.75rem;color:#94a3b8">Received ${new Date(req.ts).toLocaleDateString("en-AU", { day: "2-digit", month: "short", year: "numeric" })} at ${new Date(req.ts).toLocaleTimeString("en-AU", { hour: "2-digit", minute: "2-digit" })}</span>` : ""}
        </div>
        ${timerHtml}
      </div>
      ${machinesHtml}
      ${suburbHtml}
      ${lockedHtml}
      ${buyLeadHtml}
      ${req.notes ? `<div style="font-size:.82rem;color:#475569;margin:.5rem 0;font-style:italic;padding:.5rem .7rem;background:#f8fafc;border-radius:8px;border-left:3px solid #e2e8f0">"${req.notes}"</div>` : ""}
      ${req.broadcastSent ? `<div class="broadcast-sent-badge">📤 Broadcast to ${req.broadcastCount || 0} compan${req.broadcastCount === 1 ? "y" : "ies"} · ${req.broadcastAt || ""}</div>` : ""}
      ${actionsHtml}
      ${(() => {
        // Responses section with click-to-expand breakdown and accept/reject
        const resps = req.responses || [];
        if (resps.length === 0) return "";
        const nums2 = resps
          .map((r) =>
            parseFloat(
              String(r.grandTotal || r.price || "").replace(/[^0-9.]/g, ""),
            ),
          )
          .filter((n) => !isNaN(n));
        const minP2 = nums2.length ? Math.min(...nums2) : 0;
        return `<div style="margin-top:.9rem;border-top:2px solid #E2E8F0;padding-top:.8rem">
          <div style="font-size:.72rem;font-weight:800;color:#64748B;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.6rem">💬 Responses (${resps.length})</div>
          ${resps
            .map((p, ri) => {
              const pNum = parseFloat(
                String(p.grandTotal || p.price || "").replace(/[^0-9.]/g, ""),
              );
              const isLow = !isNaN(pNum) && pNum === minP2 && nums2.length > 1;
              const isAcc = p.accepted === true;
              const isRej = p.rejected === true || p.autoRejected === true;
              const isPartial = p.partial === true;
              const cid = `inb-resp-${(req.id || "x").replace(/[^a-z0-9]/gi, "")}-${ri}`;

              // Per-machine breakdown
              let detail = "";
              if (p.machineBreakdowns && p.machineBreakdowns.length) {
                detail = `<div id="${cid}-detail" style="display:none;margin-top:.6rem;padding-top:.6rem;border-top:1px solid #E2E8F0;font-size:.79rem">
                ${(p.machineBreakdowns || [])
                  .map(
                    (mb) => `
                  <div style="margin-bottom:.45rem;padding-bottom:.45rem;border-bottom:1px dashed #F1F5F9">
                    <div style="font-weight:700;color:#334155;margin-bottom:.15rem">${mb.emoji || "🏗️"} ${mb.name} <span style="font-weight:400;color:#94A3B8">(${DUR_LABEL[mb.duration] || mb.duration || "—"})</span></div>
                    <div style="display:grid;grid-template-columns:1fr auto;gap:.1rem .5rem;color:#475569">
                      <span>${mb.rateHour ? `$${mb.rateHour}/hr` : `$${mb.rateDay || 0}/day · $${mb.rateWeek || 0}/wk`}</span><span></span>
                      <span>Hire total</span><span style="font-weight:700;text-align:right">$${(mb.rentalCost || 0).toFixed(2)}</span>
                      ${(mb.accs || []).map((a) => `<span style="color:#C2410C">↳ ${a.name}${a.oneTime ? ' <span style=\"font-size:.72rem;font-weight:700;background:#DCFCE7;color:#15803D;border-radius:4px;padding:.05rem .3rem\">one-time</span>' : ""}</span><span style="font-weight:700;text-align:right;color:#C2410C">$${(a.total || 0).toFixed(2)}</span>`).join("")}
                      ${mb.insurance > 0 ? `<span style="color:#64748B">Insurance (${p.insurePct || 0}%)</span><span style="font-weight:700;text-align:right">$${(mb.insurance || 0).toFixed(2)}</span>` : ""}
                      ${(mb.transIn || 0) + (mb.transOut || 0) > 0 ? `<span style="color:#1E40AF">🚚 Transport</span><span style="font-weight:700;text-align:right;color:#1E40AF">$${((mb.transIn || 0) + (mb.transOut || 0)).toFixed(2)}</span>` : ""}
                    </div>
                  </div>`,
                  )
                  .join("")}
                <div style="display:grid;grid-template-columns:1fr auto;gap:.12rem .5rem;font-size:.82rem;border-top:1.5px solid #0052CC;padding-top:.35rem">
                  <span style="color:#64748B">Subtotal excl. GST</span><span style="font-weight:700;text-align:right">$${(p.beforeGST || 0).toFixed(2)}</span>
                  <span style="color:#64748B">GST (10%)</span><span style="font-weight:700;text-align:right">$${(p.gst || 0).toFixed(2)}</span>
                  <span style="font-weight:900;color:#0052CC">Total inc. GST</span><span style="font-weight:900;color:#0052CC;text-align:right">$${(!isNaN(pNum) ? pNum : 0).toFixed(2)}</span>
                </div>
              </div>`;
              }

              // Accept/Reject buttons — only unlocked after the quote window has closed
              const _inbWindowOpen = req.expires && Date.now() <= req.expires;
              let actBtns = "";
              if (isAcc) {
                actBtns = `<span style="background:#DCFCE7;color:#166534;font-size:.75rem;font-weight:800;padding:.25rem .7rem;border-radius:20px;margin-top:.5rem;display:inline-block">✅ Accepted by Customer</span>`;
              } else if (isRej) {
                actBtns = `<span style="background:#F1F5F9;color:#94A3B8;font-size:.75rem;font-weight:800;padding:.25rem .7rem;border-radius:20px;margin-top:.5rem;display:inline-block">${p.autoRejected ? "✗ Auto-rejected" : "✗ Declined by Customer"}</span>`;
              } else if (!req.acceptedBy) {
                if (_inbWindowOpen) {
                  actBtns = `<div style="margin-top:.45rem;padding:.3rem .65rem;background:#FFF7ED;border:1px solid #FCD34D;border-radius:7px;font-size:.75rem;color:#B45309;font-weight:700">⏳ Window open — accept options unlock once the quote window closes</div>`;
                } else {
                  actBtns = `<div style="display:flex;gap:.4rem;margin-top:.55rem">
                  <button onclick="inboxAcceptQuote('${req.id}',${ri})" style="flex:1;background:#16A34A;color:#fff;border:none;border-radius:7px;padding:.38rem .7rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.8rem;cursor:pointer">✅ Accept</button>
                  <button onclick="inboxRejectQuote('${req.id}',${ri})" style="flex:1;background:#F1F5F9;color:#64748B;border:none;border-radius:7px;padding:.38rem .7rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.8rem;cursor:pointer">✗ Decline</button>
                </div>`;
                }
              }

              return `<div style="background:${isAcc ? "#F0FDF4" : isRej ? "#F8FAFC" : isPartial ? "#FFFBEB" : "#fff"};border:1.5px solid ${isAcc ? "#86EFAC" : isRej ? "#E2E8F0" : isPartial ? "#F59E0B" : isLow ? "#BFDBFE" : "#E2E8F0"};border-radius:10px;padding:.7rem .85rem;margin-bottom:.45rem">
              <div style="cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:.5rem" onclick="var d=document.getElementById('${cid}-detail');var t=document.getElementById('${cid}-tog');if(d){d.style.display=d.style.display==='none'?'block':'none';if(t)t.textContent=d.style.display==='none'?'▶ View':'▼ Hide'}">
                <div style="font-weight:800;color:#334155;font-size:.9rem">🏢 ${p.company || "Rental Co."}${isPartial ? ' <span style="background:#FEF3C7;color:#92400E;font-size:.68rem;padding:.1rem .45rem;border-radius:20px;font-weight:800;margin-left:.3rem;vertical-align:middle">⚠️ Partial</span>' : ""}${isLow && nums2.length > 1 ? ' <span style="background:#DCFCE7;color:#15803D;font-size:.68rem;padding:.1rem .4rem;border-radius:20px;font-weight:700;margin-left:.3rem">Lowest</span>' : ""}</div>
                <div style="display:flex;align-items:center;gap:.5rem">
                  <span style="font-weight:900;color:${isAcc ? "#16A34A" : isPartial ? "#B45309" : "#0052CC"};font-size:1rem">$${(!isNaN(pNum) ? pNum : 0).toFixed(2)} <span style="font-size:.72rem;opacity:.7">inc. GST</span></span>
                  <span id="${cid}-tog" style="font-size:.71rem;color:#64748B;white-space:nowrap">▶ View</span>
                </div>
              </div>
              ${
                isPartial
                  ? `<div style="margin-top:.4rem;padding:.45rem .7rem;background:#FEF3C7;border:1px solid #F59E0B;border-radius:8px;font-size:.77rem;color:#78350F;line-height:1.5">
                <span style="font-weight:800">⚠️ Partial quote</span> — covers <strong>${(p.quotedMachines || []).length} of ${req.machines.length}</strong> machines requested.<br>
                <span style="color:#15803D;font-weight:700">✅ Quoted:</span> ${(p.quotedMachines || []).join(", ") || "—"} &nbsp;·&nbsp; <span style="color:#DC2626;font-weight:700">✗ Not quoted:</span> ${(p.notQuotedMachines || []).join(", ") || "—"}
              </div>`
                  : ""
              }
              ${p.notes && !isPartial ? `<div style="font-size:.77rem;color:#64748B;margin-top:.2rem;font-style:italic">"${p.notes}"</div>` : ""}
              ${p.notes && isPartial ? `<div style="font-size:.77rem;color:#64748B;margin-top:.3rem;font-style:italic">"${(p.notes || "").split("\n\n").slice(1).join("\n\n").trim() || ""}"</div>` : ""}
              ${p.altMachine ? `<div style="margin-top:.3rem;font-size:.77rem;background:#FFF7ED;border:1px solid #FCD34D;border-radius:7px;padding:.3rem .6rem;color:#92400E;font-weight:700">🔄 Offering: ${p.altMachine}${p.altType && p.altType !== "exact" ? " (" + (p.altType === "equivalent" ? "equivalent" : p.altType === "upgraded" ? "upgraded" : p.altType) + ")" : ""}</div>` : ""}
              ${
                p.question
                  ? `<div style="margin-top:.35rem;padding:.45rem .7rem;background:#EFF6FF;border:1px solid #93C5FD;border-radius:8px;font-size:.77rem">
                <div style="font-weight:800;color:#1E40AF;margin-bottom:.15rem">❓ Your question to customer</div>
                <div style="color:#334155;font-style:italic">"${p.question}"</div>
                ${p.customerAnswer ? `<div style="margin-top:.3rem;padding:.3rem .55rem;background:#DCFCE7;border-radius:6px;font-size:.76rem;font-weight:700;color:#166534">✅ Customer answered: "${p.customerAnswer}"</div>` : `<div style="margin-top:.25rem;font-size:.73rem;color:#64748B;font-style:italic">⏳ Awaiting customer response…</div>`}
              </div>`
                  : ""
              }
              ${detail}
              ${actBtns}
            </div>`;
            })
            .join("")}
          ${nums2.length > 1 ? `<div style="background:#EFF6FF;border:1px solid #BFDBFE;border-radius:8px;padding:.4rem .8rem;font-size:.77rem;color:#1D4ED8">💡 Range: <strong>$${Math.min(...nums2).toFixed(2)}</strong> – <strong>$${Math.max(...nums2).toFixed(2)}</strong></div>` : ""}
        </div>`;
      })()}
    </div>`;
    })
    .join("");
}

var _respondingId = null;
// ── Duration helpers ─────────────────────────────────────────
var DUR_MAP = {
  "half-day": 0.5,
  "1-day": 1,
  "2-3-days": 2.5,
  "1-week": 5,
  "2-weeks": 10,
  "1-month": 22,
  "3-months": 66,
  "6-months": 132,
  "12-months-plus": 260,
};
var DUR_LABEL = {
  "half-day": "Half day",
  "1-day": "1 day",
  "2-3-days": "2–3 days",
  "1-week": "1 week",
  "2-weeks": "2 weeks",
  "1-month": "1 month",
  "3-months": "3 months",
  "6-months": "6 months",
  "12-months-plus": "12+ months",
};

function rqDays(dur) {
  return DUR_MAP[dur] || 1;
}

function rqCalcMachineTotal(idx) {
  const m = window._rqReq ? window._rqReq.machines[idx] || {} : {};
  const jr = m.jobRequirements || m.jobRequirements || {};
  const isEarth = !!jr._isEarthworks;
  const days = rqDays(m.duration || "1-day");
  const rateHour =
    parseFloat(document.getElementById(`rq-rate-hour-${idx}`)?.value) || 0;
  const rateDay =
    parseFloat(document.getElementById(`rq-rate-day-${idx}`)?.value) || 0;
  const rateWeek =
    parseFloat(document.getElementById(`rq-rate-week-${idx}`)?.value) || 0;
  const transIn =
    parseFloat(document.getElementById(`rq-trans-in-${idx}`)?.value) || 0;
  const transOut =
    parseFloat(document.getElementById(`rq-trans-out-${idx}`)?.value) || 0;
  const insurePct =
    parseFloat(document.getElementById("rq-insurance-pct")?.value) || 0;

  // Rental cost: earthworks uses hourly (8h/day) or day rate; lifting uses day/week
  let rentalCost = 0;
  if (isEarth) {
    if (rateDay > 0) rentalCost = days * rateDay;
    else if (rateHour > 0) rentalCost = days * 8 * rateHour; // 8 hour day
  } else {
    if (days >= 5 && rateWeek > 0) rentalCost = (days / 5) * rateWeek;
    else if (rateDay > 0) rentalCost = days * rateDay;
    else if (rateWeek > 0) rentalCost = (days / 5) * rateWeek;
  }

  // Accessories — use day rate or weekly rate prorated
  let accTotal = 0;
  document.querySelectorAll(`[data-acc-machine="${idx}"]`).forEach((row) => {
    const rDay = parseFloat(row.querySelector(".acc-rate-day")?.value) || 0;
    const rWeek = parseFloat(row.querySelector(".acc-rate-week")?.value) || 0;
    let amt = 0;
    if (days >= 5 && rWeek > 0) amt = (days / 5) * rWeek;
    else if (rDay > 0) amt = days * rDay;
    else if (rWeek > 0) amt = (days / 5) * rWeek;
    accTotal += amt;
  });

  const hireTotal = rentalCost + accTotal;
  // Insurance on HIRE ONLY (not transport)
  const insurance = hireTotal * (insurePct / 100);
  const transport = transIn + transOut;
  const subtotalBeforeGST = hireTotal + insurance + transport;

  // Update per-machine breakdown
  const bd = document.getElementById(`rq-breakdown-${idx}`);
  if (bd) {
    const durLbl = DUR_LABEL[m.duration || "1-day"] || "";
    const usedRate =
      days >= 5 && rateWeek > 0
        ? `${(days / 5).toFixed(1)} wks × $${rateWeek}/wk`
        : rateDay > 0
          ? `${days} day${days !== 1 ? "s" : ""} × $${rateDay}/day`
          : rateWeek > 0
            ? `${(days / 5).toFixed(1)} wks × $${rateWeek}/wk`
            : "";

    // Individual accessory lines
    let accLines = "";
    document.querySelectorAll(`[data-acc-machine="${idx}"]`).forEach((row) => {
      const name = row.querySelector(".acc-name")?.value?.trim() || "Accessory";
      const rDay = parseFloat(row.querySelector(".acc-rate-day")?.value) || 0;
      const rWeek = parseFloat(row.querySelector(".acc-rate-week")?.value) || 0;
      let amt = 0,
        rateStr = "";
      if (days >= 5 && rWeek > 0) {
        amt = (days / 5) * rWeek;
        rateStr = `${(days / 5).toFixed(1)}wks×$${rWeek}`;
      } else if (rDay > 0) {
        amt = days * rDay;
        rateStr = `${days}d×$${rDay}`;
      } else if (rWeek > 0) {
        amt = (days / 5) * rWeek;
        rateStr = `${(days / 5).toFixed(1)}wks×$${rWeek}`;
      }
      if (amt > 0)
        accLines += `<span style="color:#C2410C;padding-left:.6rem">↳ ${name} (${rateStr})</span><span style="font-weight:700;text-align:right;color:#C2410C">$${amt.toFixed(2)}</span>`;
    });

    bd.innerHTML =
      rentalCost === 0 && accTotal === 0
        ? '<div style="font-size:.77rem;color:#94A3B8">Enter a rate above to see breakdown</div>'
        : `<div style="display:grid;grid-template-columns:1fr auto;gap:.2rem .8rem;font-size:.79rem">
        <span style="color:#475569">${durLbl} hire${usedRate ? " (" + usedRate + ")" : ""}</span><span style="font-weight:700;text-align:right">$${rentalCost.toFixed(2)}</span>
        ${accLines}
        ${insurance > 0 ? `<span style="color:#64748B">Insurance (${insurePct}%)</span><span style="font-weight:700;text-align:right">$${insurance.toFixed(2)}</span>` : ""}
        ${transIn + transOut > 0 ? `<span style="color:#1E40AF">🚚 Transport In</span><span style="font-weight:700;text-align:right;color:#1E40AF">$${transIn.toFixed(2)}</span>` : ""}
        ${transIn + transOut > 0 ? `<span style="color:#1E40AF">🚚 Transport Out</span><span style="font-weight:700;text-align:right;color:#1E40AF">$${transOut.toFixed(2)}</span>` : ""}
        <span style="font-weight:800;color:#0052CC;border-top:1px solid #E2E8F0;padding-top:.2rem;margin-top:.05rem">Machine subtotal</span>
        <span style="font-weight:900;color:#0052CC;text-align:right;border-top:1px solid #E2E8F0;padding-top:.2rem;margin-top:.05rem">$${subtotalBeforeGST.toFixed(2)}</span>
      </div>`;
  }
  return {
    rentalCost,
    accTotal,
    hireTotal,
    insurance,
    transIn,
    transOut,
    transport,
    subtotalBeforeGST,
  };
}

function rqAccRowCalc(inputEl) {
  // Find the parent row and machine index to get days
  const row = inputEl.closest("[data-acc-machine]");
  if (!row) return;
  const machineIdx = parseInt(row.getAttribute("data-acc-machine"), 10);
  const m = window._rqReq?.machines[machineIdx];
  if (!m) return;
  const days = rqDays(m.duration || "1-day");
  const rDay = parseFloat(row.querySelector(".acc-rate-day")?.value) || 0;
  const rWeek = parseFloat(row.querySelector(".acc-rate-week")?.value) || 0;
  let total = 0;
  if (days >= 5 && rWeek > 0) total = (days / 5) * rWeek;
  else if (rDay > 0) total = days * rDay;
  else if (rWeek > 0) total = (days / 5) * rWeek;
  const totalEl = row.querySelector(".acc-row-total");
  if (totalEl) totalEl.textContent = total > 0 ? `$${total.toFixed(2)}` : "$—";
}

function rqRefreshAllAccRowTotals() {
  if (!window._rqReq) return;
  window._rqReq.machines.forEach((m, i) => {
    const days = rqDays(m.duration || "1-day");
    document.querySelectorAll(`[data-acc-machine="${i}"]`).forEach((row) => {
      const rDay = parseFloat(row.querySelector(".acc-rate-day")?.value) || 0;
      const rWeek = parseFloat(row.querySelector(".acc-rate-week")?.value) || 0;
      let total = 0;
      if (days >= 5 && rWeek > 0) total = (days / 5) * rWeek;
      else if (rDay > 0) total = days * rDay;
      else if (rWeek > 0) total = (days / 5) * rWeek;
      const totalEl = row.querySelector(".acc-row-total");
      if (totalEl)
        totalEl.textContent = total > 0 ? `$${total.toFixed(2)}` : "$—";
    });
  });
}

function rqRecalcAll() {
  if (!window._rqReq) return;
  rqRefreshAllAccRowTotals(); // update per-row subtotals
  const insurePct =
    parseFloat(document.getElementById("rq-insurance-pct")?.value) || 0;

  let totalHire = 0,
    totalInsurance = 0,
    totalSubBeforeGST = 0,
    totalAccOnly = 0,
    totalTransport = 0;
  let transInTotal = 0,
    transOutTotal = 0;
  window._rqReq.machines.forEach((m, i) => {
    const r = rqCalcMachineTotal(i);
    totalHire += r.hireTotal;
    totalInsurance += r.insurance;
    totalSubBeforeGST += r.subtotalBeforeGST;
    totalAccOnly += r.accTotal;
    totalTransport += r.transport;
    transInTotal += r.transIn;
    transOutTotal += r.transOut;
  });
  window._rqTotalsAccTotal = totalAccOnly;

  const beforeGST = totalSubBeforeGST;
  const gst = beforeGST * 0.1;
  const grandTotal = beforeGST + gst;

  const gt = document.getElementById("rq-grand-total");
  if (gt)
    gt.innerHTML = `
    <div style="font-size:.72rem;font-weight:800;opacity:.75;margin-bottom:.55rem;letter-spacing:.5px;text-transform:uppercase">Quote Total</div>
    <div style="display:grid;grid-template-columns:1fr auto;gap:.25rem .8rem;font-size:.85rem;margin-bottom:.55rem">
      <span style="opacity:.9">Total Hire (all machines)</span><span style="font-weight:700;text-align:right">$${(totalHire - totalAccOnly).toFixed(2)}</span>
      ${totalAccOnly > 0 ? `<span style="opacity:.9">Total Accessories</span><span style="font-weight:700;text-align:right">$${totalAccOnly.toFixed(2)}</span>` : ""}
      ${totalInsurance > 0 ? `<span style="opacity:.9">Insurance levy (${insurePct}%)</span><span style="font-weight:700;text-align:right">$${totalInsurance.toFixed(2)}</span>` : ""}
      ${transInTotal > 0 ? `<span style="opacity:.9">🚚 Transport In (all machines)</span><span style="font-weight:700;text-align:right">$${transInTotal.toFixed(2)}</span>` : ""}
      ${transOutTotal > 0 ? `<span style="opacity:.9">🚚 Transport Out (all machines)</span><span style="font-weight:700;text-align:right">$${transOutTotal.toFixed(2)}</span>` : ""}
      <span style="opacity:.75;font-size:.8rem">Subtotal (excl. GST)</span><span style="font-weight:700;text-align:right;font-size:.8rem;opacity:.85">$${beforeGST.toFixed(2)}</span>
      <span style="opacity:.9;background:rgba(255,255,255,.1);padding:.15rem .4rem;border-radius:5px">GST (10%)</span><span style="font-weight:800;text-align:right;background:rgba(255,255,255,.1);padding:.15rem .4rem;border-radius:5px">$${gst.toFixed(2)}</span>
    </div>
    <div style="display:flex;justify-content:space-between;align-items:baseline;border-top:2px solid rgba(255,255,255,.35);padding-top:.55rem">
      <span style="font-size:1rem;font-weight:800">💰 TOTAL inc. GST</span>
      <span style="font-size:1.5rem;font-weight:900">$${grandTotal.toFixed(2)}</span>
    </div>`;

  window._rqTotals = {
    totalHire,
    totalInsurance,
    totalTransport,
    transInTotal,
    transOutTotal,
    beforeGST,
    gst,
    grandTotal,
    insurePct,
  };
}

function rqAddAccessory(machineIdx) {
  const container = document.getElementById(`rq-acc-list-${machineIdx}`);
  if (!container) return;
  const row = document.createElement("div");
  row.setAttribute("data-acc-machine", machineIdx);
  row.style.cssText =
    "background:#fff;border:1.5px solid #FCA572;border-radius:9px;padding:.55rem .7rem;margin-top:.45rem";
  // Get days for this machine
  const _mAcc = window._rqReq?.machines[machineIdx];
  const _dAcc = _mAcc ? rqDays(_mAcc.duration || "1-day") : 1;
  const _durAccLbl = _mAcc ? DUR_LABEL[_mAcc.duration || "1-day"] || "" : "";
  row.innerHTML = `
    <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.4rem">
      <span style="font-size:.9rem">🔧</span>
      <input class="acc-name" type="text" placeholder="Accessory name (e.g. Jib Attachment)" oninput="rqRecalcAll()"
        style="flex:1;border:1.5px solid #FCA572;border-radius:7px;padding:.28rem .5rem;font-size:.84rem;font-family:inherit;background:#FFF7ED;color:#334155;font-weight:600">
      <button onclick="this.closest('[data-acc-machine]').remove();rqRecalcAll()" style="background:none;border:none;color:#EF4444;font-size:.9rem;cursor:pointer;padding:0;flex-shrink:0">✕</button>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr auto;gap:.35rem;align-items:end">
      <div>
        <div style="font-size:.67rem;font-weight:800;color:#92400E;margin-bottom:.18rem">Hire Rate / Day ($)</div>
        <input class="acc-rate-day" type="number" min="0" step="1" placeholder="e.g. 120" oninput="rqRecalcAll();rqAccRowCalc(this)"
          style="width:100%;border:1.5px solid #FCA572;border-radius:7px;padding:.32rem .45rem;font-size:.9rem;font-weight:700;font-family:inherit;box-sizing:border-box;text-align:center">
      </div>
      <div>
        <div style="font-size:.67rem;font-weight:800;color:#92400E;margin-bottom:.18rem">Hire Rate / Week ($)</div>
        <input class="acc-rate-week" type="number" min="0" step="1" placeholder="e.g. 550" oninput="rqRecalcAll();rqAccRowCalc(this)"
          style="width:100%;border:1.5px solid #FCA572;border-radius:7px;padding:.32rem .45rem;font-size:.9rem;font-weight:700;font-family:inherit;box-sizing:border-box;text-align:center">
      </div>
      <div style="text-align:right;min-width:80px">
        <div style="font-size:.67rem;font-weight:800;color:#92400E;margin-bottom:.18rem">Hire Total</div>
        <div class="acc-row-total" style="font-size:.95rem;font-weight:900;color:#C2410C;padding:.3rem .4rem;background:#FFF7ED;border-radius:7px;text-align:center">$—</div>
      </div>
    </div>
    <div style="margin-top:.3rem;font-size:.71rem;color:#92400E;opacity:.75">${_dAcc} working day${_dAcc !== 1 ? "s" : ""} @ ${_durAccLbl} — system uses best rate (day or week)</div>`;
  container.appendChild(row);
}

function rqAccOneTimeCalc(inp) {
  const row = inp.closest("[data-acc-machine]");
  if (!row) return;
  const val = parseFloat(inp.value) || 0;
  const totalEl = row.querySelector(".acc-row-total");
  if (totalEl) totalEl.textContent = val > 0 ? `$${val.toFixed(2)}` : "$—";
}

function openRespondModal(reqId) {
  _respondingId = reqId;
  const req = quoteInbox.find((r) => r.id === reqId);
  if (!req) return;
  window._rqReq = req;
  window._rqTotals = null;

  // Summary — first name, suburb, hire start, sent time only
  const firstName = (req.customer || "").split(" ")[0] || "Customer";
  const suburb =
    req.suburb || (req.siteAddress || "").split(",")[0].trim() || "—";
  const state = req.state || "";
  const sentStr = req.ts
    ? new Date(req.ts).toLocaleDateString("en-AU", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      }) +
      " at " +
      new Date(req.ts).toLocaleTimeString("en-AU", {
        hour: "2-digit",
        minute: "2-digit",
      })
    : "—";
  document.getElementById("respond-quote-summary").innerHTML =
    `<strong>👤 ${firstName}</strong> &nbsp;·&nbsp; 📍 ${suburb}${state ? ", " + state : ""} &nbsp;·&nbsp; 📅 Hire start: ${req.date || "—"} &nbsp;·&nbsp; Sent: ${sentStr}`;

  // ── CUSTOMER REQUIREMENTS PANEL ───────────────────────────────────────
  // Build a full breakdown of every answer the customer gave — shown to RC
  const _allJR = (req.machines || []).map((m) => m.jobRequirements || {});
  const _jr0 = _allJR[0] || {};

  function _reqPill(icon, label, val, style) {
    if (!val) return "";
    const s =
      style || "background:#EFF6FF;border:1.5px solid #BFDBFE;color:#1E40AF";
    return `<div style="${s};border-radius:8px;padding:.32rem .65rem;display:inline-flex;align-items:center;gap:.35rem;font-size:.78rem;font-weight:700;white-space:nowrap"><span>${icon}</span><span style="color:#64748B;font-weight:600">${label}:</span><span>${val}</span></div>`;
  }
  function _reqPillWarn(icon, label, val) {
    return _reqPill(
      icon,
      label,
      val,
      "background:#FEF3C7;border:1.5px solid #FCD34D;color:#92400E",
    );
  }
  function _reqPillGreen(icon, label, val) {
    return _reqPill(
      icon,
      label,
      val,
      "background:#F0FDF4;border:1.5px solid #86EFAC;color:#15803D",
    );
  }
  function _reqPillRed(icon, label, val) {
    return _reqPill(
      icon,
      label,
      val,
      "background:#FEF2F2;border:1.5px solid #FCA5A5;color:#991B1B",
    );
  }

  // Gather all pills across all machines (deduplicate by value)
  const _seen = new Set();
  function _pill(icon, label, val, type) {
    const key = label + val;
    if (!val || _seen.has(key)) return "";
    _seen.add(key);
    return type === "warn"
      ? _reqPillWarn(icon, label, val)
      : type === "red"
        ? _reqPillRed(icon, label, val)
        : type === "green"
          ? _reqPillGreen(icon, label, val)
          : _reqPill(icon, label, val);
  }

  // Combine jobRequirements across all machines
  const _mergedJR = Object.assign({}, ..._allJR);

  const _pillRows = [
    // ── What they're lifting ──────────────────────────────────
    _pill("🏗️", "Lifting for", _mergedJR.liftingFor),
    _pill("👷", "Crew on platform", _mergedJR.crewSize),
    _pill(
      "⚖️",
      "Load weight",
      _mergedJR.loadWeightKg
        ? _mergedJR.loadWeightKg.toLocaleString() + " kg"
        : null,
    ),
    _pill("📦", "Load type", _mergedJR.loadType),
    _pill("⚖️", "Basket SWL", _mergedJR.basketSWL),
    // ── Height & reach ────────────────────────────────────────
    _pill(
      "📏",
      "Platform height",
      _mergedJR.liftHeightM ? _mergedJR.liftHeightM + " m" : null,
    ),
    _pill(
      "↔️",
      "Horizontal reach",
      _mergedJR.forwardReachM ? _mergedJR.forwardReachM + " m" : null,
    ),
    _pill("↔️", "Boom reach", _mergedJR.boomHorizontalReach),
    _pill(
      "📐",
      "Obstacle height",
      _mergedJR.obstacleHeightM ? _mergedJR.obstacleHeightM + " m" : null,
    ),
    _pill("🎯", "Access type", _mergedJR.accessType),
    // ── Site & terrain ────────────────────────────────────────
    _pill("⛰️", "Terrain", _mergedJR.terrain),
    _pill("📍", "Location", _mergedJR.siteLocation || _mergedJR.indoorOutdoor),
    _pill(
      "⚡",
      "Power source",
      _mergedJR.scissorPower ||
        _mergedJR.boomPower ||
        _mergedJR.forkPowerPreference,
    ),
    _pill("🚗", "Drive at height", _mergedJR.driveAtHeight),
    _pill("🔄", "Rotation required", _mergedJR.rotationRequired),
    // ── Attachments ───────────────────────────────────────────
    _pill("🔩", "Attachments", _mergedJR.attachmentsRequired),
    _pill(
      "🔌",
      "Power to basket",
      _mergedJR.powerToBasketRequired ? "Yes — 240V outlet required" : null,
      "green",
    ),
    // ── Machine constraints (warnings) ────────────────────────
    _mergedJR.maxMachineWeightKg
      ? _reqPillWarn("⚠️", "Max machine weight", _mergedJR.maxMachineWeightKg)
      : "",
    _mergedJR.maxMachineWidthMm
      ? _reqPillWarn("⚠️", "Max machine width", _mergedJR.maxMachineWidthMm)
      : "",
    _mergedJR.maxMachineHeightMm
      ? _reqPillWarn("⚠️", "Max machine height", _mergedJR.maxMachineHeightMm)
      : "",
    _mergedJR.maxMachineLengthMm
      ? _reqPillWarn("⚠️", "Max machine length", _mergedJR.maxMachineLengthMm)
      : "",
    // ── Preferences ───────────────────────────────────────────
    _pill(
      "🏷️",
      "Brand preference",
      _mergedJR.brandPreference || _mergedJR.forkBrandPreference,
    ),
    _pill("🌿", "Hire type", _mergedJR.hireType),
    _pill("🔑", "3-phase charging", _mergedJR.threePhaseCharging),
    _pill(
      "🏗️",
      "Container mast",
      _mergedJR.containerMastRequired ? "Required" : null,
      "warn",
    ),
    // ── Site restrictions ─────────────────────────────────────
    ...(_mergedJR.siteAccessRestrictions || []).map((r) =>
      _reqPillRed("🚧", "Site restriction", r),
    ),
    // ── Earthworks ────────────────────────────────────────────
    _pill("🚜", "Task", _mergedJR.earthworksJob, "warn"),
    _pill("⛏️", "Dig depth", _mergedJR.digDepth, "warn"),
    _pill("📊", "Volume", _mergedJR.cartVolume, "warn"),
    _pill("🌍", "Ground condition", _mergedJR.groundCondition, "warn"),
    _pill("📐", "Work area", _mergedJR.areaSize, "warn"),
    // ── Notes ─────────────────────────────────────────────────
    _mergedJR.siteNotes
      ? `<div style="background:#F8FAFC;border:1.5px solid #E2E8F0;border-radius:8px;padding:.35rem .65rem;font-size:.78rem;color:#334155;font-weight:600;width:100%">📝 <span style="color:#64748B;font-weight:600">Customer notes:</span> ${_mergedJR.siteNotes}</div>`
      : "",
  ].filter(Boolean);

  const _reqPanelEl = document.getElementById("rq-customer-requirements");
  if (_reqPanelEl) {
    if (_pillRows.length > 0) {
      _reqPanelEl.style.display = "block";
      _reqPanelEl.innerHTML = `
        <div style="background:linear-gradient(135deg,#F0F9FF,#EFF6FF);border:2px solid #0052CC;border-radius:12px;padding:.85rem 1rem;margin-bottom:1rem">
          <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.65rem">
            <span style="font-size:1.1rem">📋</span>
            <div>
              <div style="font-weight:900;color:#0052CC;font-size:.88rem">Customer's Stated Requirements</div>
              <div style="font-size:.72rem;color:#64748B;margin-top:.05rem">Every answer they gave in the Noyo quiz — quote against these exactly</div>
            </div>
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:.4rem .45rem">
            ${_pillRows.join("")}
          </div>
        </div>`;
    } else {
      _reqPanelEl.style.display = "none";
    }
  }

  // Restore previous response if editing (declared early so field resets can use it)
  const myPrev = (req.responses || []).find(
    (r) => r.company === currentUser?.name,
  );

  // Reset shared fields — pre-fill from previous response if editing
  document.getElementById("rq-insurance-pct").value = myPrev
    ? (myPrev.insurePct ?? "")
    : "";
  document.getElementById("respond-notes").value = myPrev
    ? myPrev.notes || ""
    : "";
  // Restore MHT state
  const mhtCb = document.getElementById("rq-mht-enabled");
  const mhtOpts = document.getElementById("rq-mht-options");
  const mhtSel = document.getElementById("rq-mht-months");
  if (mhtCb) mhtCb.checked = myPrev ? myPrev.mhtRequired || false : false;
  if (mhtOpts)
    mhtOpts.style.display = myPrev && myPrev.mhtRequired ? "block" : "none";
  if (mhtSel && myPrev && myPrev.mhtMonths)
    mhtSel.value = String(myPrev.mhtMonths);
  const _amEl = document.getElementById("rq-alt-machine");
  if (_amEl) _amEl.value = myPrev ? myPrev.altMachine || "" : "";
  const _atEl = document.getElementById("rq-alt-type");
  if (_atEl) _atEl.value = myPrev ? myPrev.altType || "" : "";
  const _rqEl = document.getElementById("rq-question");
  if (_rqEl) _rqEl.value = myPrev ? myPrev.question || "" : "";
  // Show existing file names if editing
  if (myPrev && myPrev.quoteFileName) {
    const _ql = document.getElementById("rq-quote-file-lbl");
    const _qc = document.getElementById("rq-quote-file-clear");
    if (_ql) _ql.textContent = "📎 " + myPrev.quoteFileName + " (existing)";
    if (_qc) _qc.style.display = "inline";
  }
  if (myPrev && myPrev.codFileName) {
    const _cl = document.getElementById("rq-cod-file-lbl");
    const _cc = document.getElementById("rq-cod-file-clear");
    if (_cl) _cl.textContent = "📎 " + myPrev.codFileName + " (existing)";
    if (_cc) _cc.style.display = "inline";
  }

  // ── Partial-supply notice ─────────────────────────────────
  // Check RC's registered sectors vs enquiry machine types; warn if they can't cover all
  const _rcEntry = RENTAL_COMPANIES.find((c) => c.email === currentUser?.email);
  const _rcSectors = _rcEntry?.sectors || [];
  const _partialNotice = document.getElementById("rq-partial-notice");
  if (_partialNotice) {
    if (_rcSectors.length > 0) {
      const _canSupply = (req.machines || []).filter((m) =>
        _rcSectors.includes(SECTOR_MAP[m.type] || ""),
      );
      const _cantSupply = (req.machines || []).filter(
        (m) => !_rcSectors.includes(SECTOR_MAP[m.type] || ""),
      );
      if (_cantSupply.length > 0 && _canSupply.length > 0) {
        _partialNotice.style.display = "block";
        _partialNotice.innerHTML = `
          <div style="background:#FFFBEB;border:2px solid #F59E0B;border-radius:11px;padding:.75rem 1rem;margin-bottom:.85rem">
            <div style="font-weight:900;color:#92400E;font-size:.88rem;margin-bottom:.35rem">⚠️ Partial Supply — Quote for machines you can supply only</div>
            <div style="font-size:.8rem;color:#78350F;line-height:1.5">
              Based on your registered categories, you can supply <strong>${_canSupply.length} of ${(req.machines || []).length}</strong> machines in this enquiry.<br>
              <span style="color:#15803D;font-weight:700">✅ You supply:</span> ${_canSupply.map((m) => m.name || m.id).join(", ")}<br>
              <span style="color:#DC2626;font-weight:700">✗ Not in your categories:</span> ${_cantSupply.map((m) => m.name || m.id).join(", ")}<br>
              <span style="font-style:italic;opacity:.85">Enter rates only for machines you can supply. Leave others at $0. The system will automatically flag this as a partial quote for the customer.</span>
            </div>
          </div>`;
      } else if (_cantSupply.length === (req.machines || []).length) {
        _partialNotice.style.display = "block";
        _partialNotice.innerHTML = `
          <div style="background:#FEF2F2;border:2px solid #EF4444;border-radius:11px;padding:.75rem 1rem;margin-bottom:.85rem">
            <div style="font-weight:900;color:#991B1B;font-size:.88rem">⛔ None of the requested machines are in your registered categories</div>
            <div style="font-size:.8rem;color:#7F1D1D;margin-top:.25rem">You may still submit a quote if you can source these machines, but please ensure accuracy.</div>
          </div>`;
      } else {
        _partialNotice.style.display = "none";
        _partialNotice.innerHTML = "";
      }
    } else {
      _partialNotice.style.display = "none";
    }
  }

  // Build per-machine sections
  const wrap = document.getElementById("rq-machines-wrap");
  if (wrap) wrap.innerHTML = "";
  (req.machines || []).forEach((m, i) => {
    const dur = m.duration || "1-day";
    const days = rqDays(dur);
    const durLbl = DUR_LABEL[dur] || dur;
    const jr = m.jobRequirements || {};
    const specs = [
      jr.liftHeightM && `📏 ${jr.liftHeightM}m`,
      jr.loadWeightKg && `⚖️ ${jr.loadWeightKg} kg`,
      jr.terrain && `⛰️ ${jr.terrain}`,
    ]
      .filter(Boolean)
      .join(" · ");

    const prevMB = (myPrev?.machineBreakdowns || [])[i] || {};

    // ── Auto-inject telehandler attachment line items ──────────────────
    // If customer requested jib / man basket / winch / EWP etc., add those as pre-populated accessory rows
    const isTele =
      (m.type || "").toLowerCase().includes("telehandler") ||
      (m.filters || []).includes("telehandler");
    const custAttachments = (jr.attachmentsRequired || "")
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    const attachmentLineItems = [...(m.attachments || [])];
    if (isTele) {
      const attMap = {
        "jib / crane hook": "🏗️ Jib / Crane Hook",
        "man basket / work platform": "🧑‍✈️ Man Basket / EWP Basket",
        winch: "⚙️ Winch Attachment",
        "gp bucket": "🪣 GP Bucket",
        "gp bucket with grab": "🪣 GP Bucket with Grab",
        "bale clamp / grapple": "🤏 Bale Clamp / Grapple",
      };
      custAttachments.forEach((att) => {
        const key = att.toLowerCase();
        const label =
          Object.entries(attMap).find(([k]) =>
            key.includes(k.split("/")[0].trim()),
          )?.[1] || att;
        if (
          label &&
          !attachmentLineItems.some((a) =>
            a.toLowerCase().includes(key.split("/")[0].trim()),
          )
        ) {
          attachmentLineItems.push(label);
        }
      });
    }
    // ── Also inject chargeable fork attachments (jib, rotator) ──────────
    const chargeableAttsForRC = jr.chargeableAttachments || [];
    // Add jib/rotator as specific named line items for the RC to price
    if (
      jr.jibRequested &&
      !attachmentLineItems.some((a) => a.toLowerCase().includes("jib"))
    ) {
      attachmentLineItems.push("🏗️ Jib / crane hook");
    }
    if (
      jr.rotatorRequested &&
      !attachmentLineItems.some((a) => a.toLowerCase().includes("rotat"))
    ) {
      attachmentLineItems.push("🔄 Fork rotator");
    }
    chargeableAttsForRC.forEach((att) => {
      if (
        !attachmentLineItems.some((a) =>
          a.toLowerCase().includes(
            att
              .toLowerCase()
              .replace(/[^a-z]/g, "")
              .slice(0, 6),
          ),
        )
      ) {
        attachmentLineItems.push(att);
      }
    });
    const hasAccs =
      attachmentLineItems.length > 0 ||
      (jr.oneTimeAttachments || []).length > 0;
    const accPreRows = [
      ...attachmentLineItems.map((a, ai) => {
        const label =
          a.includes("Jib") || a.includes("jib")
            ? "🏗️ Jib / Crane Hook — Day & Week Rate"
            : a.includes("Winch") || a.includes("winch")
              ? "🪝 Winch / Hook Block — Day & Week Rate"
              : a.includes("otat")
                ? "🔄 Fork Rotator — Day & Week Rate"
                : a.includes("Man basket") ||
                    a.includes("man_basket") ||
                    a.includes("Man Basket")
                  ? "🧑‍✈️ Man Basket / Work Platform — Day & Week Rate"
                  : a.includes("Pipe rack") || a.includes("pipe rack")
                    ? "🪠 Pipe Racks — Day & Week Rate"
                    : a.includes("EQSS")
                      ? "🦺 EQSS Support System — Day & Week Rate"
                      : a.includes("Power to basket") || a.includes("240V")
                        ? "🔌 Power to Basket (240V) — Day & Week Rate"
                        : a;
        return `
      <div data-acc-machine="${i}" style="background:#fff;border:1.5px solid #FCA572;border-radius:9px;padding:.55rem .7rem;margin-top:.45rem">
        <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.4rem">
          <span style="font-size:.9rem">🔧</span>
          <span style="font-weight:800;color:#C2410C;font-size:.86rem;flex:1">${label}</span>
          <button onclick="this.closest('[data-acc-machine]').remove();rqRecalcAll()" style="background:none;border:none;color:#EF4444;font-size:.9rem;cursor:pointer;padding:0;flex-shrink:0">✕</button>
        </div>
        <input class="acc-name" type="hidden" value="${a}">
        <div style="display:grid;grid-template-columns:1fr 1fr auto;gap:.35rem;align-items:end">
          <div>
            <div style="font-size:.67rem;font-weight:800;color:#92400E;margin-bottom:.18rem">Hire Rate / Day ($)</div>
            <input class="acc-rate-day" type="number" min="0" step="1" placeholder="e.g. 120" oninput="rqRecalcAll();rqAccRowCalc(this)"
              value="${(prevMB.accs || [])[ai]?.rateDay || ""}"
              style="width:100%;border:1.5px solid #FCA572;border-radius:7px;padding:.32rem .45rem;font-size:.9rem;font-weight:700;font-family:inherit;box-sizing:border-box;text-align:center">
          </div>
          <div>
            <div style="font-size:.67rem;font-weight:800;color:#92400E;margin-bottom:.18rem">Hire Rate / Week ($)</div>
            <input class="acc-rate-week" type="number" min="0" step="1" placeholder="e.g. 550" oninput="rqRecalcAll();rqAccRowCalc(this)"
              value="${(prevMB.accs || [])[ai]?.rateWeek || ""}"
              style="width:100%;border:1.5px solid #FCA572;border-radius:7px;padding:.32rem .45rem;font-size:.9rem;font-weight:700;font-family:inherit;box-sizing:border-box;text-align:center">
          </div>
          <div style="text-align:right;min-width:80px">
            <div style="font-size:.67rem;font-weight:800;color:#92400E;margin-bottom:.18rem">Hire Total</div>
            <div class="acc-row-total" style="font-size:.95rem;font-weight:900;color:#C2410C;padding:.3rem .4rem;background:#FFF7ED;border-radius:7px;text-align:center">$—</div>
          </div>
        </div>
        <div style="margin-top:.3rem;font-size:.71rem;color:#92400E;opacity:.75">${days} working day${days !== 1 ? "s" : ""} @ ${durLbl} — system calculates best day/week rate automatically</div>
      </div>`;
      }),
      ...(jr.oneTimeAttachments || []).map((a, ai) => {
        const prevOt = (prevMB.accs || []).find(
          (x) => x.name === a && x.oneTime,
        );
        return `
      <div data-acc-machine="${i}" data-one-time="1" style="background:#F0FDF4;border:1.5px solid #86EFAC;border-radius:9px;padding:.55rem .7rem;margin-top:.45rem">
        <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.4rem">
          <span style="font-size:.9rem">💧</span>
          <span style="font-weight:800;color:#15803D;font-size:.86rem;flex:1">${a} — <span style="font-weight:700;color:#166534">One-time charge (not a daily rate)</span></span>
          <button onclick="this.closest('[data-acc-machine]').remove();rqRecalcAll()" style="background:none;border:none;color:#EF4444;font-size:.9rem;cursor:pointer;padding:0;flex-shrink:0">✕</button>
        </div>
        <input class="acc-name" type="hidden" value="${a}">
        <input class="acc-one-time" type="hidden" value="1">
        <div style="display:grid;grid-template-columns:1fr auto;gap:.35rem;align-items:end">
          <div>
            <div style="font-size:.67rem;font-weight:800;color:#15803D;margin-bottom:.18rem">One-time hire charge ($) — total for the full hire</div>
            <input class="acc-rate-onetime" type="number" min="0" step="1" placeholder="e.g. 95" oninput="rqRecalcAll();rqAccOneTimeCalc(this)"
              value="${prevOt?.total || ""}"
              style="width:100%;border:1.5px solid #86EFAC;border-radius:7px;padding:.32rem .45rem;font-size:.9rem;font-weight:700;font-family:inherit;box-sizing:border-box;text-align:center;background:#fff">
          </div>
          <div style="text-align:right;min-width:80px">
            <div style="font-size:.67rem;font-weight:800;color:#15803D;margin-bottom:.18rem">Total</div>
            <div class="acc-row-total" style="font-size:.95rem;font-weight:900;color:#15803D;padding:.3rem .4rem;background:#DCFCE7;border-radius:7px;text-align:center">$—</div>
          </div>
        </div>
        <div style="margin-top:.3rem;font-size:.71rem;color:#15803D;opacity:.8">Charged once — not multiplied by days. Covers the full hire period.</div>
      </div>`;
      }),
    ].join("");

    const sec = document.createElement("div");
    sec.style.cssText =
      "background:#fff;border:1.5px solid #E2E8F0;border-radius:12px;padding:.85rem 1rem";
    sec.innerHTML = `
      <div style="display:flex;align-items:center;gap:.6rem;margin-bottom:.7rem">
        <span style="font-size:1.3rem">${m.emoji || "🏗️"}</span>
        <div>
          <div style="font-weight:800;font-size:.93rem;color:#0F172A">${m.name || m.id || "Unknown"}</div>
          <div style="font-size:.76rem;color:#64748B">⏳ ${durLbl} (${days} working day${days !== 1 ? "s" : ""})</div>
          ${specs ? `<div style="font-size:.75rem;color:#475569">${specs}</div>` : ""}
        </div>
      </div>

      <!-- Hire rates — earthworks shows hourly + day + mob/demob; lifting shows day + week -->
      ${
        jr._isEarthworks
          ? `
      <div style="background:#FFFBEB;border:1.5px solid #FDE68A;border-radius:10px;padding:.65rem .85rem;margin-bottom:.65rem">
        <div style="font-size:.72rem;font-weight:800;color:#92400E;margin-bottom:.4rem;text-transform:uppercase;letter-spacing:.4px">🚜 Earth Works Rate</div>

        <!-- Transport arrangement notice — drives mob/demob visibility -->
        <div style="background:${jr.emTransport === "rental" ? "#EFF6FF" : "#F0FDF4"};border:1px solid ${jr.emTransport === "rental" ? "#93C5FD" : "#86EFAC"};border-radius:8px;padding:.45rem .65rem;margin-bottom:.55rem;font-size:.76rem;font-weight:700;color:${jr.emTransport === "rental" ? "#1D4ED8" : "#15803D"};line-height:1.45">
          ${jr.transportNote || (jr.emTransport === "rental" ? "🚚 Customer requires transport to site. Include mob/demob fee below." : "✅ Customer is picking up or organising their own transport. Quote hire rate only.")}
        </div>

        <!-- Hire type reminder -->
        <div style="font-size:.72rem;color:#B45309;margin-bottom:.5rem;line-height:1.5">
          <strong>${jr.hireArrangement || "Hire type not specified"}</strong> — quote your rate inclusive of fuel.
          ${jr.hireArrangement && jr.hireArrangement.includes("Wet") ? "Operator cost included in your rate." : jr.hireArrangement && jr.hireArrangement.includes("Dry") ? "Machine-only rate — customer supplies operator." : ""}
          Minimum 4-hour call-out is standard.
        </div>

        <!-- Hour + Day rates -->
        <div style="display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:.45rem">
          <div style="flex:1;min-width:90px">
            <label style="font-size:.71rem;font-weight:700;color:#92400E;display:block;margin-bottom:.18rem">Rate / Hour ($)</label>
            <input id="rq-rate-hour-${i}" type="number" min="0" step="1" placeholder="e.g. 180" value="${prevMB.rateHour || ""}"
              style="width:100%;border:1.5px solid #FDE68A;border-radius:7px;padding:.32rem .5rem;font-size:.92rem;font-weight:700;font-family:inherit;box-sizing:border-box;background:#fff"
              oninput="rqRecalcAll()">
          </div>
          <div style="flex:1;min-width:90px">
            <label style="font-size:.71rem;font-weight:700;color:#92400E;display:block;margin-bottom:.18rem">Rate / Day ($)</label>
            <input id="rq-rate-day-${i}" type="number" min="0" step="1" placeholder="e.g. 1200" value="${prevMB.rateDay || ""}"
              style="width:100%;border:1.5px solid #FDE68A;border-radius:7px;padding:.32rem .5rem;font-size:.92rem;font-weight:700;font-family:inherit;box-sizing:border-box;background:#fff"
              oninput="rqRecalcAll()">
          </div>
          <input id="rq-rate-week-${i}" type="hidden" value="">
        </div>

        <!-- Mob/demob — only shown when rental company is transporting -->
        ${
          jr.emTransport === "rental"
            ? `
        <div style="display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:.3rem">
          <div style="flex:1;min-width:90px">
            <label style="font-size:.71rem;font-weight:700;color:#1E40AF;display:block;margin-bottom:.18rem">🚛 Mob fee ($)</label>
            <input id="rq-trans-in-${i}" type="number" min="0" step="1" placeholder="e.g. 350" value="${prevMB.transIn || ""}"
              style="width:100%;border:1.5px solid #93C5FD;border-radius:7px;padding:.32rem .5rem;font-size:.92rem;font-weight:700;font-family:inherit;box-sizing:border-box;background:#F0F7FF"
              oninput="rqRecalcAll()">
          </div>
          <div style="flex:1;min-width:90px">
            <label style="font-size:.71rem;font-weight:700;color:#1E40AF;display:block;margin-bottom:.18rem">🚛 Demob fee ($)</label>
            <input id="rq-trans-out-${i}" type="number" min="0" step="1" placeholder="e.g. 350" value="${prevMB.transOut || ""}"
              style="width:100%;border:1.5px solid #93C5FD;border-radius:7px;padding:.32rem .5rem;font-size:.92rem;font-weight:700;font-family:inherit;box-sizing:border-box;background:#F0F7FF"
              oninput="rqRecalcAll()">
          </div>
        </div>`
            : `
        <input id="rq-trans-in-${i}" type="hidden" value="0">
        <input id="rq-trans-out-${i}" type="hidden" value="0">
        <div style="font-size:.71rem;color:#15803D;font-style:italic">Transport fields hidden — customer is organising their own pickup/transport.</div>`
        }

        <div style="font-size:.71rem;color:#92400E;margin-top:.45rem;font-style:italic">System calculates total from day rate × days, or hourly rate × 8hrs/day if no day rate entered.</div>
      </div>
      `
          : `
      <div style="display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:.6rem">
        <div style="flex:1;min-width:100px">
          <label style="font-size:.71rem;font-weight:700;color:#64748B;display:block;margin-bottom:.18rem">Rate / Day ($)</label>
          <input id="rq-rate-day-${i}" type="number" min="0" step="1" placeholder="0" value="${prevMB.rateDay || ""}"
            style="width:100%;border:1.5px solid #CBD5E1;border-radius:7px;padding:.32rem .5rem;font-size:.92rem;font-weight:700;font-family:inherit;box-sizing:border-box"
            oninput="rqRecalcAll()">
        </div>
        <div style="flex:1;min-width:100px">
          <label style="font-size:.71rem;font-weight:700;color:#64748B;display:block;margin-bottom:.18rem">Rate / Week ($)</label>
          <input id="rq-rate-week-${i}" type="number" min="0" step="1" placeholder="0" value="${prevMB.rateWeek || ""}"
            style="width:100%;border:1.5px solid #CBD5E1;border-radius:7px;padding:.32rem .5rem;font-size:.92rem;font-weight:700;font-family:inherit;box-sizing:border-box"
            oninput="rqRecalcAll()">
        </div>
      </div>

      <!-- Transport per machine -->
      <div style="display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:.6rem">
        <div style="flex:1;min-width:100px">
          <label style="font-size:.71rem;font-weight:700;color:#1E40AF;display:block;margin-bottom:.18rem">🚚 Transport In ($)</label>
          <input id="rq-trans-in-${i}" type="number" min="0" step="1" placeholder="e.g. 150" value="${prevMB.transIn || ""}"
            style="width:100%;border:1.5px solid #93C5FD;border-radius:7px;padding:.32rem .5rem;font-size:.92rem;font-weight:700;font-family:inherit;box-sizing:border-box;background:#F0F7FF"
            oninput="rqRecalcAll()">
        </div>
        <div style="flex:1;min-width:100px">
          <label style="font-size:.71rem;font-weight:700;color:#1E40AF;display:block;margin-bottom:.18rem">🚚 Transport Out ($)</label>
          <input id="rq-trans-out-${i}" type="number" min="0" step="1" placeholder="e.g. 150" value="${prevMB.transOut || ""}"
            style="width:100%;border:1.5px solid #93C5FD;border-radius:7px;padding:.32rem .5rem;font-size:.92rem;font-weight:700;font-family:inherit;box-sizing:border-box;background:#F0F7FF"
            oninput="rqRecalcAll()">
        </div>
      </div>
      `
      }

      <!-- Accessories — only shown when customer requested attachments -->
      ${
        hasAccs
          ? `
      <div style="background:#FFF7ED;border:1.5px solid #FED7AA;border-radius:10px;padding:.6rem .75rem;margin-bottom:.5rem">
        <div style="font-size:.72rem;font-weight:800;color:#C2410C;margin-bottom:.1rem">🔧 Accessory / Attachment Rental Pricing</div>
        <div style="font-size:.72rem;color:#92400E;margin-bottom:.4rem">Customer-requested attachments are pre-filled below. Enter your hire rate per day and/or per week — system calculates the total. Leave blank if not available.</div>
        <div id="rq-acc-list-${i}">${accPreRows}</div>
        <button onclick="rqAddAccessory(${i})"
          style="margin-top:.4rem;background:none;border:1.5px dashed #FCA572;border-radius:7px;padding:.25rem .65rem;font-size:.74rem;font-weight:700;color:#C2410C;cursor:pointer;width:100%">
          + Add Another Accessory Line
        </button>
      </div>`
          : `<div id="rq-acc-list-${i}" style="display:none"></div>`
      }

      <!-- Per-machine: alt machine + question -->
      <div style="background:#FFF7ED;border:1.5px solid #FCD34D;border-radius:10px;padding:.65rem .8rem;margin-top:.5rem">
        <div style="font-size:.7rem;font-weight:800;color:#92400E;margin-bottom:.4rem">🔄 Offering a different machine for this item?</div>
        <div style="display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:.4rem">
          <input id="rq-alt-machine-${i}" type="text" placeholder="Brand / model you'll supply (leave blank if exact match)"
            value="${prevMB.altMachine || ""}"
            style="flex:2;min-width:140px;border:1.5px solid #FCD34D;border-radius:7px;padding:.3rem .5rem;font-size:.82rem;font-family:inherit;background:#fff;color:#1E293B;box-sizing:border-box">
          <select id="rq-alt-type-${i}" style="flex:1;min-width:130px;border:1.5px solid #FCD34D;border-radius:7px;padding:.3rem .45rem;font-size:.8rem;font-family:inherit;background:#fff;color:#334155">
            <option value="" ${!prevMB.altType ? "selected" : ""}>Exact match</option>
            <option value="equivalent" ${prevMB.altType === "equivalent" ? "selected" : ""}>Equivalent (same class)</option>
            <option value="upgraded" ${prevMB.altType === "upgraded" ? "selected" : ""}>Upgraded (larger / more capable)</option>
            <option value="alternative" ${prevMB.altType === "alternative" ? "selected" : ""}>Alternative type</option>
          </select>
        </div>
        <div style="font-size:.7rem;font-weight:800;color:#1E40AF;margin-bottom:.25rem;margin-top:.35rem">❓ Question to customer about this machine?</div>
        <textarea id="rq-question-${i}" rows="1" placeholder="e.g. Confirm ground conditions, overhead clearance, site access…"
          style="width:100%;border:1.5px solid #93C5FD;border-radius:7px;padding:.3rem .5rem;font-size:.8rem;font-family:inherit;background:#fff;color:#1E293B;resize:vertical;box-sizing:border-box">${prevMB.question || ""}</textarea>
      </div>

      <!-- Machine hire total (live) -->
      <div id="rq-breakdown-${i}" style="background:#F8FAFC;border:1px solid #E2E8F0;border-radius:8px;padding:.5rem .75rem"></div>`;
    wrap.appendChild(sec);
  });

  rqRecalcAll();
  document.getElementById("respond-modal").classList.add("open");
  // Scroll the INNER scroll body to top — this is the actual scrollable element
  requestAnimationFrame(() => {
    const sb = document.querySelector("#respond-modal .rq-scroll-body");
    if (sb) sb.scrollTop = 0;
    const modal = document.querySelector("#respond-modal .modal");
    if (modal) modal.scrollTop = 0;
    const rm = document.getElementById("respond-modal");
    if (rm) rm.scrollTop = 0;
  });
}

function closeRespondModal() {
  document.getElementById("respond-modal").classList.remove("open");
  // Reset ALL scroll positions so next open starts at top
  const _sb = document.querySelector("#respond-modal .rq-scroll-body");
  if (_sb) _sb.scrollTop = 0;
  const _rmClose = document.getElementById("respond-modal");
  if (_rmClose) _rmClose.scrollTop = 0;
  window._rqReq = null;
  window._rqTotals = null;
  // Reset all per-machine alt/question fields
  document
    .querySelectorAll(
      '[id^="rq-alt-machine-"],[id^="rq-alt-type-"],[id^="rq-question-"]',
    )
    .forEach((el) => {
      el.value = "";
    });
  // Reset file slots
  document.querySelectorAll(".rq-file-row").forEach((row) => {
    const inp = row.querySelector(".rq-file-input");
    if (inp) inp.value = "";
    const lbl = row.querySelector(".rq-file-lbl");
    if (lbl) lbl.textContent = "Choose file…";
    const clr = row.querySelector(".rq-file-clear");
    if (clr) clr.style.display = "none";
  });
  // Remove any dynamically added extra slots beyond the original 4
  const slots = document.getElementById("rq-file-slots");
  if (slots) {
    const rows = slots.querySelectorAll(".rq-file-row");
    rows.forEach((r, i) => {
      if (i >= 4) r.remove();
    });
  }
}

function rqFileRowSelected(input) {
  const row = input.closest(".rq-file-row");
  if (!row) return;
  const lbl = row.querySelector(".rq-file-lbl");
  const clr = row.querySelector(".rq-file-clear");
  if (input.files && input.files[0]) {
    if (lbl) lbl.textContent = input.files[0].name;
    if (clr) clr.style.display = "inline";
  }
}

function rqFileRowClear(btn) {
  const row = btn.closest(".rq-file-row");
  if (!row) return;
  const inp = row.querySelector(".rq-file-input");
  const lbl = row.querySelector(".rq-file-lbl");
  if (inp) inp.value = "";
  if (lbl) lbl.textContent = "Choose file…";
  btn.style.display = "none";
}

function rqFileTypeChange(sel) {
  /* type is stored on select.value — no action needed */
}

function rqAddFileSlot() {
  const slots = document.getElementById("rq-file-slots");
  if (!slots) return;
  const idx = slots.querySelectorAll(".rq-file-row").length;
  const row = document.createElement("div");
  row.className = "rq-file-row";
  row.setAttribute("data-slot", idx);
  row.innerHTML = `<div style="display:flex;align-items:center;gap:.5rem;flex-wrap:wrap">
    <select class="rq-file-type" onchange="rqFileTypeChange(this)" style="flex:0 0 auto;border:1.5px solid #86EFAC;border-radius:8px;padding:.32rem .55rem;font-size:.8rem;font-family:inherit;background:#fff;color:#166534;font-weight:700">
      <option value="quote">📋 Formal Quote / Hire Agreement</option>
      <option value="cod">🗒️ COD Form</option>
      <option value="account">📝 Account Application Form</option>
      <option value="terms">📄 Terms & Conditions</option>
      <option value="safety">🦺 Safety Data / Compliance</option>
      <option value="other" selected>📎 Other Document</option>
    </select>
    <label style="flex:1;min-width:140px;display:flex;align-items:center;gap:.4rem;background:#fff;border:1.5px dashed #86EFAC;border-radius:8px;padding:.38rem .65rem;cursor:pointer;font-size:.8rem;font-weight:700;color:#166534">
      <span>📂</span><span class="rq-file-lbl">Choose file…</span>
      <input type="file" class="rq-file-input" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.heic" style="display:none" onchange="rqFileRowSelected(this)">
    </label>
    <button class="rq-file-clear" onclick="rqFileRowClear(this)" style="display:none;background:none;border:none;color:#EF4444;font-size:.82rem;cursor:pointer;padding:0;white-space:nowrap">✕ Remove</button>
    <button onclick="this.closest('.rq-file-row').remove()" style="background:none;border:none;color:#94A3B8;font-size:.78rem;cursor:pointer;padding:0;white-space:nowrap">🗑 Delete row</button>
  </div>`;
  slots.appendChild(row);
}

async function rqReadAllFileSlots() {
  const rows = document.querySelectorAll(".rq-file-row");
  const results = [];
  for (const row of rows) {
    const inp = row.querySelector(".rq-file-input");
    const sel = row.querySelector(".rq-file-type");
    if (!inp || !inp.files || !inp.files[0]) continue;
    const file = inp.files[0];
    const docType = sel ? sel.value : "other";
    const docLabel = sel
      ? sel.options[sel.selectedIndex]?.text?.replace(/^[^\s]+\s/, "")
      : "Document";
    const dataUrl = await new Promise((res) => {
      const reader = new FileReader();
      reader.onload = (e) => res(e.target.result);
      reader.onerror = () => res(null);
      reader.readAsDataURL(file);
    });
    if (dataUrl)
      results.push({
        docType,
        docLabel,
        name: file.name,
        size: file.size,
        url: dataUrl,
      });
  }
  return results;
}

function rqFileSelected(input, lblId, clearBtnId) {
  const lbl = document.getElementById(lblId);
  const clr = document.getElementById(clearBtnId);
  if (input.files && input.files[0]) {
    const f = input.files[0];
    if (lbl) lbl.textContent = f.name;
    if (clr) clr.style.display = "inline";
  }
}

function rqFileClear(inputId, lblId, clearBtnId) {
  const inp = document.getElementById(inputId);
  const lbl = document.getElementById(lblId);
  const clr = document.getElementById(clearBtnId);
  if (inp) inp.value = "";
  if (lbl) lbl.textContent = "Choose file…";
  if (clr) clr.style.display = "none";
}

function rqReadFileAsDataUrl(inputId) {
  return new Promise((resolve) => {
    const inp = document.getElementById(inputId);
    if (!inp || !inp.files || !inp.files[0]) {
      resolve(null);
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) =>
      resolve({
        url: e.target.result,
        name: inp.files[0].name,
        size: inp.files[0].size,
      });
    reader.onerror = () => resolve(null);
    reader.readAsDataURL(inp.files[0]);
  });
}

async function submitResponse() {
  const req = quoteInbox.find((r) => r.id === _respondingId);
  if (!req) return;

  rqRecalcAll(); // ensure totals are fresh
  const tot = window._rqTotals;
  if (!tot || tot.grandTotal === 0) {
    showToast("Please enter at least one rate before submitting", "#EF4444");
    return;
  }

  const notes = document.getElementById("respond-notes").value.trim();
  const altMachine =
    document.getElementById("rq-alt-machine")?.value?.trim() || "";
  const altType = document.getElementById("rq-alt-type")?.value || "";
  const question = document.getElementById("rq-question")?.value?.trim() || "";

  // ── Minimum Hire Term ─────────────────────────────────────────────────
  const mhtEnabled =
    document.getElementById("rq-mht-enabled")?.checked || false;
  const mhtMonths = mhtEnabled
    ? parseInt(document.getElementById("rq-mht-months")?.value || "6", 10)
    : 0;

  // Read all file slots
  const attachedFiles = await rqReadAllFileSlots();
  // Legacy compat: first quote-type file = quoteFileUrl, first cod-type = codFileUrl
  const _qf = attachedFiles.find((f) => f.docType === "quote");
  const _cf = attachedFiles.find((f) => f.docType === "cod");
  const quoteFileData = _qf ? { url: _qf.url, name: _qf.name } : null;
  const codFileData = _cf ? { url: _cf.url, name: _cf.name } : null;
  const insurePct =
    parseFloat(document.getElementById("rq-insurance-pct")?.value) || 0;
  const transInTotal = tot.transInTotal || 0;
  const transOutTotal = tot.transOutTotal || 0;

  const machineBreakdowns = (req.machines || []).map((m, i) => {
    const days = rqDays(m.duration || "1-day");
    const rateDay =
      parseFloat(document.getElementById(`rq-rate-day-${i}`)?.value) || 0;
    const rateWeek =
      parseFloat(document.getElementById(`rq-rate-week-${i}`)?.value) || 0;
    const mTransIn =
      parseFloat(document.getElementById(`rq-trans-in-${i}`)?.value) || 0;
    const mTransOut =
      parseFloat(document.getElementById(`rq-trans-out-${i}`)?.value) || 0;
    let rentalCost = 0;
    if (days >= 5 && rateWeek > 0) rentalCost = (days / 5) * rateWeek;
    else if (rateDay > 0) rentalCost = days * rateDay;
    else if (rateWeek > 0) rentalCost = (days / 5) * rateWeek;
    // Earthworks hourly fallback
    const rateHour =
      parseFloat(document.getElementById(`rq-rate-hour-${i}`)?.value) || 0;
    const jr_m = m.jobRequirements || {};
    if (jr_m._isEarthworks && rentalCost === 0 && rateHour > 0) {
      rentalCost = days * 8 * rateHour;
    }

    const accs = [];
    document.querySelectorAll(`[data-acc-machine="${i}"]`).forEach((row) => {
      const name = row.querySelector(".acc-name")?.value.trim();
      const isOneTime =
        row.querySelector(".acc-one-time")?.value === "1" ||
        row.dataset.oneTime === "1";
      if (isOneTime) {
        const total =
          parseFloat(row.querySelector(".acc-rate-onetime")?.value) || 0;
        if (name)
          accs.push({ name, rateDay: 0, rateWeek: 0, total, oneTime: true });
      } else {
        const rDay = parseFloat(row.querySelector(".acc-rate-day")?.value) || 0;
        const rWeek =
          parseFloat(row.querySelector(".acc-rate-week")?.value) || 0;
        let total = 0;
        if (days >= 5 && rWeek > 0) total = (days / 5) * rWeek;
        else if (rDay > 0) total = days * rDay;
        else if (rWeek > 0) total = (days / 5) * rWeek;
        if (name) accs.push({ name, rateDay: rDay, rateWeek: rWeek, total });
      }
    });
    const accTotal = accs.reduce((s, a) => s + a.total, 0);
    const hireTotal = rentalCost + accTotal;
    const insurance = hireTotal * (insurePct / 100);
    const transport = mTransIn + mTransOut;
    const mAltMachine =
      document.getElementById(`rq-alt-machine-${i}`)?.value?.trim() || "";
    const mAltType = document.getElementById(`rq-alt-type-${i}`)?.value || "";
    const mQuestion =
      document.getElementById(`rq-question-${i}`)?.value?.trim() || "";
    return {
      name: m.name,
      emoji: m.emoji,
      duration: m.duration,
      rateDay,
      rateWeek,
      rateHour: rateHour || undefined,
      rentalCost,
      accs,
      accTotal,
      hireTotal,
      insurance,
      transIn: mTransIn,
      transOut: mTransOut,
      transport,
      altMachine: mAltMachine || undefined,
      altType: mAltType || undefined,
      question: mQuestion || undefined,
    };
  });

  const companyName = currentUser ? currentUser.name : "Rental Co.";

  // ── Partial quote detection ───────────────────────────────
  // Any machine with no rates entered = not quoted by this RC
  const _quotedMBs = machineBreakdowns.filter(
    (mb) =>
      (mb.rateDay || 0) > 0 || (mb.rateWeek || 0) > 0 || (mb.rateHour || 0) > 0,
  );
  const _notQuotedMBs = machineBreakdowns.filter(
    (mb) =>
      !(
        (mb.rateDay || 0) > 0 ||
        (mb.rateWeek || 0) > 0 ||
        (mb.rateHour || 0) > 0
      ),
  );
  const _isPartial = _notQuotedMBs.length > 0 && _quotedMBs.length > 0;
  const _partialAutoNote = _isPartial
    ? `⚠️ Partial quote — this supplier covers ${_quotedMBs.length} of ${machineBreakdowns.length} machines requested.\n✅ Quoted: ${_quotedMBs.map((m) => m.name).join(", ")}.\n✗ Not quoted: ${_notQuotedMBs.map((m) => m.name).join(", ")}.\nPlease source the remaining equipment separately.`
    : "";
  const _finalNotes = [_partialAutoNote, notes].filter(Boolean).join("\n\n");

  // Remove previous response from this company if editing
  if (!req.responses) req.responses = [];
  req.responses = (req.responses || []).filter(
    (r) => r.company !== companyName,
  );

  req.responses.push({
    ts: Date.now(),
    company: companyName,
    price: `$${tot.grandTotal.toFixed(2)} inc. GST`,
    machineBreakdowns,
    transInTotal,
    transOutTotal,
    transport: tot.totalTransport,
    insurePct,
    totalHire: tot.totalHire,
    totalInsurance: tot.totalInsurance,
    beforeGST: tot.beforeGST,
    gst: tot.gst,
    grandTotal: tot.grandTotal,
    notes: _finalNotes,
    partial: _isPartial,
    quotedMachines: _isPartial ? _quotedMBs.map((m) => m.name) : undefined,
    notQuotedMachines: _isPartial
      ? _notQuotedMBs.map((m) => m.name)
      : undefined,
    mhtRequired: mhtEnabled || false,
    mhtMonths: mhtEnabled ? mhtMonths : 0,
    altMachine: altMachine || undefined,
    altType: altType || undefined,
    question: question || undefined,
    quoteFileUrl: quoteFileData ? quoteFileData.url : undefined,
    quoteFileName: quoteFileData ? quoteFileData.name : undefined,
    codFileUrl: codFileData ? codFileData.url : undefined,
    codFileName: codFileData ? codFileData.name : undefined,
    attachedFiles: attachedFiles.length ? attachedFiles : undefined,
    availability: "Available on requested date",
    accepted: false,
    rejected: false,
  });
  req.responded = true;
  req.response = req.responses[(req.responses || []).length - 1];

  // On first response: give customer 1 calendar day (24 real hours) to accept.
  // If that lands on a weekend or public holiday, roll forward to the same time
  // on the next working day.
  if ((req.responses || []).length === 1 && !req.customerAcceptExpires) {
    const _acceptBase =
      req.expires && Date.now() <= req.expires
        ? req.expires // window still open — accept starts from close
        : Date.now(); // window already closed — accept starts from now (late response)
    // Add 24 real hours
    let _deadline = _acceptBase + 24 * 3600000;
    // If deadline lands on a weekend or public holiday, roll forward day by day
    const _tz = stateToTZ(req.state || "");
    for (let guard = 0; guard < 7; guard++) {
      const _wc = _wcParts(_deadline, _tz);
      if (_isWorkingIso(_wc.iso)) break;
      _deadline += 24 * 3600000;
    }
    req.customerAcceptExpires = _deadline;
    req.customerAcceptWindowHours = 24;
  }

  // ── Write response DIRECTLY to Firestore — atomic, no local merge ──
  const _directResponse = req.responses
    ? req.responses[req.responses.length - 1]
    : null;
  if (_directResponse && req.id) {
    try {
      const _docRef = _fbDb.collection("shared_enquiries").doc(req.id);
      const _snap = await _docRef.get();
      const _existing = _snap.exists ? _snap.data().responses || [] : [];
      // Remove old entry from this company, add new one
      const _others = _existing.filter(
        (r) => r.company !== _directResponse.company,
      );
      const _newResponses = [..._others, _directResponse];
      const _cleanPayload = _stripUndefined({
        ...(_snap.exists ? _snap.data() : {}),
        ...req,
        responses: _newResponses,
        responded: true,
      });
      _cleanPayload.updatedAt = firebase.firestore.FieldValue.serverTimestamp();
      await _docRef.set(_cleanPayload, { merge: true });
      console.log(
        "[Noyo] ✅ Direct Firestore write OK. enquiry:",
        req.id,
        "| now has",
        _newResponses.length,
        "responses | companies:",
        _newResponses.map((r) => r.company).join(", "),
      );
      showToast(
        "✅ Quote sent! Customer can now see your response.",
        "#15803D",
        5000,
      );
    } catch (_e) {
      console.error("[Noyo] ❌ Direct Firestore write FAILED:", _e.message);
      showToast(
        "❌ Firestore write failed: " + _e.message + " — check Firebase rules",
        "#EF4444",
        8000,
      );
    }
  }

  closeRespondModal();
  saveInbox();
  saveQuoteToFirebase(req); // also update local cache
  renderQuoteRequests();
  renderQuoteInbox();
  try {
    adminTrackQuote("responded", req);
  } catch (e) {}
}

function declineQuote(reqId) {
  const req = quoteInbox.find((r) => r.id === reqId);
  if (req) {
    req.responded = true;
    req.declined = true;
    saveInbox();
    saveQuoteToFirebase(req);
  }
  renderQuoteInbox();
  showToast("Quote declined", "#64748B");
}

