// Given a query, return the set of catKeys it refers to (empty = all)
function kymResolveCategories(query) {
  const lq = query.toLowerCase();
  const matched = new Set();
  // Check multi-word synonyms first (longest match wins)
  const keys = Object.keys(KYM_CAT_SYNONYMS).sort(
    (a, b) => b.length - a.length,
  );
  for (const syn of keys) {
    if (lq.includes(syn)) {
      KYM_CAT_SYNONYMS[syn].forEach((c) => matched.add(c));
    }
  }
  return matched;
}

// Strip category-hint words from query to get only spec tokens
function kymSpecTokens(query) {
  let lq = query.toLowerCase();
  const keys = Object.keys(KYM_CAT_SYNONYMS).sort(
    (a, b) => b.length - a.length,
  );
  for (const syn of keys) {
    lq = lq.replace(
      new RegExp(
        "\\b" + syn.replace(/[-]/g, "[-\\s]?").replace(/[°]/g, "[°]?") + "\\b",
        "g",
      ),
      " ",
    );
  }
  // Also strip standalone rotating-intent words that aren't spec values
  const stopWords = [
    "rotating",
    "rotational",
    "rotary",
    "rotation",
    "slewing",
    "slew",
    "crane",
    "replacement",
    "electric",
    "battery",
    "diesel",
    "lpg",
    "petrol",
    "gas",
    "lithium", // power terms handled separately
    "all",
    "any",
    "show",
    "me",
    "a",
    "an",
    "the",
    "with",
    "for",
    "and",
    "or",
    "of",
    "in",
    "on",
    "at",
  ];
  return lq.split(/\s+/).filter((t) => t.length > 1 && !stopWords.includes(t));
}

// ── Parse numeric intent from free-text query ─────────────────────────────
function _kymParseNumerics(query) {
  const lq = query.toLowerCase();
  const result = { capacity: null, height: null, reach: null };

  // Capacity: "2.5 ton", "2.5t", "2500kg", "2.5 tonne", "25 ton", "3T"
  const capMatch =
    lq.match(/(\d+(?:\.\d+)?)\s*(?:t\b|ton(?:ne)?s?|tonne?s?)\b/) ||
    lq.match(/(\d+(?:\.\d+)?)\s*t\b(?!elehandler|rack|ype|errain)/);
  if (capMatch) result.capacity = parseFloat(capMatch[1]);

  const kgMatch = lq.match(/(\d+(?:\.\d+)?)\s*kg\b/);
  if (kgMatch && !result.capacity)
    result.capacity = parseFloat(kgMatch[1]) / 1000;

  // Height: "20m", "20 metre", "20m lift", "20m working height", "65ft"
  const htMatch =
    lq.match(
      /(\d+(?:\.\d+)?)\s*(?:m\b|metre?s?|meter?s?)(?:\s*(?:lift|height|platform|working|high|tall))?/,
    ) || lq.match(/(\d+(?:\.\d+)?)\s*(?:ft|foot|feet)/i);
  if (htMatch) {
    let v = parseFloat(htMatch[1]);
    if (/ft|foot|feet/i.test(htMatch[0])) v = v * 0.3048;
    result.height = v;
  }

  // Reach: "10m reach", "8m outreach"
  const reachMatch = lq.match(/(\d+(?:\.\d+)?)\s*m\s*(?:reach|outreach)/);
  if (reachMatch) result.reach = parseFloat(reachMatch[1]);

  return result;
}

// Match a machine against remaining spec tokens only
function kymMatchesQuery(m, catKey, query) {
  if (!query) return true;

  const isRotatingMachine = !!m.isRotating;
  const queryLower = query.toLowerCase();

  // ── Power-source intent ─────────────────────────────────────────────────
  const ELECTRIC_TERMS = [
    "electric",
    "battery",
    "li-ion",
    "lithium",
    "zero emission",
    "electric rotating",
    "eth",
  ];
  const DIESEL_TERMS = ["diesel"];
  const LPG_TERMS = ["lpg", "gas", "petrol"];

  const queryWantsElectric = ELECTRIC_TERMS.some((t) => queryLower.includes(t));
  const queryWantsDiesel = DIESEL_TERMS.some((t) => queryLower.includes(t));
  const queryWantsLPG = LPG_TERMS.some((t) => queryLower.includes(t));

  if (queryWantsElectric || queryWantsDiesel || queryWantsLPG) {
    const powerStr = (m.power || "").toLowerCase();
    const engineStr = (m.engine || "").toLowerCase();
    const filtersStr = (m.filters || []).join(" ").toLowerCase();
    const powerBag = powerStr + " " + engineStr + " " + filtersStr;
    const isElectric =
      powerBag.includes("electric") ||
      powerBag.includes("battery") ||
      powerBag.includes("li-ion") ||
      powerBag.includes("lithium");
    const isDiesel = powerBag.includes("diesel");
    const isLPG =
      powerBag.includes("lpg") ||
      powerBag.includes("petrol") ||
      powerBag.includes("gas");
    if (queryWantsElectric && !isElectric) return false;
    if (queryWantsDiesel && isElectric) return false;
    if (queryWantsLPG && !isLPG) return false;
  }

  // ── Rotating intent ─────────────────────────────────────────────────────
  const rotatingTerms = [
    "rotating",
    "rotational",
    "rotary",
    "rotation",
    "rotator",
    "slewing",
    "slew",
    "360",
    "mrt",
    "mrtx",
    "rth",
    "crane replacement",
    "roto",
  ];
  const queryHasRotatingIntent = rotatingTerms.some((t) =>
    queryLower.includes(t),
  );
  if (queryHasRotatingIntent && catKey === "telehandler" && !isRotatingMachine)
    return false;

  // ── Numeric spec matching ───────────────────────────────────────────────
  const nums = _kymParseNumerics(queryLower);

  if (nums.capacity !== null) {
    // Check machine capacity — allow ±15% tolerance so "2.5t" matches a 2.5T or 3T machine
    const cap =
      m.capacity ||
      (m.capacityKg ? m.capacityKg / 1000 : null) ||
      m.capacityOnTyres ||
      m.capacityOnOutriggers ||
      m.ratedCapacity;
    if (cap == null) return false; // no capacity data — exclude from capacity searches
    const tolerance = nums.capacity * 0.15;
    // Machine must be AT LEAST the required capacity (within 15% below), no upper limit
    if (cap < nums.capacity - tolerance) return false;
  }

  if (nums.height !== null) {
    // Match against platform height, working height, lift height
    const ht = m.platformHeight || m.liftHeight || m.workingHeight || m.maxLift;
    if (ht == null) return false;
    const tolerance = Math.max(1, nums.height * 0.15);
    if (ht < nums.height - tolerance) return false;
  }

  if (nums.reach !== null) {
    const reach = m.maxReach || m.maxOutreach || m.forwardReach;
    if (reach == null) return false;
    const tolerance = Math.max(0.5, nums.reach * 0.15);
    if (reach < nums.reach - tolerance) return false;
  }

  // ── Brand matching ──────────────────────────────────────────────────────
  // If query contains a brand name, prioritise those machines
  const brandNames = [
    "toyota",
    "genie",
    "jlg",
    "manitou",
    "dieci",
    "caterpillar",
    "cat",
    "haulotte",
    "magni",
    "jcb",
    "sinoboom",
    "heli",
    "skyjack",
    "bobcat",
    "lgmg",
    "liulong",
    "merlo",
    "snorkel",
    "niftylift",
    "zoomlion",
    "hyster",
    "crown",
    "linde",
    "komatsu",
    "volvo",
    "hitachi",
    "kubota",
    "liebherr",
    "bomag",
    "yanmar",
    "hyundai",
    "doosan",
  ];
  const brandInQuery = brandNames.find((b) => queryLower.includes(b));
  if (brandInQuery) {
    const machineBrand = (m.brand || "").toLowerCase();
    // "cat" matches "caterpillar" and vice versa
    const catAlias =
      brandInQuery === "cat"
        ? machineBrand.includes("caterpillar") || machineBrand.includes("cat")
        : brandInQuery === "caterpillar"
          ? machineBrand.includes("cat")
          : false;
    if (!machineBrand.includes(brandInQuery) && !catAlias) return false;
  }

  // ── Text bag matching for remaining tokens ──────────────────────────────
  // If query is purely numeric (e.g. "2.5 ton", "20m"), skip text matching
  const purelyNumeric =
    nums.capacity !== null || nums.height !== null || nums.reach !== null;
  const strippedQuery = queryLower
    .replace(
      /\d+(?:\.\d+)?\s*(?:t\b|ton(?:ne)?s?|tonne?s?|kg|m\b|metre?s?|meter?s?|ft|foot|feet|reach|outreach|lift|height|platform|working)/gi,
      "",
    )
    .trim();

  if (!purelyNumeric || strippedQuery.length > 1) {
    const bag = [
      m.name,
      m.shortName,
      m.brand,
      m.power,
      m.terrain,
      catKey,
      KYM_CAT_META[catKey]?.label,
      String(m.capacity || ""),
      String(m.liftHeight || ""),
      String(m.platformHeight || ""),
      String(m.workingHeight || ""),
      (m.tags || []).join(" "),
      m.bestFor,
      m.note,
      (m.filters || []).join(" "),
      isRotatingMachine
        ? "rotating rotational rotary 360 slewing crane replacement mrt rth roto"
        : "",
      m.isReachTruck
        ? "reach truck reachtruck reach stacker reachstacker high bay narrow aisle high reach high mast high lift warehouse racking"
        : "",
      !m.isReachTruck && m.liftHeight >= 6.5 && catKey === "forklift"
        ? "high mast high reach extended mast high lift"
        : "",
      (m.name || "").toLowerCase().includes("order picker")
        ? "order picker stockpicker pick truck high reach high lift"
        : "",
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    // Feet→metre conversion
    const ftMatch = query.match(/(\d+(?:\.\d+)?)\s*(?:ft|foot|feet)/i);
    const altBag = ftMatch
      ? bag + " " + (parseFloat(ftMatch[1]) * 0.3048).toFixed(1)
      : bag;

    const specTokens = kymSpecTokens(strippedQuery || query);
    // Skip text check if only numeric tokens remain after stripping
    const nonNumericTokens = specTokens.filter((t) => isNaN(t));
    if (
      nonNumericTokens.length > 0 &&
      !nonNumericTokens.every((t) => altBag.includes(t))
    )
      return false;
  }

  return true;
}

function kymRender() {
  const grid =
    document.getElementById("kym-results-grid2") ||
    document.getElementById("kym-results-grid");
  const count =
    document.getElementById("kym-results-count2") ||
    document.getElementById("kym-results-count");
  if (!grid) return;

  // ── Remove any previous Did You Mean banner ───────────────────────────
  const _prevBanner = document.getElementById("kym-dym-banner");
  if (_prevBanner) _prevBanner.remove();
  const _prevCtxNote = grid.previousElementSibling;
  if (_prevCtxNote && _prevCtxNote.id === "kym-dym-banner")
    _prevCtxNote.remove();

  // Determine which categories to search
  let cats;
  if (_kymCat) {
    cats = [_kymCat];
  } else if (_kymQuery) {
    const resolved = kymResolveCategories(_kymQuery);
    cats = resolved.size > 0 ? [...resolved] : Object.keys(KYM_CAT_META);
  } else {
    cats = Object.keys(KYM_CAT_META);
  }

  // Collect matching machines
  // Helper: resolve the machine array for a category key, including earthworks sub-types
  const _kymGetArr = (catKey) => {
    if (catKey === "em_excavator")
      return (MACHINES.earthworks || []).filter((m) => m.type === "excavator");
    if (catKey === "em_bobcat")
      return (MACHINES.earthworks || []).filter((m) => m.type === "bobcat");
    if (catKey === "em_grader")
      return (MACHINES.earthworks || []).filter((m) => m.type === "grader");
    if (catKey === "em_compactor")
      return (MACHINES.earthworks || []).filter((m) => m.type === "compactor");
    if (catKey === "em_dumper")
      return (MACHINES.earthworks || []).filter(
        (m) => m.type === "dumper" || m.type === "mining_truck",
      );
    if (catKey === "em_water_cart")
      return (MACHINES.earthworks || []).filter((m) => m.type === "water_cart");
    if (catKey === "em_mulcher")
      return (MACHINES.earthworks || []).filter((m) => m.type === "mulcher");
    return MACHINES[catKey] || [];
  };

  const results = [];
  cats.forEach((catKey) => {
    const arr = _kymGetArr(catKey);
    arr.forEach((m) => {
      if (kymMatchesQuery(m, catKey, _kymQuery)) {
        // Apply brand filter when active (dozer subcategory)
        if (_kymBrand && m.brand !== _kymBrand) return;
        results.push({ m, catKey });
      }
    });
  });

  // ── Brand filter pill row — shown when Dozers category is active ──────
  const brandRowId = "kym-brand-filter-row";
  let existingBrandRow = document.getElementById(brandRowId);
  if (existingBrandRow) existingBrandRow.remove();
  if (_kymCat === "dozer" && grid) {
    const brandRow = document.createElement("div");
    brandRow.id = brandRowId;
    brandRow.style.cssText =
      "display:flex;flex-wrap:wrap;align-items:center;gap:.5rem;margin-bottom:1rem;padding:.75rem 1rem;background:#FFFBEB;border:1.5px solid #FDE68A;border-radius:12px";
    const brandPills = DOZER_BRANDS.map((b) => {
      const isActive = _kymBrand === b.key;
      return `<button
        onclick="kymSetBrand('${b.key}')"
        style="
          background:${isActive ? b.color : "#fff"};
          color:${isActive ? b.textColor : "#374151"};
          border:2px solid ${b.color};
          border-radius:50px;
          padding:.3rem .9rem;
          font-family:'Nunito',sans-serif;
          font-weight:${isActive ? "800" : "600"};
          font-size:.82rem;
          cursor:pointer;
          transition:all .15s;
          ${isActive ? "box-shadow:0 2px 8px rgba(0,0,0,.18)" : ""}
        "
      >${b.label}</button>`;
    }).join("");
    brandRow.innerHTML = `
      <span style="font-size:.8rem;font-weight:700;color:#92400E;white-space:nowrap">🏷️ Brand:</span>
      ${brandPills}
      ${_kymBrand ? `<button onclick="kymSetBrand('')" style="background:transparent;border:none;color:#6B7280;font-size:.8rem;cursor:pointer;margin-left:.2rem;text-decoration:underline">Clear</button>` : ""}
    `;
    grid.parentNode.insertBefore(brandRow, grid);
  }

  // Update count label — show corrected query in count
  if (count) {
    const displayQuery = _kymQuery;
    const label = displayQuery
      ? `${results.length} machine${results.length !== 1 ? "s" : ""} matching "<strong>${displayQuery}</strong>"${_kymDidYouMeanQuery ? ' <span style="font-size:.8rem;color:#9A3412">(auto-corrected from "' + _kymDidYouMeanQuery.original + '")</span>' : ""}`
      : `${results.length} machine${results.length !== 1 ? "s" : ""} ${_kymCat ? "in " + (KYM_CAT_META[_kymCat]?.label.split(" ").slice(0, 2).join(" ") || _kymCat) : "across all categories"}`;
    count.innerHTML = label;
  }

  // ── "Did you mean?" banner — always shown when auto-corrected ─────────
  if (_kymDidYouMeanQuery) {
    const orig = _kymDidYouMeanQuery.original;
    const corr = _kymDidYouMeanQuery.corrected;
    const dym = document.createElement("div");
    dym.id = "kym-dym-banner";
    dym.style.cssText =
      "background:linear-gradient(135deg,#FFF7ED,#FFEDD5);border:1.5px solid #FDBA74;border-radius:12px;padding:.7rem 1rem;margin-bottom:.9rem;display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;font-size:.87rem";
    dym.innerHTML = `
      <span style="font-size:1.1rem">🔍</span>
      <div style="flex:1;min-width:200px">
        <span style="color:#92400E">Showing results for <strong style="color:#9A3412">"${corr}"</strong></span>
        <span style="color:#B45309;margin-left:.4rem">— Did you mean <strong>"${orig}"</strong>?</span>
      </div>
      <button onclick="(function(){
        var inp=document.getElementById('kym-search-input')||document.getElementById('kym-search-input2');
        if(inp)inp.value='${orig.replace(/'/g, "\'")}';
        _kymQuery='${orig.replace(/'/g, "\'")}';
        _kymDidYouMeanQuery=null;
        kymRender();
      })()" style="background:#fff;border:1.5px solid #F97316;border-radius:8px;padding:.3rem .85rem;font-size:.82rem;font-weight:700;color:#C2410C;cursor:pointer;white-space:nowrap;flex-shrink:0">
        Use original spelling
      </button>`;
    grid.parentNode.insertBefore(dym, grid);
  }

  if (results.length === 0) {
    grid.innerHTML = `<div style="grid-column:1/-1;padding:3rem;text-align:center;color:#94A3B8">
      <div style="font-size:2.5rem;margin-bottom:.8rem">🤷</div>
      <div style="font-weight:700;font-size:1.1rem;margin-bottom:.4rem;color:#64748B">No machines found</div>
      <div style="font-size:.9rem;color:#94A3B8;line-height:1.6">
        Try refining your search — some tips:<br>
        • <strong>"reach stacker"</strong> or <strong>"high reach forklift"</strong> → shows reach trucks &amp; high-mast forklifts<br>
        • <strong>"order picker"</strong> or <strong>"picking truck"</strong> → shows high-bay pickers<br>
        • <strong>"rotating telehandler"</strong> or <strong>"360 tele"</strong> → rotating ROTO/MRT/RTH models<br>
        • <strong>"electric rotating"</strong> → zero-emission rotating telehandlers (Magni ETH)<br>
        • Try: "electric forklift", "3T telehandler", "19m boom lift", "rough terrain scissor"
      </div>
    </div>`;
    return;
  }

  // ── Contextual note for reach stacker / high-reach queries ───────────────
  const _qLower = (_kymQuery || "").toLowerCase();
  const _reachStackerQuery =
    _qLower.includes("reach stacker") || _qLower.includes("reachstacker");
  const _highReachQuery =
    _qLower.includes("high reach") ||
    _qLower.includes("high mast") ||
    _qLower.includes("high lift");
  if (
    (_reachStackerQuery || _highReachQuery) &&
    grid.previousElementSibling?.classList?.contains("kym-context-note")
  ) {
    grid.previousElementSibling.remove();
  }
  if (_reachStackerQuery) {
    const note = document.createElement("div");
    note.className = "kym-context-note";
    note.style.cssText =
      "background:#EFF6FF;border:1.5px solid #93C5FD;border-radius:12px;padding:.85rem 1.1rem;margin-bottom:1rem;font-size:.85rem;color:#1D4ED8;line-height:1.6";
    note.innerHTML = `<strong>📋 Note on "Reach Stackers":</strong> Container reach stackers (port / intermodal equipment used to stack shipping containers) are specialist port machinery and not available in the general hire fleet shown here. What we carry are <strong>reach trucks</strong> (high-bay warehouse machines that reach into racking up to 12.5m) and <strong>high-mast counterbalance forklifts</strong> (extended mast for high storage bays). If you need a container handler or port stacker, please <a href="javascript:void(0)" onclick="(function(){const e='sales@noyo.com.au';window.location.href='mailto:'+e+'?subject=Container%20Handler%20Enquiry'})()" style="color:#1D4ED8;font-weight:700">contact us directly</a> on <a href="tel:+61450133133" style="color:#1D4ED8;font-weight:700">+61 450 133 133</a>.`;
    grid.parentNode.insertBefore(note, grid);
  }

  grid.innerHTML = results
    .map(({ m, catKey }) => {
      const meta = KYM_CAT_META[catKey] || { emoji: "🏗️", label: "Machine" };
      const inCart = quoteCart.some((c) => c.id === m.id);
      const cardId = "kym-" + (m.id || "").replace(/[^a-z0-9]/gi, "-");

      // ── Core spec pills ──────────────────────────────────────────
      const specs = [];
      if (m.isRotating)
        specs.push(
          `<span style="background:#F0FDF4;color:#15803D;border:1px solid #86EFAC;border-radius:6px;padding:.15rem .5rem;font-weight:800">🔄 360° Rotating</span>`,
        );
      if (m.isReachTruck)
        specs.push(
          `<span style="background:#EFF6FF;color:#1D4ED8;border:1px solid #93C5FD;border-radius:6px;padding:.15rem .5rem;font-weight:800">🏗️ Reach Truck</span>`,
        );
      if (m.capacity) specs.push(`<span>⚖️ ${m.capacity}T capacity</span>`);
      if (m.liftHeight) specs.push(`<span>📏 ${m.liftHeight}m lift</span>`);
      if (m.platformHeight)
        specs.push(`<span>📏 ${m.platformHeight}m platform</span>`);
      if (m.workingHeight) {
      } // working height not displayed — platform height only
      if (m.power) specs.push(`<span>⚡ ${m.power}</span>`);

      // ── Dozer-specific spec pills ─────────────────────────────────
      if (catKey === "dozer") {
        if (m.operatingWeightT)
          specs.push(
            `<span style="background:#FFF7ED;color:#C2410C;border:1px solid #FED7AA;border-radius:6px;padding:.15rem .5rem;font-weight:700">⚖️ ${m.operatingWeightT}t</span>`,
          );
        if (m.engineNetKW && m.engineNetHP)
          specs.push(
            `<span style="background:#FFF7ED;color:#C2410C;border:1px solid #FED7AA;border-radius:6px;padding:.15rem .5rem;font-weight:700">⚡ ${m.engineNetKW}kW / ${m.engineNetHP}hp</span>`,
          );
        if (m.engineModel)
          specs.push(
            `<span style="background:#F8FAFC;color:#475569;border:1px solid #E2E8F0;border-radius:6px;padding:.15rem .5rem;font-weight:600">🔧 ${m.engineModel}</span>`,
          );
        const _pw = (m.powertrain || "").split(" ").slice(0, 2).join(" ");
        if (_pw)
          specs.push(
            `<span style="background:#F8FAFC;color:#475569;border:1px solid #E2E8F0;border-radius:6px;padding:.15rem .5rem;font-weight:600">⚙️ ${_pw}</span>`,
          );
        if (m.groundPressureKPa)
          specs.push(
            `<span style="background:#F0FDF4;color:#166534;border:1px solid #86EFAC;border-radius:6px;padding:.15rem .5rem;font-weight:700">🌍 ${m.groundPressureKPa} kPa</span>`,
          );
        const _blades = m.blades && m.blades.length ? m.blades : [];
        const _bestBlade = _blades.reduce(
          (a, b) => ((b.capacityM3 || 0) > (a.capacityM3 || 0) ? b : a),
          _blades[0] || {},
        );
        if (_bestBlade && _bestBlade.capacityM3)
          specs.push(
            `<span style="background:#EFF6FF;color:#1D4ED8;border:1px solid #93C5FD;border-radius:6px;padding:.15rem .5rem;font-weight:700">🪣 ${_bestBlade.capacityM3}m³ blade</span>`,
          );
        if (m.fuelTankL)
          specs.push(
            `<span style="background:#F8FAFC;color:#475569;border:1px solid #E2E8F0;border-radius:6px;padding:.15rem .5rem;font-weight:600">⛽ ${m.fuelTankL}L tank</span>`,
          );
      }
      if (m.terrain) specs.push(`<span>🌍 ${m.terrain}</span>`);

      // ── Excavator-specific spec pills ──────────────────────────────
      if (catKey === "em_excavator") {
        // Weight class badge
        const _wcMap = {
          micro: "⚪ Micro",
          mini: "🔵 Mini",
          midi: "🟡 Midi",
          standard: "🟠 Standard",
          large: "🔴 Large",
          mining: "⚫ Mining",
        };
        if (m.weightClass)
          specs.push(
            `<span style="background:#FFFBEB;color:#92400E;border:1px solid #FDE68A;border-radius:6px;padding:.15rem .5rem;font-weight:800">${_wcMap[m.weightClass] || m.weightClass}</span>`,
          );
        // Core specs from real fields
        if (m.operatingWeightT)
          specs.push(
            `<span style="background:#FFF7ED;color:#C2410C;border:1px solid #FED7AA;border-radius:6px;padding:.15rem .5rem;font-weight:700">⚖️ ${m.operatingWeightT}t operating weight</span>`,
          );
        if (m.digDepthM)
          specs.push(
            `<span style="background:#EFF6FF;color:#1D4ED8;border:1px solid #93C5FD;border-radius:6px;padding:.15rem .5rem;font-weight:700">⛏️ ${m.digDepthM}m dig depth</span>`,
          );
        if (m.bucketCapM3)
          specs.push(
            `<span style="background:#F5F3FF;color:#7C3AED;border:1px solid #DDD6FE;border-radius:6px;padding:.15rem .5rem;font-weight:700">🪣 ${m.bucketCapM3}m³ bucket</span>`,
          );
        // Parse engine kW from note text (stored as "XX.XkW engine" or "XXkW engine")
        const _engMatch = (m.note || "").match(/(\d+\.?\d*)\s*kW/i);
        if (_engMatch)
          specs.push(
            `<span style="background:#F8FAFC;color:#475569;border:1px solid #E2E8F0;border-radius:6px;padding:.15rem .5rem;font-weight:600">⚡ ${_engMatch[1]}kW engine</span>`,
          );
        // Zero tail swing — check name and note
        const _nm = (m.name || "").toLowerCase(),
          _nt = (m.note || "").toLowerCase();
        if (
          _nm.includes("zts") ||
          _nm.includes("zero tail") ||
          _nt.includes("zero tail swing") ||
          _nm.includes("uts") ||
          _nm.includes("us-") ||
          _nm.includes("usb")
        )
          specs.push(
            `<span style="background:#F0FDF4;color:#166534;border:1px solid #86EFAC;border-radius:6px;padding:.15rem .5rem;font-weight:700">↩️ Zero Tail Swing</span>`,
          );
        // Tags (tight access etc.)
        if ((m.tags || []).includes("tight access"))
          specs.push(
            `<span style="background:#FEF3C7;color:#92400E;border:1px solid #FCD34D;border-radius:6px;padding:.15rem .5rem;font-weight:700">🚪 Tight access</span>`,
          );
        if ((m.tags || []).includes("indoor"))
          specs.push(
            `<span style="background:#F0FDF4;color:#166534;border:1px solid #86EFAC;border-radius:6px;padding:.15rem .5rem;font-weight:700">🏭 Indoor safe</span>`,
          );
        if ((m.tags || []).includes("long reach"))
          specs.push(
            `<span style="background:#EFF6FF;color:#1D4ED8;border:1px solid #93C5FD;border-radius:6px;padding:.15rem .5rem;font-weight:700">↔️ Long reach</span>`,
          );
        // Brand note if Various
        if (m.brand === "Various" && m.note) {
          // Extract brand examples from note (e.g. "Brands: Kubota U10, Yanmar SV08")
          const _brandsMatch = m.note.match(/[Bb]rands?:\s*([^.]+)/);
          if (_brandsMatch)
            specs.push(
              `<span style="background:#F8FAFC;color:#64748B;border:1px solid #E2E8F0;border-radius:6px;padding:.15rem .5rem;font-weight:600">🏭 e.g. ${_brandsMatch[1].trim()}</span>`,
            );
        }
      }

      // ── Generic earthworks spec pills ───────────────────────────
      if (catKey && catKey.startsWith("em_") && catKey !== "em_excavator") {
        if (m.operatingWeightT)
          specs.push(
            `<span style="background:#FFF7ED;color:#C2410C;border:1px solid #FED7AA;border-radius:6px;padding:.15rem .5rem;font-weight:700">⚖️ ${m.operatingWeightT}t</span>`,
          );
        // Parse engine from note
        const _engM2 = (m.note || "").match(/(\d+\.?\d*)\s*kW/i);
        if (_engM2)
          specs.push(
            `<span style="background:#F8FAFC;color:#475569;border:1px solid #E2E8F0;border-radius:6px;padding:.15rem .5rem;font-weight:600">⚡ ${_engM2[1]}kW</span>`,
          );
      }

      // ── Machine dimensions row ───────────────────────────────────
      // Dims stored either in mm (>30) or metres (<30) — normalise to metres
      const toM = (v) => (v > 30 ? v / 1000 : v);
      const dimParts = [];
      if (m.machineWeight)
        dimParts.push(
          `<span title="Machine weight">🏋️ ${m.machineWeight}kg</span>`,
        );
      if (m.machineHeight && m.machineHeight > 0)
        dimParts.push(
          `<span title="Stowed height">↕ ${toM(m.machineHeight).toFixed(2)}m H</span>`,
        );
      else if (m.stowedH && m.stowedH > 0)
        dimParts.push(
          `<span title="Stowed height">↕ ${toM(m.stowedH).toFixed(2)}m H</span>`,
        );
      if (m.machineWidth && m.machineWidth > 0)
        dimParts.push(
          `<span title="Width">↔ ${toM(m.machineWidth).toFixed(2)}m W</span>`,
        );
      else if (m.stowedW && m.stowedW > 0)
        dimParts.push(
          `<span title="Width">↔ ${toM(m.stowedW).toFixed(2)}m W</span>`,
        );
      if (m.machineLength && m.machineLength > 0)
        dimParts.push(
          `<span title="Length">↕ ${toM(m.machineLength).toFixed(2)}m L</span>`,
        );
      else if (m.stowedL && m.stowedL > 0)
        dimParts.push(
          `<span title="Length">↕ ${toM(m.stowedL).toFixed(2)}m L</span>`,
        );
      const dimsHtml = dimParts.length
        ? `<div style="display:flex;flex-wrap:wrap;gap:.35rem;font-size:.75rem;font-weight:600;color:#64748B;background:#F8FAFC;border-radius:8px;padding:.4rem .6rem;margin-top:.4rem">${dimParts.join("")}</div>`
        : "";

      // ── Attachment / options section per category ────────────────
      let attachHtml = "";

      if (catKey === "forklift") {
        const tyneOpts = (m.tyneOptions || ["1200mm"])
          .map(
            (t) =>
              `<label style="display:flex;align-items:center;gap:.3rem;cursor:pointer"><input type="checkbox" data-mid="${m.id}" data-opt="tyne" value="${t}" style="accent-color:#0052CC"> ${t}</label>`,
          )
          .join("");
        const slipOpts = (
          m.slipperOptions || ["1800mm slipper", "2400mm slipper"]
        )
          .map(
            (s) =>
              `<label style="display:flex;align-items:center;gap:.3rem;cursor:pointer"><input type="checkbox" data-mid="${m.id}" data-opt="attachment" value="${s}" style="accent-color:#0052CC"> ${s}</label>`,
          )
          .join("");
        const extraOpts = [
          "Jib Attachment",
          "Rotator",
          "Side Shift",
          "Fork Positioner",
        ]
          .map(
            (a) =>
              `<label style="display:flex;align-items:center;gap:.3rem;cursor:pointer"><input type="checkbox" data-mid="${m.id}" data-opt="attachment" value="${a}" style="accent-color:#0052CC"> ${a}</label>`,
          )
          .join("");
        attachHtml = `
        <div style="border-top:1px solid #E2E8F0;padding-top:.65rem;margin-top:.2rem">
          <div style="font-size:.75rem;font-weight:800;color:#0052CC;margin-bottom:.4rem">🔧 Tyne Size</div>
          <div style="display:flex;flex-wrap:wrap;gap:.35rem .9rem;font-size:.8rem;color:#334155;margin-bottom:.5rem">${tyneOpts}</div>
          <div style="font-size:.75rem;font-weight:800;color:#0052CC;margin-bottom:.4rem">📦 Slippers / Attachments</div>
          <div style="display:flex;flex-wrap:wrap;gap:.35rem .9rem;font-size:.8rem;color:#334155">${slipOpts}${extraOpts}</div>
        </div>`;
      } else if (catKey === "telehandler") {
        const isRotating =
          (m.name || "").toLowerCase().includes("rotat") ||
          (m.filters || []).includes("rotating");
        if (isRotating) {
          const opts = [
            "Man Basket",
            "Winch",
            "Jib Attachment",
            "Rotator Hook",
            "Pallet Forks",
          ]
            .map(
              (a) =>
                `<label style="display:flex;align-items:center;gap:.3rem;cursor:pointer"><input type="checkbox" data-mid="${m.id}" data-opt="attachment" value="${a}" style="accent-color:#E8001B"> ${a}</label>`,
            )
            .join("");
          attachHtml = `
          <div style="border-top:1px solid #E2E8F0;padding-top:.65rem;margin-top:.2rem">
            <div style="font-size:.75rem;font-weight:800;color:#E8001B;margin-bottom:.4rem">🔧 Rotating Telehandler Attachments</div>
            <div style="display:flex;flex-wrap:wrap;gap:.35rem .9rem;font-size:.8rem;color:#334155">${opts}</div>
          </div>`;
        } else {
          const opts = [
            "Jib Attachment",
            "Rotator",
            "Man Basket",
            "Pallet Forks",
            "Bucket",
            "Bale Grab",
          ]
            .map(
              (a) =>
                `<label style="display:flex;align-items:center;gap:.3rem;cursor:pointer"><input type="checkbox" data-mid="${m.id}" data-opt="attachment" value="${a}" style="accent-color:#E8001B"> ${a}</label>`,
            )
            .join("");
          attachHtml = `
          <div style="border-top:1px solid #E2E8F0;padding-top:.65rem;margin-top:.2rem">
            <div style="font-size:.75rem;font-weight:800;color:#E8001B;margin-bottom:.4rem">🔧 Telehandler Attachments</div>
            <div style="display:flex;flex-wrap:wrap;gap:.35rem .9rem;font-size:.8rem;color:#334155">${opts}</div>
          </div>`;
        }
      } else if (catKey === "boom") {
        const opts = [
          "Standard Basket (230kg)",
          "XC Capacity Basket (320kg+)",
          "Power to Basket (230V outlet)",
          "Jib Extension",
          "Bi-Fuel",
        ]
          .map(
            (a) =>
              `<label style="display:flex;align-items:center;gap:.3rem;cursor:pointer"><input type="checkbox" data-mid="${m.id}" data-opt="attachment" value="${a}" style="accent-color:#F59E0B"> ${a}</label>`,
          )
          .join("");
        attachHtml = `
        <div style="border-top:1px solid #E2E8F0;padding-top:.65rem;margin-top:.2rem">
          <div style="font-size:.75rem;font-weight:800;color:#B45309;margin-bottom:.4rem">🔧 Boom Lift Options</div>
          <div style="display:flex;flex-wrap:wrap;gap:.35rem .9rem;font-size:.8rem;color:#334155">${opts}</div>
        </div>`;
      } else if (catKey === "dozer") {
        // ── Dozer attachments / configuration options ──────────────
        const _dAttach = (m.attachmentsAvailable || []).slice(0, 6);
        if (_dAttach.length) {
          const _opts = _dAttach
            .map((a) => {
              const _aLabel = a.split("(")[0].trim();
              return `<label style="display:flex;align-items:center;gap:.3rem;cursor:pointer"><input type="checkbox" data-mid="${m.id}" data-opt="attachment" value="${_aLabel}" style="accent-color:#D97706"> ${_aLabel}</label>`;
            })
            .join("");
          attachHtml = `
          <div style="border-top:1px solid #FDE68A;padding-top:.65rem;margin-top:.4rem;background:linear-gradient(135deg,#FFFBEB,#FEF3C7);border-radius:0 0 10px 10px;margin-left:-.7rem;margin-right:-.7rem;padding:.65rem .8rem .5rem">
            <div style="font-size:.75rem;font-weight:800;color:#B45309;margin-bottom:.45rem">🔩 Configuration / Attachments</div>
            <div style="display:flex;flex-wrap:wrap;gap:.35rem .9rem;font-size:.79rem;color:#334155">${_opts}</div>
          </div>`;
        }
        // Brochure ref badge
        if (m.brochureRef) {
          attachHtml += `<div style="margin-top:.4rem;font-size:.68rem;color:#9CA3AF;font-style:italic">📄 Source: ${m.brochureRef}</div>`;
        }
      }

      // ── Excavator attachments / spec table ──────────────────────
      else if (catKey === "em_excavator") {
        const _excAtts = [
          "Standard bucket (included)",
          "Rock breaker / hammer",
          "Auger / boring head",
          "Grab / grapple bucket",
          "Ripper",
          "Tilting bucket",
          "Quick hitch",
        ]
          .map(
            (a) =>
              `<label style="display:flex;align-items:center;gap:.3rem;cursor:pointer"><input type="checkbox" data-mid="${m.id}" data-opt="attachment" value="${a}" style="accent-color:#C2410C"> ${a}</label>`,
          )
          .join("");
        // Spec table rows — only show fields that have data
        const _specRows = [
          m.operatingWeightT
            ? `<tr><td style="color:#64748B;padding:.22rem .4rem;font-size:.77rem">Operating weight</td><td style="font-weight:700;padding:.22rem .4rem;font-size:.77rem">${m.operatingWeightT}t</td></tr>`
            : "",
          m.digDepthM
            ? `<tr><td style="color:#64748B;padding:.22rem .4rem;font-size:.77rem">Max dig depth</td><td style="font-weight:700;padding:.22rem .4rem;font-size:.77rem">${m.digDepthM}m</td></tr>`
            : "",
          m.bucketCapM3
            ? `<tr><td style="color:#64748B;padding:.22rem .4rem;font-size:.77rem">Bucket capacity</td><td style="font-weight:700;padding:.22rem .4rem;font-size:.77rem">${m.bucketCapM3}m³</td></tr>`
            : "",
          (() => {
            const em = (m.note || "").match(/(\d+\.?\d*)\s*kW/i);
            return em
              ? `<tr><td style="color:#64748B;padding:.22rem .4rem;font-size:.77rem">Engine</td><td style="font-weight:700;padding:.22rem .4rem;font-size:.77rem">${em[1]}kW</td></tr>`
              : "";
          })(),
          m.weightClass
            ? `<tr><td style="color:#64748B;padding:.22rem .4rem;font-size:.77rem">Class</td><td style="font-weight:700;padding:.22rem .4rem;font-size:.77rem">${{ micro: "Micro", mini: "Mini", midi: "Midi", standard: "Standard", large: "Large", mining: "Mining" }[m.weightClass] || m.weightClass}</td></tr>`
            : "",
          (m.note || "").toLowerCase().includes("zero tail swing") ||
          (m.name || "").match(/ZTS|USB|TS\b/i)
            ? `<tr><td style="color:#64748B;padding:.22rem .4rem;font-size:.77rem">Tail swing</td><td style="font-weight:700;color:#16A34A;padding:.22rem .4rem;font-size:.77rem">Zero tail swing</td></tr>`
            : "",
          (m.tags || []).includes("tight access")
            ? `<tr><td style="color:#64748B;padding:.22rem .4rem;font-size:.77rem">Access</td><td style="font-weight:700;color:#92400E;padding:.22rem .4rem;font-size:.77rem">Tight access / backyard</td></tr>`
            : "",
          m.brand && m.brand !== "Various"
            ? `<tr><td style="color:#64748B;padding:.22rem .4rem;font-size:.77rem">Brand</td><td style="font-weight:700;padding:.22rem .4rem;font-size:.77rem">${m.brand}</td></tr>`
            : "",
        ]
          .filter(Boolean)
          .join("");

        const _brandNote =
          m.brand === "Various"
            ? (() => {
                const bm = (m.note || "").match(/[Bb]rands?:([^.]+)/);
                return bm
                  ? `<div style="font-size:.72rem;color:#64748B;margin-top:.3rem;font-style:italic">e.g. ${bm[1].trim()}</div>`
                  : "";
              })()
            : "";

        attachHtml = `
        <div style="border-top:1px solid #E2E8F0;padding-top:.65rem;margin-top:.2rem">
          ${_specRows ? `<table style="width:100%;border-collapse:collapse;margin-bottom:.55rem">${_specRows}</table>` : ""}
          ${_brandNote}
          <div style="font-size:.75rem;font-weight:800;color:#C2410C;margin-bottom:.4rem">🔩 Attachments / Options</div>
          <div style="display:flex;flex-wrap:wrap;gap:.35rem .9rem;font-size:.8rem;color:#334155">${_excAtts}</div>
        </div>`;
      }

      return `<div class="kym-result-card" id="${cardId}">
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:.5rem">
        <div style="flex:1;min-width:0">
          <div style="font-size:.72rem;font-weight:700;color:#16A34A;letter-spacing:.05em;text-transform:uppercase;margin-bottom:.2rem">${meta.emoji} ${KYM_CAT_META[catKey]?.label.split(" ")[0]} ${KYM_CAT_META[catKey]?.label.split(" ")[1] || ""}</div>
          <div style="font-weight:800;font-size:.97rem;color:#0F172A;line-height:1.25">${m.name}</div>
          ${m.brand ? `<div style="font-size:.78rem;color:#64748B;margin-top:.1rem">${m.brand}</div>` : ""}
        </div>
        <span style="font-size:1.7rem;flex-shrink:0">${meta.emoji}</span>
      </div>

      ${specs.length ? `<div style="display:flex;flex-wrap:wrap;gap:.35rem;font-size:.77rem;font-weight:700;color:#475569;margin-top:.4rem">${specs.join("")}</div>` : ""}

      ${dimsHtml}

      ${m.bestFor ? `<div style="font-size:.8rem;color:#64748B;line-height:1.5;border-top:1px solid #F1F5F9;padding-top:.55rem;margin-top:.4rem">${m.bestFor}</div>` : ""}

      ${attachHtml}

      ${
        currentUser &&
        (currentUser.role === "rental" || currentUser.role === "admin_rental")
          ? `<div style="margin-top:.7rem;background:#F1F5F9;border:1.5px solid #E2E8F0;border-radius:10px;padding:.5rem .8rem;font-size:.78rem;color:#94A3B8;font-weight:700;text-align:center">🔒 Log in as a customer to add to hire enquiry</div>`
          : currentUser && currentUser.role === "lite"
            ? `<div style="margin-top:.7rem;background:rgba(14,165,233,.07);border:1.5px solid rgba(14,165,233,.25);border-radius:10px;padding:.5rem .8rem;font-size:.78rem;color:#38BDF8;font-weight:700;text-align:center">ℹ️ For information only — contact a rental company to hire</div>`
            : `<button class="kym-add-btn" id="kym-cart-btn-${(m.id || "").replace(/[^a-z0-9]/gi, "-")}" style="margin-top:.7rem;width:100%" onclick="addToCartFromKYM('${m.id}','${(m.name || "").replace(/'/g, "\\\\'")}','${catKey}',this)">🛒 Add to Quote</button>`
      }
    </div>`;
    })
    .join("");
  // Always update cart button count after render
  setTimeout(_kymUpdateCartBtn, 0);
}

function addToCartFromKYM(machineId, machineName, catKey, btn) {
  const meta = KYM_CAT_META[catKey] || {};
  const already = quoteCart.find((c) => c.id === machineId);
  if (already) {
    showToast("Already in cart", "#64748B");
    return;
  }

  // Collect any checked attachment / tyne options from this card
  const cardId = "kym-" + (machineId || "").replace(/[^a-z0-9]/gi, "-");
  const card = document.getElementById(cardId);
  const tynes = [];
  const attachments = [];
  if (card) {
    card
      .querySelectorAll('input[type=checkbox][data-opt="tyne"]:checked')
      .forEach((cb) => tynes.push(cb.value));
    card
      .querySelectorAll('input[type=checkbox][data-opt="attachment"]:checked')
      .forEach((cb) => attachments.push(cb.value));
  }

  quoteCart.push({
    id: machineId,
    name: machineName,
    emoji: meta.emoji || "🏗️",
    type: catKey,
    tynes: tynes.length ? tynes : undefined,
    attachments: attachments.length ? attachments : undefined,
    jobRequirements: getJobRequirements ? getJobRequirements() : {},
  });
  saveCartToStorage();
  updateCartUI();
  const extras = [...tynes, ...attachments];
  const extraStr = extras.length ? ` + ${extras.join(", ")}` : "";

  // Update the button to show "In Cart" state without re-rendering
  if (btn) {
    btn.textContent = "✓ In Cart";
    btn.disabled = true;
    btn.style.background = "#16A34A";
    btn.style.cursor = "default";
    btn.style.opacity = "0.8";
  }
  showToast(`🛒 ${machineName}${extraStr} added`, "#16A34A");
  if (btn) {
    btn.textContent = "✓ In Cart";
    btn.classList.add("in-cart");
    btn.disabled = true;
  }
  _kymUpdateCartBtn();
}

function _kymUpdateCartBtn() {
  const n = quoteCart ? quoteCart.length : 0;

  // KYM header button
  const headerBtn = document.getElementById("kym-cart-header-btn");
  const headerCount = document.getElementById("kym-cart-header-count");
  if (headerBtn) {
    headerBtn.style.display = n > 0 ? "inline-flex" : "none";
    if (headerCount) headerCount.textContent = n;
  }

  // Home page cart button — always visible, shows count (greyed when empty)
  const homeWrap = document.getElementById("home-cart-btn-wrap");
  const homeCount = document.getElementById("home-cart-count");
  const homeBtn = document.getElementById("home-cart-btn");
  if (homeWrap) {
    homeWrap.style.display = "block";
    if (homeCount) homeCount.textContent = n;
    if (homeBtn) {
      if (n > 0) {
        homeBtn.style.opacity = "1";
        homeBtn.style.cursor = "pointer";
        homeBtn.disabled = false;
        homeBtn.innerHTML =
          '🛒 <span id="home-cart-count">' +
          n +
          "</span> machine(s) in cart &mdash; Send Hire Enquiry &rarr;";
      } else {
        homeBtn.style.opacity = "0.45";
        homeBtn.style.cursor = "default";
        homeBtn.disabled = true;
        homeBtn.innerHTML =
          "🛒 Your cart is empty &mdash; add machines to get quotes";
      }
    }
  }
}

// ── end Know Your Machines ───────────────────────────────────────────

function addToCartDirect(machineId, machineName, _overrideType) {
  const typeEmojis = {
    forklift: "🍴",
    telehandler: "🏗️",
    scissor: "SL",
    boom: "💥",
    material: "📦",
    pushAround: "🧍",
    palletJack: "🔄",
    em_excavator: "⛏️",
    em_bobcat: "🚜",
    em_dozer: "🏔️",
    em_grader: "🛣️",
    em_compactor: "🔄",
    em_dumper: "🚛",
    em_water_cart: "💧",
    em_mulcher: "🌿",
  };
  const already = quoteCart.find((m) => m.id === machineId);
  if (already) {
    showToast("Already in cart", "#64748B");
    return;
  }
  const _useType = _overrideType || machineType;
  quoteCart.push({
    id: machineId,
    name: machineName,
    emoji: typeEmojis[_useType] || "💥",
    type: _useType,
    _isEarthworks: !!(_useType && _useType.startsWith("em_")),
    jobRequirements: getJobRequirements(),
  });
  saveCartToStorage();
  updateCartUI();
  showToast(`🛒 ${machineName} added to Hire Cart`, "#0052CC");
  // Update all card buttons for this machine to "✅ In Hire Enquiry"
  const _btnId = "cart-btn-" + machineId.replace(/[^a-z0-9]/gi, "-");
  document.querySelectorAll('[id="' + _btnId + '"]').forEach((btn) => {
    btn.outerHTML = `<div id="${_btnId}" style="flex:1;min-width:130px;background:linear-gradient(135deg,#166534,#15803D);border:none;color:#fff;border-radius:10px;padding:.65rem .8rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.85rem;text-align:center;display:flex;align-items:center;justify-content:center;gap:.4rem">✅ In Hire Enquiry</div>`;
  });
  // Track cart add
  try {
    const _cFields = { cartAdds: 1 };
    if (machineType) _cFields[`categories.${machineType}`] = 0; // already counted in search
    const _safeId = machineId.replace(/[.\/\[\]]/g, "_");
    _cFields[`machines.${_safeId}.cartAdds`] = 1;
    _noyoTrack(_cFields);
    if (window._lastSearchId)
      adminTrackCartAdd(window._lastSearchId, machineName);
  } catch (e) {}
}

// ── Timer refresh ────────────────────────────────────────────
setInterval(() => {
  if (quoteInbox.length) renderQuoteInbox();
}, 30000);

// ── Background Firestore reload every 60s — picks up new quotes/responses without page refresh ──
setInterval(async () => {
  if (!currentUser || !_fbDb) return;
  if (window._bgReloadRunning) return; // prevent stacking on slow connections
  window._bgReloadRunning = true;
  const _prevResponseCount = quoteInbox.reduce(
    (s, r) => s + (r.responses || []).length,
    0,
  );
  const _prevAcceptedCount = quoteInbox.filter((r) => r.acceptedBy).length;
  const _prevEnquiryCount = quoteInbox.length;
  const _prevEnquiryIds = new Set(quoteInbox.map((r) => r.id));
  try {
    await loadInboxFromFirebase();
    const _newResponseCount = quoteInbox.reduce(
      (s, r) => s + (r.responses || []).length,
      0,
    );
    const _newAcceptedCount = quoteInbox.filter((r) => r.acceptedBy).length;
    const _newEnquiryCount = quoteInbox.length;
    // Notify customer when new responses arrive
    if (
      currentUser.role === "customer" &&
      _newResponseCount > _prevResponseCount
    ) {
      const _diff = _newResponseCount - _prevResponseCount;
      noyoPlaySound("quote");
      noyoPushNotif({
        icon: "💬",
        title: `${_diff} new quote${_diff > 1 ? "s" : ""} received!`,
        sub: "A rental company has priced your hire enquiry. Tap to compare quotes.",
        actionLabel: "📋 View My Hire Enquiries →",
        actionFn: () => switchView("my-quotes"),
        duration: 12000,
      });
      noyoFlashTab("tab-my-quotes");
      updateMQUnreadBadge();
    }
    // Notify rental co when new enquiries arrive
    if (currentUser.role === "rental" && _newEnquiryCount > _prevEnquiryCount) {
      const _newJobs = quoteInbox.filter((r) => !_prevEnquiryIds.has(r.id));
      const _diff = _newJobs.length;
      // Play sound
      noyoPlaySound("enquiry");
      // Push notification card
      noyoPushNotif({
        icon: "🔔",
        title: `${_diff} new hire enquir${_diff > 1 ? "ies" : "y"} just arrived!`,
        sub: _newJobs
          .map(
            (j) =>
              (j.machines || []).map((m) => m.name || m.id).join(", ") ||
              "New enquiry",
          )
          .slice(0, 2)
          .join(" · "),
        actionLabel: "👀 View Quote Requests →",
        actionFn: () => switchView("quote-requests"),
        duration: 12000,
      });
      // Flash the tab
      noyoFlashTab("tab-quote-requests");
      updateQRUnreadBadge();
    }
    // Notify rental co when a quote they submitted was accepted
    if (
      currentUser.role === "rental" &&
      _newAcceptedCount > _prevAcceptedCount
    ) {
      noyoPlaySound("enquiry");
      noyoPushNotif({
        icon: "🏆",
        title: "A customer accepted your quote!",
        sub: "Congratulations — you won this job. Check Quote Requests for details.",
        actionLabel: "🏆 View Accepted Quote →",
        actionFn: () => switchView("quote-requests"),
        duration: 15000,
      });
      noyoFlashTab("tab-quote-requests");
      updateQRUnreadBadge();
    }
    // Always refresh badge for rental co after any reload
    if (currentUser.role === "rental") updateQRUnreadBadge();
    // Notify rental co when an acceptance window closes with no decision (once per enquiry)
    if (currentUser.role === "rental") {
      const myName = currentUser?.name;
      const _noDecisionKey = "noyo_nodecision_notified";
      let _notified = {};
      try {
        _notified = JSON.parse(localStorage.getItem(_noDecisionKey) || "{}");
      } catch (e) {}
      let _changed = false;
      quoteInbox.forEach((r) => {
        if (_notified[r.id]) return; // already told them
        const iResponded = (r.responses || []).some(
          (p) => p.company === myName,
        );
        if (!iResponded) return;
        if (r.acceptedBy) return; // decided — not a ghost
        if (!r.customerAcceptExpires) return;
        if (Date.now() <= r.customerAcceptExpires) return; // window still open
        // Window just closed with no decision — notify once
        _notified[r.id] = Date.now();
        _changed = true;
        showToast(
          `⏳ No decision yet on enquiry ${r.id} — the customer's accept window has closed. Noyo will follow up with them.`,
          "#B45309",
          9000,
        );
      });
      if (_changed) {
        try {
          localStorage.setItem(_noDecisionKey, JSON.stringify(_notified));
        } catch (e) {}
      }
    }
    // Update admin follow-up badge whenever inbox reloads
    try {
      _updateFollowUpBadge();
    } catch (e) {}
    renderQuoteInbox();
    renderMyQuotes();
  } catch (e) {
    console.warn("[Noyo] Background reload failed:", e.message);
  } finally {
    window._bgReloadRunning = false;
  }
}, 60000);

// ── Toast helper ─────────────────────────────────────────────
function showToast(msg, bg = "#27AE60", durationMs = 3500) {
  const t = document.createElement("div");
  t.className = "noyo-toast";
  t.style.background = bg;
  // Support HTML in msg (for links etc.)
  if (msg && (msg.includes("<a ") || msg.includes("<strong>"))) {
    t.innerHTML = msg;
  } else {
    t.textContent = msg;
  }
  document.body.appendChild(t);
  setTimeout(() => t.remove(), durationMs);
}

// ── Notification sound using Web Audio API (no file needed) ──────────────
function noyoPlaySound(type = "enquiry") {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const now = ctx.currentTime;
    if (type === "enquiry") {
      // Two-tone ascending ding — friendly but noticeable
      [
        [520, 0, 0.12],
        [780, 0.13, 0.22],
        [1040, 0.25, 0.18],
      ].forEach(([freq, start, dur]) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.type = "sine";
        osc.frequency.setValueAtTime(freq, now + start);
        gain.gain.setValueAtTime(0, now + start);
        gain.gain.linearRampToValueAtTime(0.18, now + start + 0.03);
        gain.gain.exponentialRampToValueAtTime(0.001, now + start + dur);
        osc.start(now + start);
        osc.stop(now + start + dur + 0.05);
      });
    } else if (type === "quote") {
      // Single soft chime for customer
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = "sine";
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.exponentialRampToValueAtTime(660, now + 0.25);
      gain.gain.setValueAtTime(0.15, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
      osc.start(now);
      osc.stop(now + 0.55);
    }
  } catch (e) {
    /* audio blocked — silent fallback */
  }
}

// ── Push notification card (top-right, like iOS/Android) ─────────────────
function noyoPushNotif({
  icon,
  title,
  sub,
  actionLabel,
  actionFn,
  duration = 8000,
}) {
  // Remove any existing push notif
  document.querySelectorAll(".noyo-push-notif").forEach((el) => el.remove());

  const el = document.createElement("div");
  el.className = "noyo-push-notif";
  const now = new Date().toLocaleTimeString("en-AU", {
    hour: "2-digit",
    minute: "2-digit",
  });
  el.innerHTML = `
    <div class="noyo-push-top">
      <img src="/assets/noyo-icon.png" onerror="this.style.display='none'" style="width:16px;height:16px;border-radius:4px;flex-shrink:0">
      <span class="noyo-push-app">Noyo</span>
      <span class="noyo-push-time">${now}</span>
      <button class="noyo-push-close" onclick="this.closest('.noyo-push-notif').remove()">✕</button>
    </div>
    <div class="noyo-push-body">
      <div class="noyo-push-icon">${icon}</div>
      <div>
        <div class="noyo-push-title">${title}</div>
        <div class="noyo-push-sub">${sub}</div>
      </div>
    </div>
    ${actionLabel ? `<button class="noyo-push-action" id="_push_action">${actionLabel}</button>` : ""}
  `;
  document.body.appendChild(el);

  if (actionLabel && actionFn) {
    el.querySelector("#_push_action").onclick = () => {
      actionFn();
      el.remove();
    };
  }

  // Auto-dismiss
  const timer = setTimeout(() => {
    el.classList.add("removing");
    setTimeout(() => el.remove(), 320);
  }, duration);
  el.querySelector(".noyo-push-close").addEventListener("click", () =>
    clearTimeout(timer),
  );
}

// ── Flash nav tab to draw attention ──────────────────────────────────────
function noyoFlashTab(tabId) {
  const el = document.getElementById(tabId);
  if (!el) return;
  el.classList.remove("nav-tab-alerting");
  void el.offsetWidth; // reflow
  el.classList.add("nav-tab-alerting");
  setTimeout(() => el.classList.remove("nav-tab-alerting"), 3200);
}

