// ── My Details suburb autocomplete ───────────────────────────────────
var _detSuburbDebounce = null;
function detSuburbInput(val) {
  clearTimeout(_detSuburbDebounce);
  const drop = document.getElementById("det-suburb-drop");
  const cityEl = document.getElementById("det-city-input");
  const stateEl = document.getElementById("det-state-input");

  // Immediate city detection from partial match
  const result = detectCityFromAddress(val);
  if (result) {
    if (cityEl) cityEl.value = result[0];
    if (stateEl) stateEl.value = result[1];
  } else {
    if (cityEl) cityEl.value = "";
    if (stateEl) stateEl.value = "";
  }

  // Dropdown suggestions — uses _suburbMatches for multi-city support
  _detSuburbDebounce = setTimeout(() => {
    if (!val || val.length < 2) {
      if (drop) drop.style.display = "none";
      return;
    }
    const matches = _suburbMatches(val.toLowerCase().trim());
    if (!matches.length) {
      if (drop) drop.style.display = "none";
      return;
    }
    if (drop) {
      drop.innerHTML = matches
        .map((m) => {
          const display = m.suburb
            .split(" ")
            .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
            .join(" ");
          return `<div onclick="detSuburbSelect('${m.suburb}','${display}','${m.city}','${m.state}')"
          style="padding:.55rem .9rem;cursor:pointer;font-size:.88rem;border-bottom:1px solid #F1F5F9"
          onmouseover="this.style.background='#EFF6FF'" onmouseout="this.style.background=''">
          <strong>${display}</strong> <span style="color:#64748B;font-size:.8rem">${m.city}, ${m.state}</span></div>`;
        })
        .join("");
      drop.style.display = "block";
    }
  }, 150);
}

function detSuburbSelect(key, display, city, state) {
  const inp = document.getElementById("det-suburb-input");
  const cityEl = document.getElementById("det-city-input");
  const stateEl = document.getElementById("det-state-input");
  const drop = document.getElementById("det-suburb-drop");
  if (inp) inp.value = display;
  if (cityEl) cityEl.value = city;
  if (stateEl) stateEl.value = state;
  if (drop) drop.style.display = "none";
}

function saveDetailsSuburb() {
  if (!currentUser) return;
  const suburb = (
    document.getElementById("det-suburb-input")?.value || ""
  ).trim();
  const city = (document.getElementById("det-city-input")?.value || "").trim();
  const state = (
    document.getElementById("det-state-input")?.value || ""
  ).trim();
  // Save to Firestore
  if (currentUser.uid) {
    _fbSaveUserProfile(currentUser.uid, { suburb, city, state });
    if (currentUser.role === "rental")
      _fbSaveRentalProfile(currentUser.uid, { suburb, city, state });
  }
  // Keep RENTAL_COMPANIES in sync — update baseCity so distance routing works immediately
  if (currentUser.role === "rental" && city) {
    const co = RENTAL_COMPANIES.find(
      (c) =>
        c.email && c.email.toLowerCase() === currentUser.email.toLowerCase(),
    );
    if (co) {
      co.baseCity = city;
      co.baseSuburb = suburb;
      co.cities = [city];
    }
    // Also update _sessionRegisteredOrg if present
    if (window._sessionRegisteredOrg) {
      _sessionRegisteredOrg.baseCity = city;
      _sessionRegisteredOrg.baseSuburb = suburb;
    }
  }
  showToast("Suburb & city saved ✓", "#16A34A");
}

