function _renderSectorGrid(gridId, selectedSectors) {
  const grid = document.getElementById(gridId);
  if (!grid) return;
  const sel = selectedSectors.map((s) => s.toLowerCase());
  const groups = [
    {
      label: "🏗️ Elevated Access",
      items: [
        "Boom Lifts (Articulated & Telescopic)",
        "SL Scissor Lifts, Vertical Lifts, Personnel Lifts",
        "Telehandlers and Rotating Telehandlers",
        "Material Hoists",
      ],
    },
    {
      label: "🍴 Material Handling",
      items: [
        "Forklifts, Reach Trucks, Pallet Jacks",
        "Electric Chain Hoists",
        "Glass Handling Equipment",
        "Material Handling Trolleys",
      ],
    },
    {
      label: "🏚️ Lifting & Rigging",
      items: [
        "Mini Cranes / Spider Cranes",
        "Mobile Cranes",
        "Rigging Equipment",
      ],
    },
    {
      label: "⛏️ Earthworks",
      items: [
        "Excavators (Tracked & Wheeled)",
        "Skid Steer Loaders & Bobcats",
        "Crawler Dozers & Bulldozers",
        "Motor Graders",
        "Compactors, Rollers & Plate Compactors",
        "Articulated Dump Trucks",
        "Wheel Loaders",
        "Water Carts",
      ],
    },
    {
      label: "⚡ Power & Site",
      items: [
        "Generators",
        "Lighting Towers",
        "Air Compressors",
        "Welding Machines",
        "Traffic Management Equipment",
        "Site Safety Equipment",
        "Portable Site Accommodation",
      ],
    },
  ];
  grid.innerHTML = groups
    .map((group) => {
      const allChecked = group.items.every((s) =>
        sel.includes(s.toLowerCase()),
      );
      return `<div style="margin-bottom:.7rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.25rem">
        <div style="font-size:.72rem;font-weight:900;color:#92400E;text-transform:uppercase;letter-spacing:.04em">${group.label}</div>
        <button type="button" onclick="_toggleSectorGroup(this,'${gridId}')"
          style="font-size:.68rem;color:#92400E;background:none;border:1px solid #FCD34D;border-radius:5px;padding:.1rem .4rem;cursor:pointer;font-family:'Nunito',sans-serif;font-weight:700">
          ${allChecked ? "✓ All" : "Select all"}
        </button>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:.18rem .5rem">
        ${group.items
          .map(
            (s) => `
          <label style="display:flex;align-items:center;gap:.4rem;font-size:.82rem;color:#334155;cursor:pointer;padding:.18rem .1rem;user-select:none">
            <input type="checkbox" value="${s}" ${sel.includes(s.toLowerCase()) ? "checked" : ""}
              style="width:14px;height:14px;min-height:14px;accent-color:#0052CC;cursor:pointer;flex-shrink:0">
            ${s}
          </label>`,
          )
          .join("")}
      </div>
    </div>`;
    })
    .join(
      '<hr style="border:none;border-top:1px solid #FEF3C7;margin:.1rem 0 .6rem">',
    );
}

function _toggleSectorGroup(btn, gridId) {
  const grid = document.getElementById(gridId);
  if (!grid) return;
  const groupDiv = btn.closest("div").nextElementSibling;
  if (!groupDiv) return;
  const cbs = groupDiv.querySelectorAll("input[type=checkbox]");
  const allChecked = Array.from(cbs).every((cb) => cb.checked);
  cbs.forEach((cb) => (cb.checked = !allChecked));
  btn.textContent = allChecked ? "Select all" : "✓ All";
}

