var _amExtracted = null; // last extracted machine object

function renderAdminAddMachine() {
  // No-op — the section HTML is static in index.html; just reset state
  _amExtracted = null;
  const form = document.getElementById("am-review-form");
  const status = document.getElementById("am-status");
  if (form) {
    form.style.display = "none";
    form.innerHTML = "";
  }
  if (status) {
    status.style.display = "none";
    status.innerHTML = "";
  }
  const fi = document.getElementById("am-file-input");
  if (fi) fi.value = "";
  // Show current API key status
  amRefreshKeyStatus();
}

function amGetApiKey() {
  try {
    return localStorage.getItem("noyo_claude_api_key") || "";
  } catch (e) {
    return "";
  }
}
function amSaveApiKey() {
  const inp = document.getElementById("am-apikey-input");
  const val = (inp?.value || "").trim();
  if (!val.startsWith("sk-ant-")) {
    showToast(
      "That doesn't look like a valid Anthropic API key (should start with sk-ant-)",
      "#EF4444",
    );
    return;
  }
  try {
    localStorage.setItem("noyo_claude_api_key", val);
  } catch (e) {}
  if (inp) inp.value = "";
  amRefreshKeyStatus();
  showToast("✅ API key saved — you can now extract machine specs", "#16A34A");
}
function amClearApiKey() {
  try {
    localStorage.removeItem("noyo_claude_api_key");
  } catch (e) {}
  amRefreshKeyStatus();
  showToast("API key cleared", "#64748B");
}
function amRefreshKeyStatus() {
  const key = amGetApiKey();
  const el = document.getElementById("am-apikey-status");
  if (!el) return;
  if (key) {
    el.textContent = "✅ Key saved — " + key.slice(0, 12) + "••••••••";
    el.style.color = "#16A34A";
  } else {
    el.textContent = "⚠️ Not set — enter your key above to enable extraction";
    el.style.color = "#DC2626";
  }
}

async function amHandleFile(file) {
  if (!file) return;
  const maxBytes = 20 * 1024 * 1024;
  if (file.size > maxBytes) {
    amStatus("❌ File too large (max 20 MB).", "error");
    return;
  }

  const isPdf =
    file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");
  const isImg =
    file.type.startsWith("image/") ||
    /\.(png|jpg|jpeg|heic|webp)$/i.test(file.name);
  if (!isPdf && !isImg) {
    amStatus(
      "❌ Unsupported file type. Use PDF, PNG, JPG, HEIC, or WEBP.",
      "error",
    );
    return;
  }

  amStatus("📄 Reading file…", "loading");

  // Convert to base64
  const base64 = await new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => res(r.result.split(",")[1]);
    r.onerror = () => rej(new Error("File read failed"));
    r.readAsDataURL(file);
  });

  const mediaType = isPdf ? "application/pdf" : file.type || "image/jpeg";

  amStatus(
    "🤖 Sending to Claude for extraction… this takes 15–30 seconds.",
    "loading",
  );

  // Validate API key before proceeding
  const _apiKey = amGetApiKey();
  if (!_apiKey) {
    amStatus(
      "❌ No API key set. Please enter your Anthropic API key in the field above first.",
      "error",
    );
    return;
  }

  const extractionPrompt = `You are a technical specification extractor for heavy equipment hire machines. Carefully read every part of this document.

IMPORTANT: Many brochures contain MULTIPLE machine models (e.g. ZMP04 and ZMP06, or a range of models in a table). You MUST extract EVERY machine model found and return them ALL.

REQUIRED OUTPUT: Return ONLY a valid JSON array — no markdown, no backticks, no explanation.
- If the document contains ONE machine: return a JSON array with one object: [{...}]
- If the document contains TWO OR MORE machines: return a JSON array with one object per machine: [{...}, {...}, ...]
- ALWAYS return an array, even for a single machine.
- Start with [ and end with ]

Extract every field you can find for each machine. Use null for anything not found. Numbers as numbers, not strings.

JSON schema for EACH machine object in the array:

{
  "brand": "string — manufacturer name e.g. JLG, Genie, Toyota, Manitou",
  "model": "string — model number/name e.g. 1350SJP, GT-5519",
  "name": "string — full display name e.g. JLG 1350SJP Boom Lift",
  "shortName": "string — short display name",
  "machineType": "one of: boom | scissor | telehandler | forklift | material | pushAround | palletJack",
  "isRotating": "boolean — true only for telehandlers with 360° slewing turret",
  "emoji": "single emoji representing the machine type",

  "capacity": "number — max rated capacity in TONNES (e.g. 4.0)",
  "capacityKg": "number — max rated capacity in kg",
  "capacityOnTyres": "number — capacity on tyres only in tonnes (for telehandlers/forklifts)",
  "capacityOnTyresKg": "number — capacity on tyres only in kg",
  "capacityOnOutriggers": "number — capacity with outriggers/stabilisers deployed in tonnes",
  "capacityOnOutriggersKg": "number — capacity with outriggers/stabilisers deployed in kg",
  "capacityOnJib": "number — capacity when jib attachment fitted in tonnes",
  "capacityOnJibKg": "number — capacity when jib attachment fitted in kg",
  "capacityOnRotator": "number — capacity when rotator fitted in tonnes",
  "capacityOnRotatorKg": "number — capacity when rotator fitted in kg",

  "liftHeight": "number — maximum lift/working height in metres",
  "platformHeight": "number — maximum platform height in metres",
  "workingHeight": "number — working height (platform + 2m) in metres",
  "maxReach": "number — maximum horizontal outreach in metres",
  "maxOutreach": "number — same as maxReach if separately stated",
  "upAndOverHeight": "number — maximum up-and-over height in metres",

  "swl": "number — Safe Working Load in kg (for EWP/scissor/boom)",
  "basketSWL": "number — basket/platform SWL in kg",
  "occupants": "number — maximum persons in basket",

  "jibWeight": "number — jib attachment weight in kg",
  "jibLength": "number — jib length in metres",
  "jibCapacity": "number — jib rated capacity in kg",
  "jibAngle": "string — jib articulation range e.g. '135°'",
  "rotatorWeight": "number — rotator attachment weight in kg",
  "rotatorCapacity": "number — rotator rated capacity in kg",

  "turretRotation": "number — turret slewing range in degrees (360 for continuous)",
  "boomRotation": "string — boom rotation description if applicable",

  "stabWidth": "number — outrigger/stabiliser spread width in mm when deployed",
  "stabDepth": "number — outrigger/stabiliser depth in mm when deployed",
  "stowedWidth": "number — machine stowed/transport width in mm",
  "stowedLength": "number — machine stowed/transport length in mm",
  "stowedHeight": "number — machine stowed/transport height in mm",
  "machineWeight": "number — machine weight in kg",
  "machineWidth": "number — machine width in mm",
  "machineLength": "number — machine length in mm",
  "machineHeight": "number — machine height in mm",

  "undercarriage": "one of: tyres | tracks | crawler | outriggers | skids",
  "tyreSize": "string — tyre size spec e.g. '400/80-24'",
  "trackWidth": "number — track width in mm (for crawler machines)",
  "gradeability": "string — max grade/slope e.g. '45%' or '24°'",
  "groundClearance": "number — ground clearance in mm",
  "turningRadius": "number — minimum turning radius in metres",

  "engine": "string — engine description e.g. 'Deutz D2011 L3 diesel 36kW'",
  "power": "string — power source: Diesel | Electric | LPG | Petrol | Hybrid | Dual Power",
  "enginePower": "number — engine power in kW",
  "fuelCapacity": "number — fuel tank capacity in litres",
  "hydraulicPressure": "number — hydraulic system pressure in bar",
  "hydraulicFlow": "number — hydraulic flow rate in L/min",

  "terrain": "one of: indoor | outdoor | indoor/outdoor | rough-terrain | crawler",
  "driveType": "string — e.g. '4WD', '2WD', 'Hydrostatic'",
  "steeringModes": "string — steering modes available",

  "loadChart": "string — brief summary of load chart information",
  "loadMatrix": "array of {height:number, reach:number, capacityKg:number} objects — extract key load chart data points if a load chart table is present",

  "certifications": "array of strings — e.g. ['AS/NZS 1418', 'EN280', 'ROPS', 'FOPS']",
  "attachments": "array of strings — available attachments/accessories",
  "tyneOptions": "array of strings — available tyne lengths (forklifts)",
  "filters": "array of strings — category filters that apply e.g. ['telehandler','outdoor']",
  "tags": "array of strings — searchable feature tags",

  "bestFor": "string — 1-2 sentences on best applications",
  "note": "string — comprehensive technical note capturing all important specs and warnings",

  "source": "string — document title, date, version if visible",
  "supplier": "string — Australian distributor/supplier if mentioned"
}`;

  try {
    const contentBlock = isPdf
      ? {
          type: "document",
          source: {
            type: "base64",
            media_type: "application/pdf",
            data: base64,
          },
        }
      : {
          type: "image",
          source: { type: "base64", media_type: mediaType, data: base64 },
        };

    const resp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": _apiKey,
        "anthropic-version": "2023-06-01",
        "anthropic-dangerous-direct-browser-access": "true",
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 4096,
        messages: [
          {
            role: "user",
            content: [contentBlock, { type: "text", text: extractionPrompt }],
          },
        ],
      }),
    });

    if (!resp.ok) {
      const err = await resp.json().catch(() => ({}));
      throw new Error(err.error?.message || `API error ${resp.status}`);
    }

    const data = await resp.json();
    const rawText = (data.content || [])
      .filter((b) => b.type === "text")
      .map((b) => b.text)
      .join("");

    // Strip any accidental markdown fences
    const cleaned = rawText
      .replace(/^```json\s*/i, "")
      .replace(/```$/, "")
      .trim();

    let extracted;
    try {
      extracted = JSON.parse(cleaned);
    } catch (parseErr) {
      // Try to find array or object in response
      const arrMatch = cleaned.match(/\[[\s\S]*\]/);
      const objMatch = cleaned.match(/\{[\s\S]*\}/);
      if (arrMatch) extracted = JSON.parse(arrMatch[0]);
      else if (objMatch) extracted = JSON.parse(objMatch[0]);
      else
        throw new Error(
          "Could not parse JSON from response. Try a cleaner PDF.",
        );
    }

    // Normalise to array — brochure may have 1 or many machines
    const machines = Array.isArray(extracted) ? extracted : [extracted];

    if (machines.length === 0)
      throw new Error("No machines found in document.");

    _amExtracted = machines;
    const plural =
      machines.length > 1 ? `${machines.length} machines` : "1 machine";
    amStatus(
      `✅ Found ${plural} — review and edit below, then save all to database.`,
      "success",
    );
    amRenderReviewForm(machines, file.name);
  } catch (e) {
    amStatus(`❌ Extraction failed: ${e.message}`, "error");
  }
}

function amStatus(msg, type) {
  const el = document.getElementById("am-status");
  if (!el) return;
  const colors = {
    loading: { bg: "#EFF6FF", border: "#BFDBFE", color: "#1E40AF" },
    success: { bg: "#F0FDF4", border: "#86EFAC", color: "#15803D" },
    error: { bg: "#FEF2F2", border: "#FCA5A5", color: "#DC2626" },
  };
  const c = colors[type] || colors.loading;
  el.style.display = "block";
  el.innerHTML = `<div style="background:${c.bg};border:1.5px solid ${c.border};border-radius:10px;padding:.75rem 1rem;font-size:.85rem;font-weight:700;color:${c.color};display:flex;align-items:center;gap:.6rem">
    ${type === "loading" ? '<span style="display:inline-block;animation:spin 1s linear infinite">⏳</span>' : ""}
    ${msg}
  </div>`;
}

function _amField(id, label, val, type = "text", opts = null) {
  const v = val != null ? val : "";
  if (type === "select" && opts) {
    const options = opts
      .map(
        (o) =>
          `<option value="${o}" ${o === v ? "selected" : ""}>${o}</option>`,
      )
      .join("");
    return `<div style="display:flex;flex-direction:column;gap:.2rem">
      <label style="font-size:.73rem;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:.03em">${label}</label>
      <select id="${id}" style="border:1.5px solid #CBD5E1;border-radius:7px;padding:.32rem .55rem;font-size:.83rem;font-family:inherit;background:#fff">
        <option value="">—</option>${options}
      </select></div>`;
  }
  if (type === "textarea") {
    return `<div style="display:flex;flex-direction:column;gap:.2rem">
      <label style="font-size:.73rem;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:.03em">${label}</label>
      <textarea id="${id}" rows="3" style="border:1.5px solid #CBD5E1;border-radius:7px;padding:.32rem .55rem;font-size:.83rem;font-family:inherit;resize:vertical;background:#fff">${v}</textarea></div>`;
  }
  if (type === "array") {
    const arrVal = Array.isArray(val) ? val.join(", ") : val || "";
    return `<div style="display:flex;flex-direction:column;gap:.2rem">
      <label style="font-size:.73rem;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:.03em">${label} <span style="font-weight:400;color:#94A3B8">(comma-separated)</span></label>
      <input type="text" id="${id}" value="${arrVal.replace(/"/g, "&quot;")}" style="border:1.5px solid #CBD5E1;border-radius:7px;padding:.32rem .55rem;font-size:.83rem;font-family:inherit;background:#fff"></div>`;
  }
  return `<div style="display:flex;flex-direction:column;gap:.2rem">
    <label style="font-size:.73rem;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:.03em">${label}</label>
    <input type="${type}" id="${id}" value="${String(v).replace(/"/g, "&quot;")}" style="border:1.5px solid #CBD5E1;border-radius:7px;padding:.32rem .55rem;font-size:.83rem;font-family:inherit;background:#fff"></div>`;
}

function amRenderReviewForm(machines, fileName) {
  const form = document.getElementById("am-review-form");
  if (!form) return;

  // Normalise to array
  if (!Array.isArray(machines)) machines = [machines];

  const g2 =
    "display:grid;grid-template-columns:1fr 1fr;gap:.65rem;margin-bottom:.9rem";
  const g3 =
    "display:grid;grid-template-columns:1fr 1fr 1fr;gap:.65rem;margin-bottom:.9rem";
  const g1 =
    "display:grid;grid-template-columns:1fr;gap:.65rem;margin-bottom:.9rem";
  const sh = (t) =>
    `<div style="font-size:.8rem;font-weight:900;color:#0052CC;text-transform:uppercase;letter-spacing:.05em;margin:.9rem 0 .4rem;border-bottom:2px solid #EFF6FF;padding-bottom:.25rem">${t}</div>`;

  // Render machine form fields for one machine (prefixed with machine index)
  const renderMachineFields = (d, idx) => `
    ${sh("Identity")}
    <div style="${g3}">
      ${_amField(`am-brand-${idx}`, "Brand", d.brand)}
      ${_amField(`am-model-${idx}`, "Model", d.model)}
      ${_amField(`am-name-${idx}`, "Full Name", d.name)}
    </div>
    <div style="${g3}">
      ${_amField(`am-shortName-${idx}`, "Short Name", d.shortName)}
      ${_amField(`am-machineType-${idx}`, "Machine Type", d.machineType, "select", ["boom", "scissor", "telehandler", "forklift", "material", "pushAround", "palletJack"])}
      ${_amField(`am-emoji-${idx}`, "Emoji", d.emoji)}
    </div>

    ${sh("Capacity")}
    <div style="${g3}">
      ${_amField(`am-capacityKg-${idx}`, "Capacity (kg)", d.capacityKg, "number")}
      ${_amField(`am-capacityOnTyresKg-${idx}`, "On Tyres (kg)", d.capacityOnTyresKg, "number")}
      ${_amField(`am-capacityOnOutriggersKg-${idx}`, "On Outriggers (kg)", d.capacityOnOutriggersKg, "number")}
    </div>

    ${sh("Height & Reach")}
    <div style="${g3}">
      ${_amField(`am-platformHeight-${idx}`, "Platform Height (m)", d.platformHeight, "number")}
      ${_amField(`am-workingHeight-${idx}`, "Working Height (m)", d.workingHeight, "number")}
      ${_amField(`am-maxReach-${idx}`, "Max Reach (m)", d.maxReach, "number")}
    </div>

    ${sh("Dimensions & Weight")}
    <div style="${g3}">
      ${_amField(`am-stowedWidth-${idx}`, "Width (mm)", d.stowedWidth, "number")}
      ${_amField(`am-stowedLength-${idx}`, "Length (mm)", d.stowedLength, "number")}
      ${_amField(`am-stowedHeight-${idx}`, "Height (mm)", d.stowedHeight, "number")}
    </div>
    <div style="${g2}">
      ${_amField(`am-machineWeight-${idx}`, "Machine Weight (kg)", d.machineWeight, "number")}
      ${_amField(`am-groundClearance-${idx}`, "Ground Clearance (mm)", d.groundClearance, "number")}
    </div>

    ${sh("Power & Engine")}
    <div style="${g3}">
      ${_amField(`am-power-${idx}`, "Power Source", d.power, "select", ["Electric", "Diesel", "LPG", "Petrol", "Hybrid", "Dual Power"])}
      ${_amField(`am-engine-${idx}`, "Engine", d.engine)}
      ${_amField(`am-terrain-${idx}`, "Terrain", d.terrain, "select", ["indoor", "outdoor", "indoor/outdoor", "rough-terrain", "crawler"])}
    </div>

    ${sh("Notes & Tags")}
    <div style="${g1}">
      ${_amField(`am-bestFor-${idx}`, "Best For", d.bestFor, "textarea")}
      ${_amField(`am-note-${idx}`, "Technical Note", d.note, "textarea")}
      ${_amField(`am-filters-${idx}`, "Filters", d.filters, "array")}
      ${_amField(`am-tags-${idx}`, "Tags", d.tags, "array")}
    </div>`;

  // Tab headers if multiple machines
  const tabNav =
    machines.length > 1
      ? `
    <div style="display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:1rem;border-bottom:2px solid #E2E8F0;padding-bottom:.6rem">
      ${machines
        .map(
          (d, i) => `
        <button id="am-tab-btn-${i}" onclick="amSwitchTab(${i},${machines.length})"
          style="background:${i === 0 ? "#0052CC" : "#F1F5F9"};color:${i === 0 ? "#fff" : "#64748B"};border:none;border-radius:8px;padding:.35rem .85rem;font-size:.82rem;font-weight:800;cursor:pointer;font-family:'Nunito',sans-serif">
          ${d.name || d.model || `Machine ${i + 1}`}
        </button>`,
        )
        .join("")}
    </div>`
      : "";

  form.style.display = "block";
  form.innerHTML = `
    <div style="background:#fff;border:1.5px solid #E2E8F0;border-radius:14px;padding:1.2rem 1.4rem">
      <div style="font-weight:900;color:#0F172A;font-size:1rem;margin-bottom:.2rem">
        📋 ${machines.length > 1 ? `${machines.length} Machines Found` : "Review Extracted Data"} — ${fileName}
      </div>
      ${machines.length > 1 ? `<div style="font-size:.78rem;color:#16A34A;font-weight:700;margin-bottom:.5rem">✅ ${machines.length} machines detected in this brochure — review each tab then save all at once.</div>` : ""}
      <div style="font-size:.78rem;color:#64748B;margin-bottom:1rem">Edit any field before saving. Greyed values were not found in the document.</div>

      ${tabNav}

      ${machines
        .map(
          (d, i) => `
        <div id="am-tab-panel-${i}" style="display:${i === 0 ? "block" : "none"}">
          ${renderMachineFields(d, i)}
        </div>`,
        )
        .join("")}

      <div id="am-save-status" style="margin-top:.8rem"></div>
      <div style="display:flex;gap:.75rem;margin-top:1.1rem;flex-wrap:wrap">
        <button onclick="amSaveMachine()" style="flex:1;min-width:180px;background:linear-gradient(135deg,#16A34A,#15803D);color:#fff;border:none;border-radius:10px;padding:.65rem 1.2rem;font-family:'Nunito',sans-serif;font-weight:900;font-size:.92rem;cursor:pointer">
          💾 Save ${machines.length > 1 ? `All ${machines.length} Machines` : "Machine"} to Database
        </button>
        <button onclick="renderAdminAddMachine()" style="background:#F1F5F9;color:#475569;border:1.5px solid #E2E8F0;border-radius:10px;padding:.65rem 1.2rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.88rem;cursor:pointer">
          ↩ Start Over
        </button>
      </div>
    </div>`;
}

function amSwitchTab(idx, total) {
  for (let i = 0; i < total; i++) {
    const panel = document.getElementById(`am-tab-panel-${i}`);
    const btn = document.getElementById(`am-tab-btn-${i}`);
    if (panel) panel.style.display = i === idx ? "block" : "none";
    if (btn) {
      btn.style.background = i === idx ? "#0052CC" : "#F1F5F9";
      btn.style.color = i === idx ? "#fff" : "#64748B";
    }
  }
}
function amReadForm(idx) {
  // idx = machine index (0, 1, 2...) — suffix for all field IDs
  const sfx = idx !== undefined ? `-${idx}` : "";
  const g = (id) => document.getElementById(id + sfx)?.value?.trim() || null;
  const gn = (id) => {
    const v = g(id);
    return v ? parseFloat(v) : null;
  };
  const ga = (id) => {
    const v = g(id);
    if (!v) return [];
    return v
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
  };

  const brand = g("am-brand") || "Unknown";
  const model = g("am-model") || "";
  const name = g("am-name") || `${brand} ${model}`.trim();
  const id =
    (brand + "-" + model)
      .toLowerCase()
      .replace(/[^a-z0-9]/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "") || `machine-${Date.now()}`;
  const machineType = g("am-machineType") || "boom";
  const typeEmojis = {
    boom: "💥",
    scissor: "✂️",
    telehandler: "🏗️",
    forklift: "🍴",
    material: "📦",
    pushAround: "🧍",
    palletJack: "🔄",
  };

  return {
    id,
    brand,
    model,
    name,
    shortName: g("am-shortName") || name,
    emoji: typeEmojis[machineType] || "🏗️",
    machineType,
    capacityKg: gn("am-capacityKg"),
    capacityOnTyresKg: gn("am-capacityOnTyresKg"),
    capacityOnOutriggersKg: gn("am-capacityOnOutriggersKg"),
    platformHeight: gn("am-platformHeight"),
    workingHeight: gn("am-workingHeight"),
    maxReach: gn("am-maxReach"),
    stowedWidth: gn("am-stowedWidth"),
    stowedLength: gn("am-stowedLength"),
    stowedHeight: gn("am-stowedHeight"),
    machineWeight: gn("am-machineWeight"),
    groundClearance: gn("am-groundClearance"),
    power: g("am-power"),
    engine: g("am-engine"),
    terrain: g("am-terrain") || "indoor",
    tags: ga("am-tags"),
    filters: ga("am-filters").length ? ga("am-filters") : [machineType],
    bestFor: g("am-bestFor"),
    note: g("am-note"),
    _customAdded: true,
    _addedAt: new Date().toISOString(),
    _addedBy: currentUser ? currentUser.email : "admin",
  };
}

async function amSaveMachine() {
  const saveStatus = document.getElementById("am-save-status");
  const machines = Array.isArray(_amExtracted) ? _amExtracted : [_amExtracted];
  const count = machines.length;

  if (saveStatus)
    saveStatus.innerHTML = `<div style="background:#EFF6FF;border:1.5px solid #BFDBFE;border-radius:9px;padding:.65rem 1rem;font-size:.85rem;font-weight:700;color:#1E40AF">⏳ Saving ${count} machine${count > 1 ? "s" : ""}…</div>`;

  const saved = [],
    failed = [];

  for (let i = 0; i < count; i++) {
    const machine = amReadForm(i);
    if (!machine.brand || machine.brand === "Unknown") {
      failed.push(`Machine ${i + 1}: missing brand`);
      continue;
    }

    try {
      await _fbDb.collection("custom_machines").doc(machine.id).set(machine);

      // Push to in-memory
      const existIdx = ALL_MACHINES.findIndex((m) => m.id === machine.id);
      if (existIdx > -1) ALL_MACHINES.splice(existIdx, 1);
      ALL_MACHINES.push(machine);
      const typeKey = machine.machineType;
      if (MACHINES[typeKey]) {
        const tIdx = MACHINES[typeKey].findIndex((m) => m.id === machine.id);
        if (tIdx > -1) MACHINES[typeKey].splice(tIdx, 1);
        MACHINES[typeKey].push(machine);
      }
      saved.push(machine.name);
    } catch (e) {
      failed.push(`${machine.name}: ${e.message}`);
    }
  }

  if (saveStatus) {
    if (saved.length > 0 && failed.length === 0) {
      saveStatus.innerHTML = `
        <div style="background:#F0FDF4;border:1.5px solid #86EFAC;border-radius:9px;padding:.65rem 1rem;font-size:.85rem;font-weight:700;color:#15803D">
          ✅ ${saved.length} machine${saved.length > 1 ? "s" : ""} saved and immediately active in search results:<br>
          ${saved.map((n) => `<span style="display:inline-block;background:#DCFCE7;border-radius:4px;padding:.05rem .4rem;margin:.15rem .2rem .15rem 0;font-size:.78rem">${n}</span>`).join("")}
        </div>`;
    } else if (saved.length > 0) {
      saveStatus.innerHTML = `
        <div style="background:#FEF3C7;border:1.5px solid #FCD34D;border-radius:9px;padding:.65rem 1rem;font-size:.85rem;font-weight:700;color:#92400E">
          ⚠️ Saved ${saved.length}, failed ${failed.length}: ${failed.join("; ")}
        </div>`;
    } else {
      saveStatus.innerHTML = `<div style="background:#FEF2F2;border:1.5px solid #FCA5A5;border-radius:9px;padding:.65rem 1rem;font-size:.85rem;font-weight:700;color:#DC2626">❌ Save failed: ${failed.join("; ")}</div>`;
    }
  }

  if (saved.length > 0)
    showToast(
      `✅ ${saved.length} machine${saved.length > 1 ? "s" : ""} added to database`,
      "#16A34A",
    );
}

// Load any previously saved custom machines from Firestore on boot
async function _loadCustomMachines() {
  try {
    const snap = await _fbDb.collection("custom_machines").get();
    snap.forEach((doc) => {
      const m = doc.data();
      if (!m.id || ALL_MACHINES.find((x) => x.id === m.id)) return; // skip duplicates
      ALL_MACHINES.push(m);
      const typeKey = m.machineType;
      if (typeKey && MACHINES[typeKey]) {
        if (!MACHINES[typeKey].find((x) => x.id === m.id))
          MACHINES[typeKey].push(m);
      }
    });
    if (snap.size > 0)
      console.log(`Loaded ${snap.size} custom machine(s) from Firestore.`);
  } catch (e) {
    console.warn("Could not load custom machines:", e.message);
  }
}

window.addEventListener("load", () => {
  if (typeof _fbDb !== "undefined") _loadCustomMachines();
});

function adminSendBillingReminder(email, company) {
  // Send an in-app notification + email-style reminder to a rental company
  const subject = encodeURIComponent(
    "Noyo Subscription Renewal Reminder — " + company,
  );
  const body = encodeURIComponent(
    "Hi " +
      company +
      ",\n\n" +
      "This is a friendly reminder from Noyo that your subscription is due for renewal soon.\n\n" +
      "To continue receiving quote requests and accessing the Noyo platform, please renew your plan before it expires.\n\n" +
      "Log in at noyo.com.au to manage your subscription.\n\n" +
      "If you have any questions, reply to this email or call us on +61 450 133 133.\n\n" +
      "Cheers,\nThe Noyo Team",
  );
  window.open("mailto:" + email + "?subject=" + subject + "&body=" + body);
  showToast("📧 Reminder drafted for " + company, "#0052CC");
}

// ── Auto-send 7-day billing reminders on admin login ──────────────────────
async function _checkBillingReminders() {
  try {
    const all = await _getAllRegisteredRentalCos();
    const now = Date.now();
    const soon = all.filter((c) => {
      if (!c.subscriptionEnd) return false;
      const daysLeft = Math.ceil(
        (new Date(c.subscriptionEnd) - now) / (1000 * 60 * 60 * 24),
      );
      return (
        daysLeft >= 0 &&
        daysLeft <= 7 &&
        c.approvalStatus === "approved" &&
        c.plan
      );
    });
    if (soon.length > 0) {
      // Show admin notification banner
      const existing = document.getElementById("billing-reminder-banner");
      if (existing) existing.remove();
      const banner = document.createElement("div");
      banner.id = "billing-reminder-banner";
      banner.style.cssText =
        "position:fixed;bottom:1.2rem;right:1.2rem;z-index:9999;background:linear-gradient(135deg,#FEF3C7,#FEF9C3);border:2px solid #FCD34D;border-radius:14px;padding:1rem 1.3rem;max-width:340px;box-shadow:0 8px 30px rgba(0,0,0,.15)";
      banner.innerHTML = `
        <div style="font-weight:900;color:#92400E;font-size:.92rem;margin-bottom:.4rem">⚠️ ${soon.length} Subscription${soon.length > 1 ? "s" : ""} Expiring Soon</div>
        ${soon
          .map((c) => {
            const d = Math.ceil(
              (new Date(c.subscriptionEnd) - now) / (1000 * 60 * 60 * 24),
            );
            return `<div style="font-size:.8rem;color:#78350F;margin-bottom:.2rem">• <strong>${c.company || c.name}</strong> — ${d === 0 ? "expires today" : d + "d left"}</div>`;
          })
          .join("")}
        <div style="display:flex;gap:.5rem;margin-top:.6rem">
          <button onclick="showAdminSection('billing',document.getElementById('admin-tab-billing'));this.closest('#billing-reminder-banner').remove()"
            style="background:#F59E0B;color:#fff;border:none;border-radius:8px;padding:.35rem .8rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.78rem;cursor:pointer">View Billing</button>
          <button onclick="this.closest('#billing-reminder-banner').remove()"
            style="background:rgba(0,0,0,.06);color:#92400E;border:none;border-radius:8px;padding:.35rem .8rem;font-family:'Nunito',sans-serif;font-weight:700;font-size:.78rem;cursor:pointer">Dismiss</button>
        </div>`;
      document.body.appendChild(banner);
    }
  } catch (e) {}
}

async function renderAdminBilling() {
  const el = document.getElementById("admin-sec-billing");
  if (!el) return;
  el.innerHTML = `<div style="color:#94A3B8;padding:2rem;text-align:center">Loading billing data…</div>`;

  // ── Load all rental companies from Firestore ──────────────────────────
  let allRcos = [];
  try {
    allRcos = await _getAllRegisteredRentalCos();
  } catch (e) {}

  // ── Helper: compute monthly billing for one company ───────────────────
  // Returns { base, overage, overageCount, total, included, used, remaining }
  function _billing(c) {
    const planKey = c.plan || null;
    const cfg = planKey ? NOYO_PLANS[planKey] : null;
    if (!cfg)
      return {
        base: 0,
        overage: 0,
        overageCount: 0,
        total: 0,
        included: 0,
        used: 0,
        remaining: 0,
        cfg: null,
      };
    const used = parseInt(c.enquiriesUsed || 0, 10);
    const included = cfg.included;
    const overCount = Math.max(0, used - included);
    const overage = overCount * cfg.extraPrice;
    return {
      base: cfg.price,
      overage,
      overageCount: overCount,
      total: cfg.price + overage,
      included,
      used,
      remaining: Math.max(0, included - used),
      cfg,
    };
  }

  // ── MRR calculations ──────────────────────────────────────────────────
  const activeRcos = allRcos.filter(
    (c) => c.approvalStatus === "approved" && c.plan,
  );
  const byPlan = { starter: [], growth: [], pro: [] };
  activeRcos.forEach((c) => {
    if (byPlan[c.plan]) byPlan[c.plan].push(c);
  });

  const mrrBase = activeRcos.reduce((s, c) => s + _billing(c).base, 0);
  const mrrOverage = activeRcos.reduce((s, c) => s + _billing(c).overage, 0);
  const mrrTotal = mrrBase + mrrOverage;

  const planMRR = (key) =>
    byPlan[key].reduce((s, c) => s + _billing(c).total, 0);
  const starterMRR = planMRR("starter"),
    growthMRR = planMRR("growth"),
    proMRR = planMRR("pro");

  // ── Quote revenue: earned vs rejected per company ─────────────────────
  // For each response on each quote: accepted=earned, rejected=lost
  const coStats = {}; // keyed by company name
  const _initCo = (name) => {
    if (!coStats[name])
      coStats[name] = {
        name,
        quotesReceived: 0,
        quotesResponded: 0,
        quotesWon: 0,
        quotesLost: 0,
        earnedRevenue: 0,
        rejectedRevenue: 0,
        pendingRevenue: 0,
      };
    return coStats[name];
  };
  quoteInbox.forEach((req) => {
    (req.responses || []).forEach((r) => {
      if (!r.company) return;
      const co = _initCo(r.company);
      co.quotesReceived++;
      co.quotesResponded++;
      const val = r.grandTotal || 0;
      if (r.accepted) {
        co.quotesWon++;
        co.earnedRevenue += val;
      } else if (r.rejected) {
        co.quotesLost++;
        co.rejectedRevenue += val;
      } else {
        // awaiting customer decision
        co.pendingRevenue += val;
      }
    });
  });
  // Also count quote requests received (not just responded)
  quoteInbox.forEach((req) => {
    // Each rental company that was a recipient
    (req.responses || []).forEach((r) => {
      if (r.company) _initCo(r.company);
    });
  });
  const coStatsList = Object.values(coStats).sort(
    (a, b) => b.earnedRevenue - a.earnedRevenue,
  );

  // ── By-region breakdown: quote activity by state/city ────────────────
  const regionStats = {}; // keyed by state
  const depotStats = {}; // keyed by city
  quoteInbox.forEach((req) => {
    const state = req.state || (req.suburb ? "" : "") || "—";
    const city = req.city || req.suburb || "—";
    const val = (req.responses || []).find((r) => r.accepted)?.grandTotal || 0;
    const hasResp = (req.responses || []).length > 0;
    const won = !!req.acceptedBy;

    if (state && state !== "—") {
      if (!regionStats[state])
        regionStats[state] = {
          quotes: 0,
          responses: 0,
          won: 0,
          earnedRevenue: 0,
        };
      regionStats[state].quotes++;
      if (hasResp) regionStats[state].responses++;
      if (won) {
        regionStats[state].won++;
        regionStats[state].earnedRevenue += val;
      }
    }
    if (city && city !== "—") {
      if (!depotStats[city])
        depotStats[city] = {
          quotes: 0,
          responses: 0,
          won: 0,
          earnedRevenue: 0,
        };
      depotStats[city].quotes++;
      if (hasResp) depotStats[city].responses++;
      if (won) {
        depotStats[city].won++;
        depotStats[city].earnedRevenue += val;
      }
    }
  });

  // ── Plan comparison averages ──────────────────────────────────────────
  function _planAvg(planKey) {
    const cos = byPlan[planKey] || [];
    if (!cos.length)
      return {
        count: 0,
        avgLeads: 0,
        avgWinRate: 0,
        avgEarned: 0,
        avgTotal: 0,
      };
    let totalLeads = 0,
      totalWon = 0,
      totalEarned = 0,
      totalBilled = 0;
    cos.forEach((c) => {
      const b = _billing(c);
      const st = coStats[c.name] || coStats[c.company] || {};
      totalLeads += b.used;
      totalWon += st.quotesWon || 0;
      totalEarned += st.earnedRevenue || 0;
      totalBilled += b.total;
    });
    const n = cos.length;
    return {
      count: n,
      avgLeads: (totalLeads / n).toFixed(1),
      avgWinRate:
        totalLeads > 0 ? Math.round((totalWon / totalLeads) * 100) : 0,
      avgEarned: Math.round(totalEarned / n),
      avgTotal: Math.round(totalBilled / n),
    };
  }
  const sAvg = _planAvg("starter"),
    gAvg = _planAvg("growth"),
    pAvg = _planAvg("pro");

  // ── AU dollar formatter ───────────────────────────────────────────────
  const $$ = (n) =>
    "$" +
    (n || 0).toLocaleString("en-AU", {
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    });

  // ── Plan badge helper ─────────────────────────────────────────────────
  function planBadgeHtml(key) {
    if (!key)
      return '<span style="color:#94A3B8;font-size:.75rem">No Plan</span>';
    const c = NOYO_PLANS[key];
    const colors = { starter: "#64748B", growth: "#0052CC", pro: "#7C3AED" };
    const bgs = { starter: "#F1F5F9", growth: "#EFF6FF", pro: "#F5F3FF" };
    return `<span style="background:${bgs[key] || "#F1F5F9"};color:${colors[key] || "#334155"};border-radius:20px;padding:.18rem .6rem;font-size:.74rem;font-weight:800">${c.label}${key === "growth" ? " ⭐" : ""}</span>`;
  }

  // ── RENDER ────────────────────────────────────────────────────────────
  el.innerHTML = `
    <div class="admin-section-title">💳 Billing & Revenue</div>

    <!-- ═══ MRR OVERVIEW ═══ -->
    <div style="background:linear-gradient(135deg,#0F172A,#1E293B);border:1.5px solid rgba(255,255,255,.08);border-radius:18px;padding:1.4rem 1.6rem;margin-bottom:1.4rem">
      <div style="font-size:.72rem;font-weight:800;color:#64748B;text-transform:uppercase;letter-spacing:.6px;margin-bottom:1rem">💰 Monthly Recurring Revenue — ${new Date().toLocaleString("en-AU", { month: "long", year: "numeric" })}</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1rem;margin-bottom:1.2rem">
        ${[
          [
            "Total MRR",
            $$(mrrTotal),
            "Base + overage combined",
            "#22C55E",
            "rgba(34,197,94,.12)",
          ],
          [
            "Base MRR",
            $$(mrrBase),
            "Subscriptions only",
            "#3B82F6",
            "rgba(59,130,246,.1)",
          ],
          [
            "Overage",
            $$(mrrOverage),
            "Extra enquiries billed",
            "#F59E0B",
            "rgba(245,158,11,.1)",
          ],
          [
            "Active Cos",
            activeRcos.length,
            "On a paid plan",
            "#A78BFA",
            "rgba(167,139,250,.1)",
          ],
        ]
          .map(
            ([l, v, s, col, bg]) => `
          <div style="background:${bg};border:1.5px solid ${col}33;border-radius:14px;padding:1rem 1.1rem;text-align:center">
            <div style="font-size:1.6rem;font-weight:900;color:${col}">${v}</div>
            <div style="font-size:.78rem;font-weight:800;color:#CBD5E1;margin-top:.1rem">${l}</div>
            <div style="font-size:.68rem;color:#64748B">${s}</div>
          </div>`,
          )
          .join("")}
      </div>
      <!-- Plan tier MRR bars -->
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:.8rem">
        ${[
          ["Starter", starterMRR, byPlan.starter.length, "#64748B", "#F1F5F9"],
          ["Growth ⭐", growthMRR, byPlan.growth.length, "#0052CC", "#EFF6FF"],
          ["Pro", proMRR, byPlan.pro.length, "#7C3AED", "#F5F3FF"],
        ]
          .map(([label, mrr, count, col, bg]) => {
            const pct = mrrTotal > 0 ? Math.round((mrr / mrrTotal) * 100) : 0;
            return `
          <div style="background:rgba(255,255,255,.04);border:1.5px solid rgba(255,255,255,.07);border-radius:12px;padding:.85rem 1rem">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.45rem">
              <span style="font-weight:800;color:#E2E8F0;font-size:.82rem">${label}</span>
              <span style="font-size:.72rem;color:#64748B">${count} co${count !== 1 ? "s" : ""}</span>
            </div>
            <div style="font-size:1.25rem;font-weight:900;color:${col};margin-bottom:.4rem">${$$(mrr)}/mo</div>
            <div style="background:rgba(255,255,255,.06);border-radius:4px;height:8px;overflow:hidden">
              <div style="width:${pct}%;height:100%;background:${col};border-radius:4px"></div>
            </div>
            <div style="font-size:.68rem;color:#64748B;margin-top:.3rem">${pct}% of total MRR</div>
          </div>`;
          })
          .join("")}
      </div>
    </div>

    <!-- ═══ STRIPE INTEGRATION STATUS ═══ -->
    <div style="background:rgba(99,102,241,.06);border:1.5px solid rgba(99,102,241,.25);border-radius:14px;padding:.9rem 1.2rem;margin-bottom:1.4rem;display:flex;align-items:center;gap:1rem;flex-wrap:wrap">
      <div style="font-size:1.4rem">💳</div>
      <div style="flex:1;min-width:200px">
        <div style="font-weight:800;color:#A5B4FC;font-size:.88rem">Stripe Integration</div>
        <div style="font-size:.76rem;color:#64748B;margin-top:.15rem">Connect Stripe to auto-sync subscription status, payment history, and failed payment alerts.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-wrap:wrap">
        <div style="background:rgba(255,200,50,.1);border:1px solid rgba(255,200,50,.35);border-radius:8px;padding:.35rem .75rem;font-size:.75rem;font-weight:800;color:#FCD34D">⚠️ Stripe keys not yet set</div>
        <button onclick="adminOpenStripeSetup()" style="background:#6366F1;color:#fff;border:none;border-radius:8px;padding:.4rem 1rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.8rem;cursor:pointer">Configure →</button>
      </div>
    </div>

    <!-- ═══ PER-COMPANY BILLING TABLE ═══ -->
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.7rem">
      <div style="font-size:.78rem;font-weight:800;color:#94A3B8;text-transform:uppercase;letter-spacing:.5px">📋 All Rental Companies — Subscription Status</div>
      <div style="font-size:.72rem;color:#64748B">${allRcos.filter((c) => c.approvalStatus === "approved").length} approved · ${allRcos.length} total registered</div>
    </div>
    <div style="overflow-x:auto;margin-bottom:1.6rem">
      <table style="width:100%;border-collapse:collapse;font-size:.78rem">
        <thead>
          <tr style="background:rgba(255,255,255,.04);border-bottom:2px solid rgba(255,255,255,.08)">
            <th style="padding:.5rem .7rem;text-align:left;color:#94A3B8;font-weight:800;white-space:nowrap">Company</th>
            <th style="padding:.5rem .7rem;text-align:left;color:#94A3B8;font-weight:800">Plan</th>
            <th style="padding:.5rem .7rem;text-align:left;color:#94A3B8;font-weight:800;white-space:nowrap">Sub Start</th>
            <th style="padding:.5rem .7rem;text-align:left;color:#94A3B8;font-weight:800;white-space:nowrap">Sub End / Renews</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Included</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Used</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Remaining</th>
            <th style="padding:.5rem .7rem;text-align:right;color:#94A3B8;font-weight:800">Base Fee</th>
            <th style="padding:.5rem .7rem;text-align:right;color:#94A3B8;font-weight:800">Overage $</th>
            <th style="padding:.5rem .7rem;text-align:right;color:#94A3B8;font-weight:800">Total Bill</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Payment</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Actions</th>
          </tr>
        </thead>
        <tbody>
          ${
            allRcos
              .filter(
                (c) =>
                  c.approvalStatus === "approved" ||
                  c.approvalStatus === "pending" ||
                  c.plan,
              )
              .map((c) => {
                const b = _billing(c);
                const now = Date.now();

                // Subscription dates
                const subStart = c.subscriptionStart
                  ? new Date(c.subscriptionStart)
                  : c.registeredAt
                    ? new Date(c.registeredAt)
                    : null;
                const subEnd = c.subscriptionEnd
                  ? new Date(c.subscriptionEnd)
                  : subStart
                    ? new Date(subStart.getTime() + 30 * 24 * 60 * 60 * 1000)
                    : null;
                const daysLeft = subEnd
                  ? Math.ceil((subEnd - now) / (1000 * 60 * 60 * 24))
                  : null;

                // Payment status logic
                const isOverdue =
                  c.paymentStatus === "overdue" ||
                  (daysLeft !== null && daysLeft < 0);
                const isExpiring =
                  daysLeft !== null && daysLeft >= 0 && daysLeft <= 7;
                const isPaid =
                  c.plan && !isOverdue && c.approvalStatus === "approved";
                const isNoPlan = !c.plan;
                const isPending = c.approvalStatus === "pending";

                // Row background
                const rowBg = isOverdue
                  ? "background:rgba(239,68,68,.08);border-left:3px solid #EF4444"
                  : isExpiring
                    ? "background:rgba(245,158,11,.07);border-left:3px solid #F59E0B"
                    : isPending
                      ? "background:rgba(253,230,138,.12)"
                      : "";

                const remColor =
                  b.remaining <= 2
                    ? "#EF4444"
                    : b.remaining <= 5
                      ? "#F59E0B"
                      : "#22C55E";

                // Payment badge
                const payBadge = isOverdue
                  ? '<span style="background:#FEF2F2;color:#DC2626;border:1px solid #FCA5A5;border-radius:20px;padding:.12rem .5rem;font-size:.7rem;font-weight:800">🔴 OVERDUE</span>'
                  : isExpiring
                    ? `<span style="background:#FEF3C7;color:#B45309;border:1px solid #FCD34D;border-radius:20px;padding:.12rem .5rem;font-size:.7rem;font-weight:800">⚠️ ${daysLeft}d left</span>`
                    : isPending
                      ? '<span style="background:#FEF9C3;color:#92400E;border:1px solid #FDE68A;border-radius:20px;padding:.12rem .5rem;font-size:.7rem;font-weight:800">⏳ Pending</span>'
                      : isNoPlan
                        ? '<span style="background:#F1F5F9;color:#94A3B8;border-radius:20px;padding:.12rem .5rem;font-size:.7rem;font-weight:800">— No Plan</span>'
                        : '<span style="background:#DCFCE7;color:#16A34A;border:1px solid #86EFAC;border-radius:20px;padding:.12rem .5rem;font-size:.7rem;font-weight:800">✅ Active</span>';

                const fmtDate = (d) =>
                  d
                    ? d.toLocaleDateString("en-AU", {
                        day: "2-digit",
                        month: "short",
                        year: "numeric",
                      })
                    : "—";

                return `<tr style="border-bottom:1px solid rgba(255,255,255,.05);${rowBg}">
              <td style="padding:.45rem .7rem">
                <div style="font-weight:800;color:${isOverdue ? "#EF4444" : "#E2E8F0"}">${c.company || c.name || "—"}</div>
                <div style="font-size:.68rem;color:#475569">${c.email}</div>
                <div style="font-size:.68rem;color:#64748B">${c.city || ""}${c.state ? " · " + c.state : ""}</div>
              </td>
              <td style="padding:.45rem .7rem">${planBadgeHtml(c.plan)}</td>
              <td style="padding:.45rem .7rem;font-size:.76rem;color:#94A3B8;white-space:nowrap">${fmtDate(subStart)}</td>
              <td style="padding:.45rem .7rem;font-size:.76rem;white-space:nowrap;font-weight:${isExpiring || isOverdue ? 800 : 400};color:${isOverdue ? "#EF4444" : isExpiring ? "#F59E0B" : "#94A3B8"}">${fmtDate(subEnd)}${isExpiring && !isOverdue ? " ⚠️" : isOverdue ? " 🔴" : ""}</td>
              <td style="padding:.45rem .7rem;text-align:center;color:#94A3B8">${b.included || "—"}</td>
              <td style="padding:.45rem .7rem;text-align:center;font-weight:800;color:#CBD5E1">${b.used || 0}</td>
              <td style="padding:.45rem .7rem;text-align:center;font-weight:800;color:${remColor}">${b.cfg ? b.remaining : "—"}</td>
              <td style="padding:.45rem .7rem;text-align:right;color:#94A3B8">${b.base ? $$(b.base) : "—"}</td>
              <td style="padding:.45rem .7rem;text-align:right;font-weight:${b.overage > 0 ? 800 : 400};color:${b.overage > 0 ? "#F59E0B" : "#475569"}">${b.overage > 0 ? $$(b.overage) : "—"}</td>
              <td style="padding:.45rem .7rem;text-align:right;font-weight:900;color:${isOverdue ? "#EF4444" : "#22C55E"}">${b.total ? $$(b.total) : "—"}</td>
              <td style="padding:.45rem .7rem;text-align:center">${payBadge}</td>
              <td style="padding:.45rem .7rem;text-align:center;white-space:nowrap">
                <button onclick="openAdminPlanModal('${c.email}','${c.plan || ""}','${b.used}')"
                  style="background:#EFF6FF;color:#0052CC;border:1.5px solid #BFDBFE;border-radius:6px;padding:.2rem .45rem;font-size:.7rem;font-weight:800;cursor:pointer">✏️ Plan</button>
                ${
                  isExpiring || isOverdue
                    ? `<button onclick="adminSendBillingReminder('${c.email}','${(c.company || c.name || "").replace(/'/g, "")}')"
                  style="background:#FEF3C7;color:#92400E;border:1.5px solid #FCD34D;border-radius:6px;padding:.2rem .45rem;font-size:.7rem;font-weight:800;cursor:pointer;margin-left:.2rem">📧 Remind</button>`
                    : ""
                }
              </td>
            </tr>`;
              })
              .join("") ||
            `<tr><td colspan="12" style="text-align:center;color:#475569;padding:2rem">No rental companies registered yet.</td></tr>`
          }
        </tbody>
        <tfoot>
          <tr style="background:rgba(34,197,94,.06);border-top:2px solid rgba(34,197,94,.2)">
            <td colspan="7" style="padding:.5rem .7rem;font-weight:800;color:#94A3B8;font-size:.78rem">TOTALS (active plans)</td>
            <td style="padding:.5rem .7rem;text-align:right;font-weight:800;color:#94A3B8">${$$(mrrBase)}</td>
            <td style="padding:.5rem .7rem;text-align:right;font-weight:800;color:#F59E0B">${$$(mrrOverage)}</td>
            <td style="padding:.5rem .7rem;text-align:right;font-weight:900;font-size:.9rem;color:#22C55E">${$$(mrrTotal)}</td>
            <td colspan="2"></td>
          </tr>
        </tfoot>
      </table>
    </div>

    <!-- ═══ EARNED vs REJECTED REVENUE ═══ -->
    <div style="font-size:.78rem;font-weight:800;color:#94A3B8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.7rem">📊 Quote Revenue — Earned vs Rejected by Company</div>
    <div style="overflow-x:auto;margin-bottom:1.6rem">
      <table style="width:100%;border-collapse:collapse;font-size:.78rem">
        <thead>
          <tr style="background:rgba(255,255,255,.04);border-bottom:2px solid rgba(255,255,255,.08)">
            <th style="padding:.5rem .7rem;text-align:left;color:#94A3B8;font-weight:800">Company</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Plan</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Quotes Rec'd</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Responded</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#22C55E;font-weight:800">Won ✅</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#EF4444;font-weight:800">Lost ❌</th>
            <th style="padding:.5rem .7rem;text-align:right;color:#22C55E;font-weight:800">Earned $</th>
            <th style="padding:.5rem .7rem;text-align:right;color:#EF4444;font-weight:800">Rejected $</th>
            <th style="padding:.5rem .7rem;text-align:right;color:#F59E0B;font-weight:800">Pending $</th>
            <th style="padding:.5rem .7rem;text-align:center;color:#94A3B8;font-weight:800">Win Rate</th>
          </tr>
        </thead>
        <tbody>
          ${
            coStatsList.length
              ? coStatsList
                  .map((co) => {
                    const winRate =
                      co.quotesResponded > 0
                        ? Math.round((co.quotesWon / co.quotesResponded) * 100)
                        : 0;
                    const winCol =
                      winRate >= 50
                        ? "#22C55E"
                        : winRate >= 25
                          ? "#F59E0B"
                          : "#EF4444";
                    // Try to find plan for this company
                    const rcMatch = allRcos.find(
                      (r) => r.name === co.name || r.company === co.name,
                    );
                    return `<tr style="border-bottom:1px solid rgba(255,255,255,.05)">
              <td style="padding:.42rem .7rem;font-weight:800;color:#E2E8F0">${co.name}</td>
              <td style="padding:.42rem .7rem;text-align:center">${planBadgeHtml(rcMatch?.plan || null)}</td>
              <td style="padding:.42rem .7rem;text-align:center;color:#CBD5E1;font-weight:700">${co.quotesReceived}</td>
              <td style="padding:.42rem .7rem;text-align:center;color:#94A3B8">${co.quotesResponded}</td>
              <td style="padding:.42rem .7rem;text-align:center;font-weight:800;color:#22C55E">${co.quotesWon}</td>
              <td style="padding:.42rem .7rem;text-align:center;font-weight:800;color:#EF4444">${co.quotesLost}</td>
              <td style="padding:.42rem .7rem;text-align:right;font-weight:900;color:#22C55E">${co.earnedRevenue > 0 ? $$(co.earnedRevenue) : "—"}</td>
              <td style="padding:.42rem .7rem;text-align:right;font-weight:700;color:#EF4444">${co.rejectedRevenue > 0 ? $$(co.rejectedRevenue) : "—"}</td>
              <td style="padding:.42rem .7rem;text-align:right;font-weight:700;color:#F59E0B">${co.pendingRevenue > 0 ? $$(co.pendingRevenue) : "—"}</td>
              <td style="padding:.42rem .7rem;text-align:center">
                <span style="background:${winCol}22;color:${winCol};border-radius:20px;padding:.15rem .6rem;font-size:.8rem;font-weight:900">${winRate}%</span>
              </td>
            </tr>`;
                  })
                  .join("")
              : `<tr><td colspan="10" style="text-align:center;color:#475569;padding:2rem">No quote data yet.</td></tr>`
          }
        </tbody>
      </table>
    </div>

    <!-- ═══ PLAN COMPARISON ═══ -->
    <div style="font-size:.78rem;font-weight:800;color:#94A3B8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.7rem">📦 Plan Performance Comparison</div>
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem;margin-bottom:1.6rem">
      ${[
        ["starter", "Starter", "#64748B", "rgba(100,116,139,.1)", sAvg],
        ["growth", "Growth ⭐", "#0052CC", "rgba(0,82,204,.1)", gAvg],
        ["pro", "Pro", "#7C3AED", "rgba(124,58,237,.1)", pAvg],
      ]
        .map(
          ([key, label, col, bg, avg]) => `
        <div style="background:${bg};border:2px solid ${col}44;border-radius:16px;padding:1.1rem 1.2rem">
          <div style="font-weight:900;color:${col};font-size:.95rem;margin-bottom:.8rem">${label}</div>
          <div style="font-size:.72rem;color:#64748B;margin-bottom:.2rem">Companies on plan</div>
          <div style="font-size:1.3rem;font-weight:900;color:#E2E8F0;margin-bottom:.9rem">${avg.count}</div>
          ${[
            ["Avg enquiries/mo", avg.avgLeads],
            ["Avg win rate", avg.avgWinRate + "%"],
            ["Avg earned/mo", avg.avgEarned > 0 ? $$(avg.avgEarned) : "—"],
            [
              "Avg monthly bill",
              avg.avgTotal > 0 ? $$(avg.avgTotal) : $$(NOYO_PLANS[key].price),
            ],
          ]
            .map(
              ([l, v]) => `
            <div style="display:flex;justify-content:space-between;align-items:center;padding:.3rem 0;border-bottom:1px solid rgba(255,255,255,.06)">
              <span style="font-size:.74rem;color:#94A3B8">${l}</span>
              <span style="font-size:.82rem;font-weight:800;color:#CBD5E1">${v}</span>
            </div>`,
            )
            .join("")}
          <div style="margin-top:.8rem;font-size:.74rem;color:${col};font-weight:700">
            Base: ${$$(NOYO_PLANS[key].price)}/mo · ${NOYO_PLANS[key].included} enquiries
          </div>
          <div style="font-size:.71rem;color:#64748B">Overage: ${$$(NOYO_PLANS[key].extraPrice)}/extra</div>
        </div>`,
        )
        .join("")}
    </div>

    <!-- ═══ BY REGION / DEPOT / STATE ═══ -->
    <div style="font-size:.78rem;font-weight:800;color:#94A3B8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.7rem">🗺️ Quote Activity by Region</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.4rem">
      <!-- By State -->
      <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem">
        <div style="font-size:.75rem;font-weight:800;color:#CBD5E1;margin-bottom:.8rem">📍 By State</div>
        <table style="width:100%;border-collapse:collapse;font-size:.75rem">
          <thead><tr>
            <th style="text-align:left;color:#64748B;font-weight:700;padding:.25rem .35rem">State</th>
            <th style="text-align:center;color:#64748B;font-weight:700;padding:.25rem .35rem">Quotes</th>
            <th style="text-align:center;color:#64748B;font-weight:700;padding:.25rem .35rem">Won</th>
            <th style="text-align:right;color:#64748B;font-weight:700;padding:.25rem .35rem">Revenue</th>
          </tr></thead>
          <tbody>
            ${
              Object.entries(regionStats)
                .sort((a, b) => b[1].quotes - a[1].quotes)
                .slice(0, 12)
                .map(([state, s]) => {
                  const wr =
                    s.quotes > 0 ? Math.round((s.won / s.quotes) * 100) : 0;
                  return `<tr style="border-bottom:1px solid rgba(255,255,255,.04)">
                <td style="padding:.3rem .35rem;font-weight:700;color:#CBD5E1">${state}</td>
                <td style="padding:.3rem .35rem;text-align:center;color:#94A3B8">${s.quotes}</td>
                <td style="padding:.3rem .35rem;text-align:center;color:#22C55E;font-weight:700">${s.won} <span style="font-size:.65rem;color:#64748B">(${wr}%)</span></td>
                <td style="padding:.3rem .35rem;text-align:right;color:#22C55E;font-weight:700">${s.earnedRevenue > 0 ? $$(s.earnedRevenue) : "—"}</td>
              </tr>`;
                })
                .join("") ||
              '<tr><td colspan="4" style="text-align:center;color:#475569;padding:1rem">No regional data yet.</td></tr>'
            }
          </tbody>
        </table>
      </div>
      <!-- By Depot/City -->
      <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem">
        <div style="font-size:.75rem;font-weight:800;color:#CBD5E1;margin-bottom:.8rem">🏙️ By Depot City</div>
        <table style="width:100%;border-collapse:collapse;font-size:.75rem">
          <thead><tr>
            <th style="text-align:left;color:#64748B;font-weight:700;padding:.25rem .35rem">Depot</th>
            <th style="text-align:center;color:#64748B;font-weight:700;padding:.25rem .35rem">Quotes</th>
            <th style="text-align:center;color:#64748B;font-weight:700;padding:.25rem .35rem">Won</th>
            <th style="text-align:right;color:#64748B;font-weight:700;padding:.25rem .35rem">Revenue</th>
          </tr></thead>
          <tbody>
            ${
              Object.entries(depotStats)
                .sort((a, b) => b[1].quotes - a[1].quotes)
                .slice(0, 12)
                .map(([city, s]) => {
                  const wr =
                    s.quotes > 0 ? Math.round((s.won / s.quotes) * 100) : 0;
                  return `<tr style="border-bottom:1px solid rgba(255,255,255,.04)">
                <td style="padding:.3rem .35rem;font-weight:700;color:#CBD5E1">${city}</td>
                <td style="padding:.3rem .35rem;text-align:center;color:#94A3B8">${s.quotes}</td>
                <td style="padding:.3rem .35rem;text-align:center;color:#22C55E;font-weight:700">${s.won} <span style="font-size:.65rem;color:#64748B">(${wr}%)</span></td>
                <td style="padding:.3rem .35rem;text-align:right;color:#22C55E;font-weight:700">${s.earnedRevenue > 0 ? $$(s.earnedRevenue) : "—"}</td>
              </tr>`;
                })
                .join("") ||
              '<tr><td colspan="4" style="text-align:center;color:#475569;padding:1rem">No depot data yet.</td></tr>'
            }
          </tbody>
        </table>
      </div>
    </div>

    <!-- ═══ STRIPE SETUP MODAL PLACEHOLDER ═══ -->
    <div id="billing-stripe-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:9999;display:none;align-items:center;justify-content:center">
      <div style="background:#1E293B;border:1.5px solid rgba(99,102,241,.4);border-radius:18px;padding:1.8rem;max-width:480px;width:90%;position:relative">
        <button onclick="document.getElementById('billing-stripe-modal').style.display='none'"
          style="position:absolute;top:.8rem;right:.8rem;background:none;border:none;color:#94A3B8;font-size:1.3rem;cursor:pointer">×</button>
        <div style="font-weight:900;color:#A5B4FC;font-size:1.1rem;margin-bottom:.4rem">💳 Stripe Setup</div>
        <div style="font-size:.82rem;color:#64748B;margin-bottom:1.2rem">Configure your Stripe integration for automatic billing, payment tracking, and webhook events.</div>
        <div style="display:flex;flex-direction:column;gap:.7rem">
          <div>
            <div style="font-size:.75rem;font-weight:800;color:#94A3B8;margin-bottom:.3rem">Publishable Key</div>
            <input id="stripe-pk-input" class="lp-input" placeholder="pk_live_…" style="font-size:.82rem;background:#0F172A;color:#E2E8F0">
          </div>
          <div>
            <div style="font-size:.75rem;font-weight:800;color:#94A3B8;margin-bottom:.3rem">Webhook Secret</div>
            <input id="stripe-wh-input" class="lp-input" type="password" placeholder="whsec_…" style="font-size:.82rem;background:#0F172A;color:#E2E8F0">
          </div>
          <div style="background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.3);border-radius:10px;padding:.7rem .9rem;font-size:.76rem;color:#FCD34D;line-height:1.6">
            ⚠️ <strong>Cloudflare Worker webhook endpoint:</strong><br>
            Deploy the Noyo billing worker at <code style="background:rgba(0,0,0,.3);padding:.1rem .3rem;border-radius:4px">https://billing.noyo.com.au/stripe-webhook</code><br>
            Point your Stripe webhook to this URL. The worker writes payment events to Firestore <code style="background:rgba(0,0,0,.3);padding:.1rem .3rem;border-radius:4px">billing_events</code> collection automatically.
          </div>
          <button onclick="adminSaveStripeKeys()"
            style="background:#6366F1;color:#fff;border:none;border-radius:10px;padding:.65rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.88rem;cursor:pointer;margin-top:.3rem">
            Save & Test Connection
          </button>
        </div>
      </div>
    </div>
  `;
}

function adminOpenStripeSetup() {
  const modal = document.getElementById("billing-stripe-modal");
  if (modal) modal.style.display = "flex";
}

function adminSaveStripeKeys() {
  const pk = (document.getElementById("stripe-pk-input")?.value || "").trim();
  const wh = (document.getElementById("stripe-wh-input")?.value || "").trim();
  if (!pk || !pk.startsWith("pk_")) {
    showToast(
      "⚠️ Enter a valid Stripe publishable key (starts with pk_)",
      "#EF4444",
    );
    return;
  }
  if (!wh || !wh.startsWith("whsec_")) {
    showToast(
      "⚠️ Enter a valid webhook secret (starts with whsec_)",
      "#EF4444",
    );
    return;
  }
  // In production: save to Firestore config collection (admin-only doc)
  try {
    _fbDb
      .collection("_config")
      .doc("stripe")
      .set({
        publishableKey: pk,
        webhookSecretHint: wh.slice(0, 12) + "…",
        updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
      });
  } catch (e) {}
  document.getElementById("billing-stripe-modal").style.display = "none";
  showToast(
    "✅ Stripe keys saved. Deploy the Cloudflare Worker to activate webhook sync.",
    "#16A34A",
  );
}

function renderAdminLiteAnalytics() {
  const el = document.getElementById("admin-sec-liteanalytics");
  if (!el) return;

  // Pull lite-only searches
  const liteSearches = adminData.searches.filter(
    (s) => s.isLite || s.role === "lite",
  );
  const allSearches = adminData.searches;

  // ── Helper: bar chart HTML ──────────────────────────────────────────────
  function barChart(counts, colorA, colorB) {
    const entries = Object.entries(counts).sort((a, b) => b[1] - a[1]);
    if (!entries.length)
      return '<div style="color:#94A3B8;font-size:.82rem;padding:.5rem">No data yet</div>';
    const max = entries[0][1] || 1;
    return entries
      .map(
        ([k, v]) => `
      <div style="display:flex;align-items:center;gap:.6rem;margin-bottom:.35rem">
        <div style="flex:0 0 130px;font-size:.75rem;font-weight:700;color:#CBD5E1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${k}">${k}</div>
        <div style="flex:1;background:rgba(255,255,255,.06);border-radius:6px;height:18px;overflow:hidden">
          <div style="width:${Math.round((v / max) * 100)}%;height:100%;background:linear-gradient(90deg,${colorA},${colorB});border-radius:6px;display:flex;align-items:center;justify-content:flex-end;padding-right:5px">
            <span style="font-size:.68rem;font-weight:800;color:#fff">${v}</span>
          </div>
        </div>
      </div>`,
      )
      .join("");
  }

  // ── Depot frequency ─────────────────────────────────────────────────────
  const depotCounts = {};
  liteSearches.forEach((s) => {
    const d =
      s.depot && s.depot !== "—"
        ? s.depot
        : s.city && s.city !== "—"
          ? s.city
          : "Unknown";
    depotCounts[d] = (depotCounts[d] || 0) + 1;
  });

  // ── Machine types ────────────────────────────────────────────────────────
  const typeCounts = {};
  liteSearches.forEach((s) => {
    const t = s.machineName || s.machineType || "Unknown";
    typeCounts[t] = (typeCounts[t] || 0) + 1;
  });

  // ── Time-of-day heatmap (0-23 hours) ────────────────────────────────────
  const hourBuckets = Array(24).fill(0);
  liteSearches.forEach((s) => {
    if (s.ts) hourBuckets[new Date(s.ts).getHours()]++;
  });
  const hourMax = Math.max(...hourBuckets, 1);
  const hourHtml = hourBuckets
    .map((v, h) => {
      const pct = Math.round((v / hourMax) * 100);
      const label =
        h === 0
          ? "12am"
          : h === 12
            ? "12pm"
            : h < 12
              ? h + "am"
              : h - 12 + "pm";
      const bg =
        pct === 0
          ? "rgba(14,165,233,.04)"
          : `rgba(14,165,233,${(0.1 + (pct / 100) * 0.85).toFixed(2)})`;
      return `<div style="flex:1;min-width:28px;text-align:center">
      <div style="background:${bg};border-radius:4px;height:${Math.max(6, Math.round(pct * 0.5))}px;margin-bottom:3px;transition:height .3s" title="${label}: ${v} searches"></div>
      <div style="font-size:.58rem;color:#64748B;font-weight:600">${label}</div>
    </div>`;
    })
    .join("");

  // ── Day-of-week ──────────────────────────────────────────────────────────
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const dowBuckets = Array(7).fill(0);
  liteSearches.forEach((s) => {
    if (s.ts) dowBuckets[new Date(s.ts).getDay()]++;
  });
  const dowMax = Math.max(...dowBuckets, 1);
  const dowHtml = dowBuckets
    .map((v, d) => {
      const pct = Math.round((v / dowMax) * 100);
      const bg =
        pct === 0
          ? "rgba(14,165,233,.04)"
          : `rgba(14,165,233,${(0.15 + (pct / 100) * 0.8).toFixed(2)})`;
      return `<div style="flex:1;text-align:center">
      <div style="background:${bg};border-radius:5px;height:${Math.max(8, Math.round(pct * 0.6))}px;margin-bottom:4px" title="${days[d]}: ${v}"></div>
      <div style="font-size:.7rem;color:#94A3B8;font-weight:700">${days[d]}</div>
      <div style="font-size:.65rem;color:#64748B">${v}</div>
    </div>`;
    })
    .join("");

  // ── Per-day trend (last 30 days) ─────────────────────────────────────────
  const perDay = {};
  const now30 = Date.now();
  liteSearches.forEach((s) => {
    if (!s.ts || now30 - s.ts > 30 * 86400000) return;
    const day = new Date(s.ts).toLocaleDateString("en-AU", {
      day: "2-digit",
      month: "short",
    });
    perDay[day] = (perDay[day] || 0) + 1;
  });
  const dayEntries = Object.entries(perDay).slice(-30);
  const dayMax = Math.max(...dayEntries.map((e) => e[1]), 1);
  const dayHtml = dayEntries.length
    ? dayEntries
        .map(
          ([d, v]) => `
    <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.25rem">
      <div style="flex:0 0 60px;font-size:.72rem;color:#94A3B8;font-weight:600">${d}</div>
      <div style="flex:1;background:rgba(255,255,255,.06);border-radius:4px;height:14px;overflow:hidden">
        <div style="width:${Math.round((v / dayMax) * 100)}%;height:100%;background:linear-gradient(90deg,#0EA5E9,#38BDF8);border-radius:4px"></div>
      </div>
      <div style="font-size:.72rem;color:#38BDF8;font-weight:800;flex:0 0 20px;text-align:right">${v}</div>
    </div>`,
        )
        .join("")
    : '<div style="color:#94A3B8;font-size:.82rem">No searches in last 30 days</div>';

  // ── Per-month trend ───────────────────────────────────────────────────────
  const perMonth = {};
  liteSearches.forEach((s) => {
    if (!s.ts) return;
    const mo = new Date(s.ts).toLocaleDateString("en-AU", {
      month: "short",
      year: "numeric",
    });
    perMonth[mo] = (perMonth[mo] || 0) + 1;
  });
  const moEntries = Object.entries(perMonth);
  const moMax = Math.max(...moEntries.map((e) => e[1]), 1);
  const moHtml = moEntries.length
    ? moEntries
        .map(
          ([m, v]) => `
    <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.3rem">
      <div style="flex:0 0 75px;font-size:.75rem;color:#94A3B8;font-weight:600">${m}</div>
      <div style="flex:1;background:rgba(255,255,255,.06);border-radius:4px;height:16px;overflow:hidden">
        <div style="width:${Math.round((v / moMax) * 100)}%;height:100%;background:linear-gradient(90deg,#0369A1,#0EA5E9);border-radius:4px"></div>
      </div>
      <div style="font-size:.75rem;color:#0EA5E9;font-weight:800;flex:0 0 20px;text-align:right">${v}</div>
    </div>`,
        )
        .join("")
    : '<div style="color:#94A3B8;font-size:.82rem">No monthly data yet</div>';

  // ── Registered lite users ─────────────────────────────────────────────────
  const liteUsers = Object.values(customerRegistry).filter(
    (u) => u.role === "lite",
  );
  const liteUserCount = liteUsers.length;
  const liteSearchCount = liteSearches.length;
  const avgPerUser =
    liteUserCount > 0 ? (liteSearchCount / liteUserCount).toFixed(1) : "0";

  // ── Top job types from lite searches ─────────────────────────────────────
  const jobCounts = {};
  liteSearches.forEach((s) => {
    if (s.jobType && s.jobType !== "—")
      jobCounts[s.jobType] = (jobCounts[s.jobType] || 0) + 1;
  });

  // ── Render ────────────────────────────────────────────────────────────────
  el.innerHTML = `
    <div class="admin-section-title" style="color:#38BDF8">🔵 Lite Portal Analytics</div>
    <div style="background:rgba(14,165,233,.06);border:1.5px solid rgba(14,165,233,.2);border-radius:12px;padding:.7rem 1rem;margin-bottom:1.2rem;font-size:.78rem;color:#7DD3FC;line-height:1.6">
      ℹ️ <strong>Lite Portal</strong> users search for machine information only — no quoting, no cart. These analytics track what machines people want to know about, and from which depots, helping identify unmet demand.
    </div>

    <!-- KPI row -->
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:.8rem;margin-bottom:1.4rem">
      ${[
        ["🔵", "Lite Users", liteUserCount, "Registered"],
        ["🔍", "Lite Searches", liteSearchCount, "Total"],
        ["📊", "Avg / User", avgPerUser, "Searches per user"],
        [
          "🏙️",
          "Depots Active",
          Object.keys(depotCounts).length,
          "Unique depots",
        ],
        [
          "⚙️",
          "Machine Types",
          Object.keys(typeCounts).length,
          "Unique types searched",
        ],
      ]
        .map(
          ([icon, label, val, sub]) => `
        <div style="background:linear-gradient(135deg,rgba(14,165,233,.10),rgba(14,165,233,.04));border:1.5px solid rgba(14,165,233,.22);border-radius:14px;padding:.9rem 1rem;text-align:center">
          <div style="font-size:1.5rem">${icon}</div>
          <div style="font-size:1.35rem;font-weight:900;color:#38BDF8">${val}</div>
          <div style="font-size:.75rem;font-weight:800;color:#CBD5E1">${label}</div>
          <div style="font-size:.68rem;color:#64748B">${sub}</div>
        </div>`,
        )
        .join("")}
    </div>

    <!-- Depot + Machine type side by side -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.2rem">
      <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem">
        <div style="font-size:.75rem;font-weight:800;color:#38BDF8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.8rem">🏙️ Depot Search Frequency</div>
        ${barChart(depotCounts, "#0EA5E9", "#38BDF8") || '<div style="color:#94A3B8;font-size:.82rem">No depot data yet</div>'}
      </div>
      <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem">
        <div style="font-size:.75rem;font-weight:800;color:#38BDF8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.8rem">⚙️ Machine Types Searched</div>
        ${barChart(typeCounts, "#0369A1", "#0EA5E9") || '<div style="color:#94A3B8;font-size:.82rem">No type data yet</div>'}
      </div>
    </div>

    <!-- Job type pills -->
    ${
      Object.keys(jobCounts).length
        ? `
    <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem;margin-bottom:1.2rem">
      <div style="font-size:.75rem;font-weight:800;color:#38BDF8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.7rem">🎯 Job Types Searched</div>
      <div>${Object.entries(jobCounts)
        .sort((a, b) => b[1] - a[1])
        .map(
          ([k, v]) =>
            `<span style="background:rgba(14,165,233,.12);color:#38BDF8;border:1px solid rgba(14,165,233,.3);border-radius:20px;padding:.2rem .7rem;font-size:.78rem;font-weight:700;margin:.18rem;display:inline-block">${k} <strong>${v}×</strong></span>`,
        )
        .join("")}</div>
    </div>`
        : ""
    }

    <!-- Time of day heatmap -->
    <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem;margin-bottom:1.2rem">
      <div style="font-size:.75rem;font-weight:800;color:#38BDF8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.9rem">🕐 Time of Day Pattern</div>
      <div style="display:flex;gap:2px;align-items:flex-end;min-height:50px">${hourHtml}</div>
    </div>

    <!-- Day of week + monthly side by side -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.2rem">
      <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem">
        <div style="font-size:.75rem;font-weight:800;color:#38BDF8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.9rem">📅 Day of Week</div>
        <div style="display:flex;gap:4px;align-items:flex-end;min-height:60px">${dowHtml}</div>
      </div>
      <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem">
        <div style="font-size:.75rem;font-weight:800;color:#38BDF8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.7rem">📆 Per Month</div>
        ${moHtml}
      </div>
    </div>

    <!-- Per-day last 30 days -->
    <div style="background:rgba(255,255,255,.03);border:1.5px solid rgba(255,255,255,.08);border-radius:14px;padding:1rem;margin-bottom:1.2rem">
      <div style="font-size:.75rem;font-weight:800;color:#38BDF8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.7rem">📈 Daily Searches — Last 30 Days</div>
      ${dayHtml}
    </div>

    <!-- Recent lite search log -->
    <div style="font-size:.78rem;font-weight:800;color:#38BDF8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:.6rem">📋 Recent Lite Searches</div>
    <div style="overflow-x:auto">
      <table style="width:100%;border-collapse:collapse;font-size:.78rem">
        <thead>
          <tr style="background:rgba(14,165,233,.1)">
            <th style="padding:.45rem .6rem;text-align:left;color:#7DD3FC;font-weight:800;white-space:nowrap">Time</th>
            <th style="padding:.45rem .6rem;text-align:left;color:#7DD3FC;font-weight:800">User</th>
            <th style="padding:.45rem .6rem;text-align:left;color:#7DD3FC;font-weight:800">Depot</th>
            <th style="padding:.45rem .6rem;text-align:left;color:#7DD3FC;font-weight:800">Machine Type</th>
            <th style="padding:.45rem .6rem;text-align:left;color:#7DD3FC;font-weight:800">Job</th>
            <th style="padding:.45rem .6rem;text-align:left;color:#7DD3FC;font-weight:800">Height</th>
          </tr>
        </thead>
        <tbody>
          ${
            liteSearches.length
              ? [...liteSearches]
                  .reverse()
                  .slice(0, 50)
                  .map(
                    (s) => `
            <tr style="border-bottom:1px solid rgba(255,255,255,.05)">
              <td style="padding:.38rem .6rem;color:#64748B;white-space:nowrap;font-size:.72rem">${s.ts ? new Date(s.ts).toLocaleString("en-AU", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }) : "—"}</td>
              <td style="padding:.38rem .6rem;font-weight:700;color:#CBD5E1">${s.user || "—"}<br><span style="font-size:.68rem;color:#475569">${s.email || ""}</span></td>
              <td style="padding:.38rem .6rem;color:#38BDF8;font-weight:700">${s.depot && s.depot !== "—" ? s.depot : s.city || "—"}</td>
              <td style="padding:.38rem .6rem;font-weight:700;color:#E2E8F0">${s.machineName || s.machineType || "—"}</td>
              <td style="padding:.38rem .6rem;color:#94A3B8;font-size:.74rem">${s.jobType || "—"}</td>
              <td style="padding:.38rem .6rem;color:#94A3B8">${s.height || "—"}</td>
            </tr>`,
                  )
                  .join("")
              : '<tr><td colspan="6" style="text-align:center;color:#475569;padding:2rem">No Lite portal searches recorded yet.</td></tr>'
          }
        </tbody>
      </table>
    </div>
  `;
}

// ══════════════════════════════════════════════════════════════════
// ADMIN FOLLOW-UP QUEUE
// ══════════════════════════════════════════════════════════════════

function _getFollowUpJobs() {
  const now = Date.now();
  return (quoteInbox || []).filter(
    (r) =>
      (r.responses || []).length > 0 &&
      !r.acceptedBy &&
      r.customerAcceptExpires &&
      now > r.customerAcceptExpires,
  );
}

function _updateFollowUpBadge() {
  const badge = document.getElementById("admin-followup-badge");
  if (!badge) return;
  const jobs = _getFollowUpJobs();
  // Only show count for uncalled ones
  const calledKey = "noyo_followup_called";
  let called = {};
  try {
    called = JSON.parse(localStorage.getItem(calledKey) || "{}");
  } catch (e) {}
  const uncalled = jobs.filter((r) => !called[r.id]);
  if (uncalled.length > 0) {
    badge.textContent = uncalled.length;
    badge.style.display = "inline";
    const tab = document.getElementById("admin-tab-followup");
    if (tab) tab.style.background = "linear-gradient(135deg,#FEE2E2,#FFF)";
  } else {
    badge.style.display = "none";
    const tab = document.getElementById("admin-tab-followup");
    if (tab) tab.style.background = "linear-gradient(135deg,#F0FDF4,#fff)";
  }
}

function renderAdminFollowUp() {
  const el = document.getElementById("admin-followup-list");
  if (!el) return;

  const calledKey = "noyo_followup_called";
  let called = {};
  try {
    called = JSON.parse(localStorage.getItem(calledKey) || "{}");
  } catch (e) {}

  const jobs = _getFollowUpJobs();

  if (jobs.length === 0) {
    el.innerHTML = `<div style="text-align:center;padding:2rem;color:#94A3B8">
      <div style="font-size:2rem;margin-bottom:.5rem">🎉</div>
      <div style="font-weight:700;margin-bottom:.3rem">No follow-ups needed right now</div>
      <div style="font-size:.8rem">All enquiries with quotes have been decided on, or acceptance windows are still open.</div>
    </div>`;
    _updateFollowUpBadge();
    return;
  }

  // Sort: uncalled first, then by how long ago window closed (most recent first)
  jobs.sort((a, b) => {
    const aCalled = !!called[a.id];
    const bCalled = !!called[b.id];
    if (aCalled !== bCalled) return aCalled ? 1 : -1;
    return (b.customerAcceptExpires || 0) - (a.customerAcceptExpires || 0);
  });

  el.innerHTML = jobs
    .map((r) => {
      const isCalled = !!called[r.id];
      const calledAt = called[r.id]
        ? new Date(called[r.id]).toLocaleString("en-AU", {
            day: "2-digit",
            month: "short",
            hour: "2-digit",
            minute: "2-digit",
          })
        : null;
      const closedMs = Date.now() - (r.customerAcceptExpires || 0);
      const closedHrs = Math.floor(closedMs / 3600000);
      const closedLabel =
        closedHrs < 24
          ? `${closedHrs}h ago`
          : `${Math.floor(closedHrs / 24)}d ago`;
      const rcNames = (r.responses || [])
        .map((p) => p.company)
        .filter(Boolean)
        .join(", ");
      const machineList =
        (r.machines || [])
          .map((m) => `${m.emoji || "🏗️"} ${m.name || m.type || "Machine"}`)
          .join(", ") ||
        r.machineType ||
        "—";
      const respCount = (r.responses || []).length;
      const prices = (r.responses || [])
        .map((p) =>
          parseFloat(
            String(p.grandTotal || p.price || "").replace(/[^0-9.]/g, ""),
          ),
        )
        .filter((n) => !isNaN(n) && n > 0);
      const priceRange =
        prices.length > 1
          ? `A$${Math.min(...prices).toLocaleString(undefined, { minimumFractionDigits: 0 })} – A$${Math.max(...prices).toLocaleString(undefined, { minimumFractionDigits: 0 })}`
          : prices.length === 1
            ? `A$${prices[0].toLocaleString(undefined, { minimumFractionDigits: 0 })}`
            : "No price data";

      return `<div style="background:${isCalled ? "#F8FAFC" : "#fff"};border:1.5px solid ${isCalled ? "#E2E8F0" : "#FCA5A5"};border-radius:12px;padding:.85rem 1rem;margin-bottom:.75rem;opacity:${isCalled ? 0.75 : 1}">
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:.5rem;flex-wrap:wrap">
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;margin-bottom:.4rem">
            <span style="background:${isCalled ? "#F1F5F9" : "#FEE2E2"};color:${isCalled ? "#64748B" : "#991B1B"};font-size:.72rem;font-weight:900;padding:.15rem .55rem;border-radius:20px">${isCalled ? "✅ Called" : "📞 NEEDS CALL"}</span>
            <span style="font-weight:800;color:#1E293B;font-size:.9rem">${r.id}</span>
            <span style="font-size:.75rem;color:#64748B">Window closed ${closedLabel}</span>
          </div>
          <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.3rem .8rem;font-size:.82rem">
            <div><span style="color:#94A3B8;font-weight:700">👤 Customer:</span> <span style="font-weight:700;color:#334155">${r.customer || "—"}</span></div>
            ${r.email ? `<div><span style="color:#94A3B8;font-weight:700">📧 Email:</span> <a href="mailto:${r.email}" style="color:#0052CC;font-weight:700;text-decoration:none">${r.email}</a></div>` : ""}
            ${r.mobile ? `<div><span style="color:#94A3B8;font-weight:700">📱 Mobile:</span> <a href="tel:${r.mobile}" style="color:#0052CC;font-weight:700;text-decoration:none">${r.mobile}</a></div>` : ""}
            <div><span style="color:#94A3B8;font-weight:700">📍 Location:</span> <span style="color:#334155">${r.suburb || r.city || r.cluster || "—"}${r.state ? ", " + r.state : ""}</span></div>
            <div><span style="color:#94A3B8;font-weight:700">🏗️ Machine:</span> <span style="color:#334155">${machineList}</span></div>
            ${r.date ? `<div><span style="color:#94A3B8;font-weight:700">📅 Hire Start:</span> <span style="color:#334155">${r.date}</span></div>` : ""}
            <div><span style="color:#94A3B8;font-weight:700">💬 Quotes received:</span> <span style="font-weight:800;color:#0052CC">${respCount} quote${respCount !== 1 ? "s" : ""}</span> — ${priceRange}</div>
            <div style="grid-column:1/-1"><span style="color:#94A3B8;font-weight:700">🏗️ From:</span> <span style="color:#334155">${rcNames || "—"}</span></div>
          </div>
          ${isCalled && calledAt ? `<div style="margin-top:.5rem;font-size:.75rem;color:#64748B;font-style:italic">✅ Marked as called on ${calledAt}</div>` : ""}
        </div>
        <div style="display:flex;flex-direction:column;gap:.4rem;min-width:130px">
          ${!isCalled ? `<button onclick="adminMarkFollowUpCalled('${r.id}')" style="background:#16A34A;color:#fff;border:none;border-radius:8px;padding:.45rem .85rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.8rem;cursor:pointer;white-space:nowrap">✅ Mark Called</button>` : `<button onclick="adminMarkFollowUpCalled('${r.id}', true)" style="background:#F1F5F9;color:#64748B;border:1px solid #E2E8F0;border-radius:8px;padding:.4rem .8rem;font-family:'Nunito',sans-serif;font-weight:700;font-size:.78rem;cursor:pointer;white-space:nowrap">↩ Mark Uncalled</button>`}
          ${r.email ? `<a href="mailto:${r.email}?subject=Your%20Noyo%20hire%20enquiry%20${encodeURIComponent(r.id)}&body=Hi%20${encodeURIComponent(r.customer || "")},\n\nI'm%20following%20up%20on%20your%20hire%20enquiry%20${encodeURIComponent(r.id)}%20-%20you%20received%20${respCount}%20quote${respCount !== 1 ? "s" : ""}%20and%20we%20wanted%20to%20check%20if%20you%27d%20like%20to%20proceed.\n\nKind%20regards,\nNoyo" style="display:block;text-align:center;background:#EFF6FF;color:#1D4ED8;border:1.5px solid #BFDBFE;border-radius:8px;padding:.38rem .7rem;font-family:'Nunito',sans-serif;font-weight:800;font-size:.78rem;cursor:pointer;text-decoration:none;white-space:nowrap">📧 Email Customer</a>` : ""}
        </div>
      </div>
    </div>`;
    })
    .join("");

  _updateFollowUpBadge();
}

function adminMarkFollowUpCalled(id, undo) {
  const calledKey = "noyo_followup_called";
  let called = {};
  try {
    called = JSON.parse(localStorage.getItem(calledKey) || "{}");
  } catch (e) {}
  if (undo) {
    delete called[id];
  } else {
    called[id] = Date.now();
  }
  try {
    localStorage.setItem(calledKey, JSON.stringify(called));
  } catch (e) {}
  renderAdminFollowUp();
}

function showAdminSection(name, btn) {
  document
    .querySelectorAll(".admin-section")
    .forEach((s) => s.classList.remove("active"));
  document
    .querySelectorAll(".admin-tab")
    .forEach((t) => t.classList.remove("active"));
  const sec = document.getElementById("admin-sec-" + name);
  if (sec) sec.classList.add("active");
  if (btn) btn.classList.add("active");
  // Trigger renders for new sections
  if (name === "quotes") renderAdminQuotes();
  if (name === "customers") renderAdminCustomers();
  if (name === "rentalcos") renderAdminRentalCos();
  if (name === "users") renderAdminUsers();
  if (name === "searches") renderAdminSearches();
  if (name === "activity") renderAdminActivity();
  if (name === "analytics") {
    analyticsSetPreset("30d");
  }
  if (name === "liteanalytics") renderAdminLiteAnalytics();
  if (name === "billing") renderAdminBilling();
  if (name === "billing") _checkBillingReminders();
  if (name === "sponsored") renderAdminSponsored();
  if (name === "addmachine") renderAdminAddMachine();
  if (name === "addmachine") {
    /* panel is static HTML — nothing to render */
  }
  if (name === "usermgmt") loadUserMgmtTable();
  if (name === "investor") renderInvestorDashboard();
  if (name === "followup") renderAdminFollowUp();
  if (name === "management") renderManagementDashboard();
  if (name === "mapintel") renderMapIntelDashboard();
  if (name === "livemap") renderLiveMap();
}

// ══════════════════════════════════════════════════════════════════
// ANALYTICS CHARTS
// ══════════════════════════════════════════════════════════════════
const _chartInstances = {};

function destroyChart(id) {
  if (_chartInstances[id]) {
    try {
      _chartInstances[id].destroy();
    } catch (e) {}
    delete _chartInstances[id];
  }
}

function makeChart(id, cfg) {
  destroyChart(id);
  const canvas = document.getElementById(id);
  if (!canvas) return;
  _chartInstances[id] = new Chart(canvas, cfg);
}

function analyticsApplyCustom() {
  // Mark all preset buttons as inactive, mark custom as active
  [
    "today",
    "yesterday",
    "this_week",
    "last_week",
    "7d",
    "this_month",
    "last_month",
    "30d",
    "90d",
    "this_year",
    "last_year",
    "12m",
    "all",
  ].forEach((p) => {
    const btn = document.getElementById("abtn-" + p);
    if (btn) btn.classList.remove("active");
  });
  const fromEl = document.getElementById("analytics-from");
  const toEl = document.getElementById("analytics-to");
  const lbl = document.getElementById("analytics-range-label");
  if (!fromEl.value || !toEl.value) {
    showToast("Please select both From and To dates", "#F59E0B");
    return;
  }
  if (fromEl.value > toEl.value) {
    showToast("From date must be before To date", "#EF4444");
    return;
  }
  // Calculate days in range
  const days =
    Math.round((new Date(toEl.value) - new Date(fromEl.value)) / 86400000) + 1;
  if (lbl)
    lbl.textContent = days + " day" + (days !== 1 ? "s" : "") + " selected";
  renderAnalytics();
}

function analyticsSetPreset(preset) {
  const now = new Date();
  const today = now.toISOString().slice(0, 10);
  let from = today,
    to = today,
    label = "";

  const _fmt = (d) => d.toISOString().slice(0, 10);

  if (preset === "today") {
    from = to = today;
    label = "Today";
  } else if (preset === "yesterday") {
    const d = new Date(now);
    d.setDate(d.getDate() - 1);
    from = to = _fmt(d);
    label = "Yesterday";
  } else if (preset === "this_week") {
    // Monday → today (ISO week Mon-Sun)
    const d = new Date(now);
    const day = d.getDay(); // 0=Sun
    d.setDate(d.getDate() - (day === 0 ? 6 : day - 1));
    from = _fmt(d);
    to = today;
    label = "This Week";
  } else if (preset === "last_week") {
    const d = new Date(now);
    const day = d.getDay();
    const thisMonday = new Date(d);
    thisMonday.setDate(d.getDate() - (day === 0 ? 6 : day - 1));
    const lastMonday = new Date(thisMonday);
    lastMonday.setDate(thisMonday.getDate() - 7);
    const lastSunday = new Date(thisMonday);
    lastSunday.setDate(thisMonday.getDate() - 1);
    from = _fmt(lastMonday);
    to = _fmt(lastSunday);
    label = "Last Week";
  } else if (preset === "7d") {
    const d = new Date(now);
    d.setDate(d.getDate() - 6);
    from = _fmt(d);
    to = today;
    label = "Last 7 Days";
  } else if (preset === "this_month") {
    const d = new Date(now.getFullYear(), now.getMonth(), 1);
    from = _fmt(d);
    to = today;
    label =
      "This Month (" + now.toLocaleString("en-AU", { month: "long" }) + ")";
  } else if (preset === "last_month") {
    const first = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const last = new Date(now.getFullYear(), now.getMonth(), 0);
    from = _fmt(first);
    to = _fmt(last);
    label =
      "Last Month (" + first.toLocaleString("en-AU", { month: "long" }) + ")";
  } else if (preset === "30d") {
    const d = new Date(now);
    d.setDate(d.getDate() - 29);
    from = _fmt(d);
    to = today;
    label = "Last 30 Days";
  } else if (preset === "90d") {
    const d = new Date(now);
    d.setDate(d.getDate() - 89);
    from = _fmt(d);
    to = today;
    label = "Last 90 Days";
  } else if (preset === "this_year") {
    from = now.getFullYear() + "-01-01";
    to = today;
    label = "This Year (" + now.getFullYear() + ")";
  } else if (preset === "last_year") {
    const yr = now.getFullYear() - 1;
    from = yr + "-01-01";
    to = yr + "-12-31";
    label = "Last Year (" + yr + ")";
  } else if (preset === "12m") {
    const d = new Date(now);
    d.setFullYear(d.getFullYear() - 1);
    from = _fmt(d);
    to = today;
    label = "Last 12 Months";
  } else if (preset === "all") {
    from = "2024-01-01";
    to = today;
    label = "All Time";
  } else if (preset === "custom") {
    // Don't change dates — just refresh active state
    const allBtns = [
      "today",
      "yesterday",
      "this_week",
      "last_week",
      "7d",
      "this_month",
      "last_month",
      "30d",
      "90d",
      "this_year",
      "last_year",
      "12m",
      "all",
    ];
    allBtns.forEach((p) => {
      const b = document.getElementById("abtn-" + p);
      if (b) b.classList.remove("active");
    });
    return; // custom apply button handles the render
  }

  const fromEl = document.getElementById("analytics-from");
  const toEl = document.getElementById("analytics-to");
  const lbl = document.getElementById("analytics-range-label");
  if (fromEl) fromEl.value = from;
  if (toEl) toEl.value = to;
  if (lbl) lbl.textContent = label;

  // Update active button
  const allPresets = [
    "today",
    "yesterday",
    "this_week",
    "last_week",
    "7d",
    "this_month",
    "last_month",
    "30d",
    "90d",
    "this_year",
    "last_year",
    "12m",
    "all",
  ];
  allPresets.forEach((p) => {
    const btn = document.getElementById("abtn-" + p);
    if (btn) btn.classList.toggle("active", p === preset);
  });
  renderAnalytics();
}

async function renderAnalytics() {
  if (typeof Chart === "undefined") {
    setTimeout(renderAnalytics, 300);
    return;
  }

  // ── Date range ─────────────────────────────────────────────────────────
  const today = new Date().toISOString().slice(0, 10);
  const fromEl = document.getElementById("analytics-from");
  const toEl = document.getElementById("analytics-to");
  if (!fromEl.value) {
    analyticsSetPreset("30d");
    return;
  }
  const fromDate = fromEl.value || today;
  const toDate = toEl.value || today;

  // Generate date list
  const dateList = [];
  const cur = new Date(fromDate);
  const end = new Date(toDate);
  while (cur <= end) {
    dateList.push(cur.toISOString().slice(0, 10));
    cur.setDate(cur.getDate() + 1);
  }

  // ── Load analytics_daily from Firestore ────────────────────────────────
  let dailyDocs = [];
  try {
    const snap = await _fbDb
      .collection("analytics_daily")
      .where(firebase.firestore.FieldPath.documentId(), ">=", fromDate)
      .where(firebase.firestore.FieldPath.documentId(), "<=", toDate)
      .get();
    dailyDocs = snap.docs.map((d) => ({ date: d.id, ...d.data() }));
  } catch (e) {
    console.warn("Analytics load failed:", e.message);
  }

  // ── Load recent search records ─────────────────────────────────────────
  let searchRecs = [];
  try {
    const cutoffMs = new Date(fromDate).getTime();
    const snap2 = await _fbDb
      .collection("admin_analytics")
      .doc("searches")
      .collection("records")
      .where("ts", ">=", cutoffMs)
      .orderBy("ts", "desc")
      .limit(200)
      .get();
    searchRecs = snap2.docs.map((d) => ({ id: d.id, ...d.data() }));
  } catch (e) {}

  // ── Aggregate daily data ───────────────────────────────────────────────
  let totalSearches = 0,
    totalCartAdds = 0;
  const categoryAgg = {}; // catKey → count
  const machineAgg = {}; // machId → { views, cartAdds, name }
  const cityAgg = {}; // city → count
  const dailySearch = {}; // date → searches
  const dailyCart = {}; // date → cartAdds
  const dailyQuote = {}; // date → quotes

  dateList.forEach((d) => {
    dailySearch[d] = 0;
    dailyCart[d] = 0;
    dailyQuote[d] = 0;
  });

  dailyDocs.forEach((doc) => {
    const d = doc.date;
    totalSearches += parseInt(doc.searches) || 0;
    totalCartAdds += parseInt(doc.cartAdds) || 0;
    dailySearch[d] = (dailySearch[d] || 0) + (parseInt(doc.searches) || 0);
    dailyCart[d] = (dailyCart[d] || 0) + (parseInt(doc.cartAdds) || 0);

    // Categories
    if (doc.categories)
      Object.entries(doc.categories).forEach(([k, v]) => {
        categoryAgg[k] = (categoryAgg[k] || 0) + (parseInt(v) || 0);
      });

    // Machines
    if (doc.machines)
      Object.entries(doc.machines).forEach(([rawId, mData]) => {
        const id = rawId.replace(/_/g, "-"); // un-sanitize
        if (!machineAgg[id]) {
          const m = ALL_MACHINES.find((x) => x.id === id);
          machineAgg[id] = {
            views: 0,
            cartAdds: 0,
            name: m ? m.shortName || m.name : id,
            brand: m ? m.brand : "",
          };
        }
        machineAgg[id].views += parseInt(mData?.views) || 0;
        machineAgg[id].cartAdds += parseInt(mData?.cartAdds) || 0;
      });

    // Cities
    if (doc.cities)
      Object.entries(doc.cities).forEach(([k, v]) => {
        const city = k.replace(/_/g, " ");
        cityAgg[city] = (cityAgg[city] || 0) + (parseInt(v) || 0);
      });
  });

  // ── Quote data from quoteInbox (in-memory) ─────────────────────────────
  const cutoffMs = new Date(fromDate).getTime();
  const toMs = new Date(toDate).getTime() + 86400000;
  const recentQuotes = (quoteInbox || []).filter(
    (q) => q.ts && q.ts >= cutoffMs && q.ts <= toMs,
  );
  recentQuotes.forEach((q) => {
    const d = new Date(q.ts).toISOString().slice(0, 10);
    dailyQuote[d] = (dailyQuote[d] || 0) + 1;
    // City from quote
    const city = q.state || q.city || q.suburb;
    if (city) cityAgg[city] = (cityAgg[city] || 0) + 0.5;
  });
  const totalQuotes = recentQuotes.length;
  const totalAccepted = recentQuotes.filter((q) => q.acceptedBy).length;
  const totalResponded = recentQuotes.filter(
    (q) => (q.responses || []).length > 0,
  ).length;

  // ── KPI tiles ──────────────────────────────────────────────────────────
  const convRate =
    totalSearches > 0
      ? ((totalCartAdds / totalSearches) * 100).toFixed(1)
      : "0.0";
  const quoteRate =
    totalCartAdds > 0
      ? ((totalQuotes / totalCartAdds) * 100).toFixed(1)
      : "0.0";
  const kpis = [
    {
      icon: "🔍",
      val: totalSearches.toLocaleString(),
      label: "Searches",
      color: "#0052CC",
      bg: "#EFF6FF",
    },
    {
      icon: "🛒",
      val: totalCartAdds.toLocaleString(),
      label: "Cart Adds",
      color: "#7C3AED",
      bg: "#F5F3FF",
    },
    {
      icon: "📨",
      val: totalQuotes.toLocaleString(),
      label: "Quotes Sent",
      color: "#0891B2",
      bg: "#ECFEFF",
    },
    {
      icon: "✅",
      val: totalAccepted.toLocaleString(),
      label: "Hires Accepted",
      color: "#16A34A",
      bg: "#F0FDF4",
    },
    {
      icon: "📊",
      val: convRate + "%",
      label: "Search→Cart Rate",
      color: "#D97706",
      bg: "#FFFBEB",
    },
    {
      icon: "💬",
      val: quoteRate + "%",
      label: "Cart→Quote Rate",
      color: "#DC2626",
      bg: "#FEF2F2",
    },
    {
      icon: "🧑",
      val: Object.keys(customerRegistry || {}).filter((e) => {
        const u = customerRegistry[e];
        return u.lastSeen && u.lastSeen >= cutoffMs;
      }).length,
      label: "Active Users",
      color: "#0F172A",
      bg: "#F8FAFC",
    },
    {
      icon: "⭐",
      val: _sponsoredAds.filter((a) => a.active && !_spnIsExpired(a)).length,
      label: "Live Brand Ads",
      color: "#92400E",
      bg: "#FFFBEB",
    },
  ];
  const kpiRow = document.getElementById("analytics-kpi-row");
  if (kpiRow)
    kpiRow.innerHTML = kpis
      .map(
        (k) => `
    <div style="background:${k.bg};border:1.5px solid ${k.color}22;border-radius:12px;padding:.7rem .8rem;text-align:center">
      <div style="font-size:1.3rem">${k.icon}</div>
      <div style="font-size:1.35rem;font-weight:900;color:${k.color};line-height:1.2">${k.val}</div>
      <div style="font-size:.7rem;font-weight:700;color:#64748B;margin-top:.1rem">${k.label}</div>
    </div>`,
      )
      .join("");

  // ── Conversion funnel ──────────────────────────────────────────────────
  const funnelEl = document.getElementById("analytics-funnel");
  if (funnelEl && totalSearches > 0) {
    const steps = [
      { label: "🔍 Searches", val: totalSearches, color: "#0052CC" },
      {
        label: "🛒 Cart Adds",
        val: totalCartAdds,
        pct:
          totalSearches > 0
            ? ((totalCartAdds / totalSearches) * 100).toFixed(0)
            : 0,
        color: "#7C3AED",
      },
      {
        label: "📨 Quotes Sent",
        val: totalQuotes,
        pct:
          totalCartAdds > 0
            ? ((totalQuotes / totalCartAdds) * 100).toFixed(0)
            : 0,
        color: "#0891B2",
      },
      {
        label: "✅ Accepted",
        val: totalAccepted,
        pct:
          totalQuotes > 0
            ? ((totalAccepted / totalQuotes) * 100).toFixed(0)
            : 0,
        color: "#16A34A",
      },
    ];
    const maxVal = totalSearches || 1;
    funnelEl.innerHTML = `
      <div style="background:#fff;border:1.5px solid #E2E8F0;border-radius:14px;padding:1rem 1.2rem;margin-bottom:1rem">
        <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.8rem">🎯 Conversion Funnel</div>
        <div style="display:flex;flex-direction:column;gap:.45rem">
          ${steps
            .map(
              (s, i) => `
          <div>
            <div style="display:flex;justify-content:space-between;font-size:.77rem;font-weight:700;margin-bottom:.2rem">
              <span style="color:#334155">${s.label}</span>
              <span style="color:${s.color};font-weight:900">${s.val.toLocaleString()}${s.pct !== undefined ? ` <span style="color:#94A3B8;font-weight:600">(${s.pct}% of prev)</span>` : ""}</span>
            </div>
            <div style="background:#F1F5F9;border-radius:99px;height:10px;overflow:hidden">
              <div style="background:${s.color};width:${Math.round((s.val / maxVal) * 100)}%;height:100%;border-radius:99px;transition:width .4s"></div>
            </div>
          </div>`,
            )
            .join("")}
        </div>
      </div>`;
  }

  // ── Chart helpers ─────────────────────────────────────────────────────
  const gridColor = "rgba(0,0,0,.05)";
  const tickColor = "#94A3B8";
  const chartOpts = (extra = {}) => ({
    responsive: true,
    maintainAspectRatio: false,
    plugins: { legend: { display: false }, ...extra.plugins },
    scales: {
      x: {
        ticks: { color: tickColor, font: { size: 10 }, maxTicksLimit: 10 },
        grid: { color: gridColor },
      },
      y: {
        ticks: { color: tickColor, font: { size: 10 }, precision: 0 },
        grid: { color: gridColor },
        beginAtZero: true,
      },
      ...extra.scales,
    },
    ...extra,
  });

  // Determine label density
  const useDays = dateList.length <= 90;
  const step = Math.ceil(dateList.length / 20);
  const chartLabels = dateList.map((d, i) => {
    if (i % step !== 0) return "";
    const dt = new Date(d);
    return useDays
      ? dt.toLocaleDateString("en-AU", { day: "numeric", month: "short" })
      : dt.toLocaleDateString("en-AU", { month: "short", year: "2-digit" });
  });

  // ── 1. Activity over time ───────────────────────────────────────────────
  makeChart("chart-activity-time", {
    type: "line",
    data: {
      labels: chartLabels,
      datasets: [
        {
          label: "Searches",
          data: dateList.map((d) => dailySearch[d] || 0),
          borderColor: "#0052CC",
          backgroundColor: "rgba(0,82,204,.08)",
          fill: true,
          tension: 0.35,
          pointRadius: 1,
        },
        {
          label: "Cart Adds",
          data: dateList.map((d) => dailyCart[d] || 0),
          borderColor: "#7C3AED",
          backgroundColor: "rgba(124,58,237,.08)",
          fill: true,
          tension: 0.35,
          pointRadius: 1,
        },
        {
          label: "Quotes",
          data: dateList.map((d) => dailyQuote[d] || 0),
          borderColor: "#16A34A",
          backgroundColor: "rgba(22,163,74,.08)",
          fill: true,
          tension: 0.35,
          pointRadius: 1,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          display: true,
          position: "top",
          labels: { font: { size: 11 }, boxWidth: 20, color: "#334155" },
        },
      },
      scales: {
        x: {
          ticks: { color: tickColor, font: { size: 10 }, maxTicksLimit: 12 },
          grid: { color: gridColor },
        },
        y: {
          ticks: { color: tickColor, font: { size: 10 }, precision: 0 },
          grid: { color: gridColor },
          beginAtZero: true,
        },
      },
    },
  });

  // ── 2. Top categories ──────────────────────────────────────────────────
  const catLabels = {
    telehandler: "Telehandlers",
    rotating: "Rotating Tele",
    boom: "Boom Lifts",
    scissor: "Scissor Lifts",
    forklift: "Forklifts",
    material: "Material Lifts",
    pushAround: "Push-Around",
    palletJack: "Pallet Jacks",
    em_excavator: "Excavators",
    em_bobcat: "Bobcats",
    em_dozer: "Dozers",
    em_compactor: "Compactors",
    em_grader: "Graders",
    em_dumper: "ADTs",
    loader: "Wheel Loaders",
    em_water_cart: "Water Carts",
    rigid_dump_truck: "Mining Trucks",
  };
  // Also count from quoteInbox machines
  const catFromQuotes = {};
  recentQuotes.forEach((q) =>
    (q.machines || []).forEach((m) => {
      const t = m.type || m.machineType || "";
      if (t) catFromQuotes[t] = (catFromQuotes[t] || 0) + 1;
    }),
  );
  const combinedCat = { ...categoryAgg };
  Object.entries(catFromQuotes).forEach(([k, v]) => {
    combinedCat[k] = (combinedCat[k] || 0) + v;
  });
  const catSorted = Object.entries(combinedCat)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 12);
  const catColors = [
    "#0052CC",
    "#7C3AED",
    "#0891B2",
    "#16A34A",
    "#D97706",
    "#DC2626",
    "#0EA5E9",
    "#8B5CF6",
    "#10B981",
    "#F59E0B",
    "#6366F1",
    "#EC4899",
  ];
  makeChart("chart-categories", {
    type: "bar",
    data: {
      labels: catSorted.map((c) => catLabels[c[0]] || c[0]),
      datasets: [
        {
          data: catSorted.map((c) => c[1]),
          backgroundColor: catColors,
          borderRadius: 5,
        },
      ],
    },
    options: {
      indexAxis: "y",
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: {
        x: {
          ticks: { color: tickColor, font: { size: 10 }, precision: 0 },
          grid: { color: gridColor },
          beginAtZero: true,
        },
        y: {
          ticks: { color: tickColor, font: { size: 10 } },
          grid: { display: false },
        },
      },
    },
  });

  // ── 3. Geographic ─────────────────────────────────────────────────────
  const geoSorted = Object.entries(cityAgg)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10);
  makeChart("chart-geo", {
    type: "doughnut",
    data: {
      labels: geoSorted.map((g) => g[0]),
      datasets: [
        {
          data: geoSorted.map((g) => Math.round(g[1])),
          backgroundColor: catColors,
          borderWidth: 2,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: "right",
          labels: { font: { size: 10 }, color: "#334155", boxWidth: 12 },
        },
      },
    },
  });

  // ── 4. Quote outcomes ─────────────────────────────────────────────────
  const pending = recentQuotes.filter(
    (q) => (q.responses || []).length > 0 && !q.acceptedBy,
  ).length;
  const declined = recentQuotes.filter(
    (q) => !q.acceptedBy && (q.responses || []).some((r) => r.rejected),
  ).length;
  const noResp = recentQuotes.filter((q) => !(q.responses || []).length).length;
  makeChart("chart-conversion", {
    type: "doughnut",
    data: {
      labels: ["Accepted", "Pending", "Declined", "No Response"],
      datasets: [
        {
          data: [totalAccepted, pending, declined, noResp],
          backgroundColor: ["#16A34A", "#D97706", "#EF4444", "#94A3B8"],
          borderWidth: 2,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: "right",
          labels: { font: { size: 10 }, color: "#334155", boxWidth: 12 },
        },
      },
    },
  });

  // ── 5. Hire duration ──────────────────────────────────────────────────
  const durCount = {
    Daily: 0,
    Weekly: 0,
    "2 Weeks": 0,
    Monthly: 0,
    "3 Months": 0,
    "6 Months": 0,
    "12+ Months": 0,
    Other: 0,
  };
  recentQuotes.forEach((q) => {
    const d = (q.duration || q.hireDuration || "").toLowerCase();
    if (d.includes("half") || d === "1d" || d.includes("4hr"))
      durCount["Daily"]++;
    else if (d.includes("1 day") || d === "daily" || d === "1-day")
      durCount["Daily"]++;
    else if (d.includes("1 week") || d === "1w" || d === "1-week")
      durCount["Weekly"]++;
    else if (d.includes("2 week") || d === "2w" || d === "2-weeks")
      durCount["2 Weeks"]++;
    else if (d.includes("month") || d === "1m" || d === "1-month")
      durCount["Monthly"]++;
    else if (d.includes("3m") || d.includes("3 month")) durCount["3 Months"]++;
    else if (d.includes("6m") || d.includes("6 month")) durCount["6 Months"]++;
    else if (d.includes("12m") || d.includes("year") || d.includes("12 month"))
      durCount["12+ Months"]++;
    else durCount["Other"]++;
  });
  const durPairs = Object.entries(durCount).filter((p) => p[1] > 0);
  makeChart("chart-hire-duration", {
    type: "pie",
    data: {
      labels: durPairs.map((p) => p[0]),
      datasets: [
        {
          data: durPairs.map((p) => p[1]),
          backgroundColor: catColors,
          borderWidth: 2,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: "right",
          labels: { font: { size: 10 }, color: "#334155", boxWidth: 12 },
        },
      },
    },
  });

  // ── 6. Rental company response activity ──────────────────────────────
  const rcActivity = {};
  (quoteInbox || []).forEach((q) => {
    (q.responses || []).forEach((r) => {
      if (!r.company) return;
      if (!rcActivity[r.company])
        rcActivity[r.company] = { responses: 0, accepted: 0 };
      rcActivity[r.company].responses++;
      if (q.acceptedBy === r.company) rcActivity[r.company].accepted++;
    });
  });
  const rcSorted = Object.entries(rcActivity)
    .sort((a, b) => b[1].responses - a[1].responses)
    .slice(0, 10);
  makeChart("chart-rental-activity", {
    type: "bar",
    data: {
      labels: rcSorted.map((r) => r[0]),
      datasets: [
        {
          label: "Quotes Sent",
          data: rcSorted.map((r) => r[1].responses),
          backgroundColor: "rgba(8,145,178,.7)",
          borderRadius: 4,
        },
        {
          label: "Accepted",
          data: rcSorted.map((r) => r[1].accepted),
          backgroundColor: "rgba(22,163,74,.8)",
          borderRadius: 4,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          labels: { font: { size: 10 }, color: "#334155", boxWidth: 12 },
        },
      },
      scales: {
        x: {
          ticks: { color: tickColor, font: { size: 10 }, maxRotation: 30 },
          grid: { color: gridColor },
        },
        y: {
          ticks: { color: tickColor, font: { size: 10 }, precision: 0 },
          grid: { color: gridColor },
          beginAtZero: true,
        },
      },
    },
  });

  // ── 7. Top machines searched ──────────────────────────────────────────
  const topSearched = Object.entries(machineAgg)
    .sort((a, b) => b[1].views - a[1].views)
    .slice(0, 10);
  const topCarted = Object.entries(machineAgg)
    .sort((a, b) => b[1].cartAdds - a[1].cartAdds)
    .filter((m) => m[1].cartAdds > 0)
    .slice(0, 10);

  const _machTable = (title, icon, rows, valKey, valLabel) => `
    <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.7rem">${icon} ${title}</div>
    ${
      rows.length === 0
        ? `<div style="text-align:center;color:#94A3B8;font-size:.82rem;padding:1.5rem">No data yet for this period</div>`
        : `<table style="width:100%;border-collapse:collapse">
          <thead><tr style="background:#F8FAFC">
            <th style="padding:.3rem .5rem;font-size:.72rem;font-weight:700;color:#64748B;text-align:left">#</th>
            <th style="padding:.3rem .5rem;font-size:.72rem;font-weight:700;color:#64748B;text-align:left">Machine</th>
            <th style="padding:.3rem .5rem;font-size:.72rem;font-weight:700;color:#64748B;text-align:right">${valLabel}</th>
          </tr></thead>
          <tbody>
          ${rows
            .map(
              ([id, m], i) => `
            <tr style="border-top:1px solid #F1F5F9">
              <td style="padding:.3rem .5rem;font-size:.75rem;color:#94A3B8;font-weight:700">${i + 1}</td>
              <td style="padding:.3rem .5rem">
                <div style="font-size:.78rem;font-weight:700;color:#0F172A">${m.name || id}</div>
                <div style="font-size:.7rem;color:#64748B">${m.brand || ""}</div>
              </td>
              <td style="padding:.3rem .5rem;text-align:right;font-size:.85rem;font-weight:900;color:#0052CC">${(m[valKey] || 0).toLocaleString()}</td>
            </tr>`,
            )
            .join("")}
          </tbody>
        </table>`
    }`;

  const tsEl = document.getElementById("analytics-top-searched");
  if (tsEl)
    tsEl.innerHTML = _machTable(
      "Top Machines Searched / Shown",
      "🔍",
      topSearched,
      "views",
      "Views",
    );
  const tcEl = document.getElementById("analytics-top-carted");
  if (tcEl)
    tcEl.innerHTML = _machTable(
      "Top Machines Added to Cart",
      "🛒",
      topCarted,
      "cartAdds",
      "Cart Adds",
    );

  // ── 8. Recent search log ───────────────────────────────────────────────
  const rEl = document.getElementById("analytics-recent-searches");
  if (rEl) {
    const recentSearches = searchRecs.slice(0, 20);
    rEl.innerHTML = `
      <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.7rem">🕐 Recent Search Activity</div>
      ${
        recentSearches.length === 0
          ? `<div style="text-align:center;color:#94A3B8;font-size:.82rem;padding:1rem">No recent searches in this period</div>`
          : `<div style="overflow-x:auto">
            <table style="width:100%;border-collapse:collapse;min-width:500px">
              <thead><tr style="background:#F8FAFC">
                <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#64748B;text-align:left">Time</th>
                <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#64748B;text-align:left">Category</th>
                <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#64748B;text-align:left">User</th>
                <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#64748B;text-align:left">Location</th>
                <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#64748B;text-align:center">Cart</th>
                <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#DC2626;text-align:center">No Results</th>
              </tr></thead>
              <tbody>
              ${recentSearches
                .map((s) => {
                  const dt = new Date(s.ts);
                  const timeStr =
                    dt.toLocaleDateString("en-AU", {
                      day: "2-digit",
                      month: "short",
                    }) +
                    " " +
                    dt.toLocaleTimeString("en-AU", {
                      hour: "2-digit",
                      minute: "2-digit",
                    });
                  return `<tr style="border-top:1px solid #F1F5F9">
                  <td style="padding:.3rem .6rem;font-size:.75rem;color:#64748B;white-space:nowrap">${timeStr}</td>
                  <td style="padding:.3rem .6rem;font-size:.78rem;font-weight:700;color:#0052CC">${s.machineName || s.jobType || "—"}</td>
                  <td style="padding:.3rem .6rem;font-size:.75rem;color:#334155">${s.role === "customer" || !s.role ? "Customer" : s.user || "—"}</td>
                  <td style="padding:.3rem .6rem;font-size:.75rem;color:#64748B">${s.city && s.city !== "—" ? "📍 " + s.city : "—"}</td>
                  <td style="padding:.3rem .6rem;text-align:center">${s.cartAdded ? "🛒" : ""}</td>
                  <td style="padding:.3rem .6rem;text-align:center">${s.zeroResults ? '<span style="color:#DC2626;font-weight:800">✕</span>' : ""}</td>
                </tr>`;
                })
                .join("")}
              </tbody>
            </table>
          </div>`
      }`;
  }

  // ── 9. Zero results tracker ───────────────────────────────────────────
  const zrEl = document.getElementById("analytics-zero-results");
  if (zrEl) {
    const zeroHits = searchRecs.filter((s) => s.zeroResults);
    const zrByCat = {};
    zeroHits.forEach((s) => {
      const t = s.machineName || s.jobType || "Unknown";
      zrByCat[t] = (zrByCat[t] || 0) + 1;
    });
    const zrSorted = Object.entries(zrByCat).sort((a, b) => b[1] - a[1]);
    zrEl.innerHTML = `
      <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.7rem">
        <div style="font-weight:800;font-size:.88rem;color:#991B1B">⚠️ Zero-Result Searches — ${zeroHits.length} dead ends in period</div>
        <span style="font-size:.72rem;color:#94A3B8">(searches that returned no machines — fix these first)</span>
      </div>
      ${
        zrSorted.length === 0
          ? `<div style="text-align:center;color:#16A34A;font-size:.82rem;padding:.8rem">✅ No zero-result searches in this period</div>`
          : `<div style="display:flex;flex-wrap:wrap;gap:.4rem">
            ${zrSorted
              .slice(0, 12)
              .map(
                ([cat, count]) => `
              <div style="background:#FEF2F2;border:1.5px solid #FCA5A5;border-radius:8px;padding:.3rem .65rem;font-size:.78rem;font-weight:700;color:#991B1B">
                ${cat} <span style="background:#DC2626;color:#fff;border-radius:20px;padding:.05rem .4rem;font-size:.7rem;margin-left:.3rem">${count}</span>
              </div>`,
              )
              .join("")}
           </div>`
      }`;
  }

  // ── 10. Brand Partner Impression Report ───────────────────────────────
  const brEl = document.getElementById("analytics-brand-report");
  if (brEl) {
    // Aggregate impressions from sponsored ads — use their dailyStats field
    const brandRows = (_sponsoredAds || [])
      .map((ad) => {
        let imprInRange = 0,
          clicksInRange = 0;
        if (ad.dailyStats) {
          Object.entries(ad.dailyStats).forEach(([day, stats]) => {
            if (day >= fromDate && day <= toDate) {
              imprInRange += parseInt(stats.impressions || 0);
              clicksInRange += parseInt(stats.clicks || 0);
            }
          });
        }
        const totalImpr = parseInt(ad.impressions) || 0;
        const totalClicks = parseInt(ad.clicks) || 0;
        const ctrRange =
          imprInRange > 0
            ? ((clicksInRange / imprInRange) * 100).toFixed(1) + "%"
            : "—";
        const ctrAll =
          totalImpr > 0
            ? ((totalClicks / totalImpr) * 100).toFixed(1) + "%"
            : "—";
        const isActive = ad.active && !_spnIsExpired(ad);
        return {
          ad,
          imprInRange,
          clicksInRange,
          ctrRange,
          totalImpr,
          totalClicks,
          ctrAll,
          isActive,
        };
      })
      .sort((a, b) => b.imprInRange - a.imprInRange);

    if (brandRows.length === 0) {
      brEl.innerHTML = `<div style="text-align:center;color:#92400E;font-size:.82rem;padding:1rem">No brand partner ads configured yet. Create one in the Brand Partner (Sponsored) tab.</div>`;
    } else {
      brEl.innerHTML = `
        <div style="overflow-x:auto">
          <table style="width:100%;border-collapse:collapse;min-width:600px">
            <thead>
              <tr style="background:rgba(180,83,9,.1)">
                <th style="padding:.4rem .7rem;font-size:.72rem;font-weight:800;color:#92400E;text-align:left">Brand / Ad</th>
                <th style="padding:.4rem .7rem;font-size:.72rem;font-weight:800;color:#92400E;text-align:left">Category</th>
                <th style="padding:.4rem .7rem;font-size:.72rem;font-weight:800;color:#92400E;text-align:center">Status</th>
                <th style="padding:.4rem .7rem;font-size:.72rem;font-weight:800;color:#0052CC;text-align:right">Impressions<br><span style="color:#94A3B8;font-weight:600">(this period)</span></th>
                <th style="padding:.4rem .7rem;font-size:.72rem;font-weight:800;color:#0052CC;text-align:right">Clicks<br><span style="color:#94A3B8;font-weight:600">(this period)</span></th>
                <th style="padding:.4rem .7rem;font-size:.72rem;font-weight:800;color:#0052CC;text-align:right">CTR<br><span style="color:#94A3B8;font-weight:600">(this period)</span></th>
                <th style="padding:.4rem .7rem;font-size:.72rem;font-weight:800;color:#64748B;text-align:right">Total Impr<br><span style="font-weight:600">(all time)</span></th>
                <th style="padding:.4rem .7rem;font-size:.72rem;font-weight:800;color:#64748B;text-align:right">Total CTR<br><span style="font-weight:600">(all time)</span></th>
              </tr>
            </thead>
            <tbody>
            ${brandRows
              .map(
                (row) => `
              <tr style="border-top:1px solid #FDE68A">
                <td style="padding:.4rem .7rem">
                  <div style="font-weight:800;font-size:.82rem;color:#1E293B">${row.ad.brand || "—"}</div>
                  <div style="font-size:.7rem;color:#64748B">${row.ad.id || ""}</div>
                </td>
                <td style="padding:.4rem .7rem;font-size:.78rem;color:#334155">${row.ad.category || "All"}</td>
                <td style="padding:.4rem .7rem;text-align:center">
                  <span style="background:${row.isActive ? "#DCFCE7" : "#F1F5F9"};color:${row.isActive ? "#15803D" : "#94A3B8"};border-radius:20px;padding:.1rem .5rem;font-size:.7rem;font-weight:800">
                    ${row.isActive ? "🟢 Live" : "⚫ Inactive"}
                  </span>
                </td>
                <td style="padding:.4rem .7rem;text-align:right;font-size:1rem;font-weight:900;color:#0052CC">${row.imprInRange.toLocaleString()}</td>
                <td style="padding:.4rem .7rem;text-align:right;font-size:1rem;font-weight:900;color:#7C3AED">${row.clicksInRange.toLocaleString()}</td>
                <td style="padding:.4rem .7rem;text-align:right;font-size:.88rem;font-weight:700;color:${parseFloat(row.ctrRange) > 2 ? "#16A34A" : "#D97706"}">${row.ctrRange}</td>
                <td style="padding:.4rem .7rem;text-align:right;font-size:.82rem;color:#64748B">${row.totalImpr.toLocaleString()}</td>
                <td style="padding:.4rem .7rem;text-align:right;font-size:.82rem;color:#64748B">${row.ctrAll}</td>
              </tr>`,
              )
              .join("")}
            </tbody>
            <tfoot>
              <tr style="border-top:2px solid #FCD34D;background:rgba(180,83,9,.05)">
                <td colspan="3" style="padding:.4rem .7rem;font-weight:800;font-size:.82rem;color:#92400E">TOTAL</td>
                <td style="padding:.4rem .7rem;text-align:right;font-weight:900;font-size:.95rem;color:#0052CC">${brandRows.reduce((s, r) => s + r.imprInRange, 0).toLocaleString()}</td>
                <td style="padding:.4rem .7rem;text-align:right;font-weight:900;font-size:.95rem;color:#7C3AED">${brandRows.reduce((s, r) => s + r.clicksInRange, 0).toLocaleString()}</td>
                <td colspan="3"></td>
              </tr>
            </tfoot>
          </table>
        </div>
        <div style="font-size:.72rem;color:#92400E;margin-top:.5rem">
          💡 Impressions = times the ad was shown in search results. Clicks = customer tapped the sponsored card. Use <strong>Export CSV</strong> to send a report to your brand partner.
        </div>`;
    }
  }

  // ── 11. Traffic Sources, Devices, Countries, Cities ─────────────────
  // Aggregate from dailyDocs
  const sourceAgg = {},
    mediumAgg = {},
    deviceAgg = {},
    browserAgg = {},
    countryAgg = {},
    cityDetailAgg = {};
  const roleAgg = {}; // role → sessions
  const roleDevices = {}; // role → { device → count }
  const roleCountries = {}; // role → { country → count }
  const roleCities = {}; // role → { city → count }
  const roleSources = {}; // role → { source → count }
  const roleHours = {}; // role → { hour → count }
  const hourAgg = {}; // hour → count (all roles)
  let totalSessions = 0;

  dailyDocs.forEach((doc) => {
    totalSessions += parseInt(doc.sessions || 0);
    if (doc.sources)
      Object.entries(doc.sources).forEach(([k, v]) => {
        const k2 = k.replace(/_/g, " ");
        sourceAgg[k2] = (sourceAgg[k2] || 0) + parseInt(v || 0);
      });
    if (doc.mediums)
      Object.entries(doc.mediums).forEach(([k, v]) => {
        mediumAgg[k] = (mediumAgg[k] || 0) + parseInt(v || 0);
      });
    if (doc.devices)
      Object.entries(doc.devices).forEach(([k, v]) => {
        deviceAgg[k] = (deviceAgg[k] || 0) + parseInt(v || 0);
      });
    if (doc.browsers)
      Object.entries(doc.browsers).forEach(([k, v]) => {
        browserAgg[k] = (browserAgg[k] || 0) + parseInt(v || 0);
      });
    if (doc.countries)
      Object.entries(doc.countries).forEach(([k, v]) => {
        const k2 = k.replace(/_/g, " ");
        countryAgg[k2] = (countryAgg[k2] || 0) + parseInt(v || 0);
      });
    if (doc.cities)
      Object.entries(doc.cities).forEach(([k, v]) => {
        const k2 = k.replace(/_/g, " ");
        cityDetailAgg[k2] = (cityDetailAgg[k2] || 0) + parseInt(v || 0);
      });
    if (doc.hours)
      Object.entries(doc.hours).forEach(([k, v]) => {
        hourAgg[k] = (hourAgg[k] || 0) + parseInt(v || 0);
      });

    // Role segmentation
    if (doc.roles)
      Object.entries(doc.roles).forEach(([role, v]) => {
        roleAgg[role] = (roleAgg[role] || 0) + parseInt(v || 0);
      });
    ["customer", "rental", "lite", "admin"].forEach((role) => {
      const rd = doc[`role_devices`];
      const rc = doc[`role_countries`];
      const rci = doc[`role_cities`];
      const rs = doc[`role_sources`];
      const rh = doc[`role_hours`];
      if (rd?.[role]) {
        if (!roleDevices[role]) roleDevices[role] = {};
        Object.entries(rd[role]).forEach(([k, v]) => {
          roleDevices[role][k] = (roleDevices[role][k] || 0) + parseInt(v || 0);
        });
      }
      if (rc?.[role]) {
        if (!roleCountries[role]) roleCountries[role] = {};
        Object.entries(rc[role]).forEach(([k, v]) => {
          roleCountries[role][k.replace(/_/g, " ")] =
            (roleCountries[role][k.replace(/_/g, " ")] || 0) + parseInt(v || 0);
        });
      }
      if (rci?.[role]) {
        if (!roleCities[role]) roleCities[role] = {};
        Object.entries(rci[role]).forEach(([k, v]) => {
          roleCities[role][k.replace(/_/g, " ")] =
            (roleCities[role][k.replace(/_/g, " ")] || 0) + parseInt(v || 0);
        });
      }
      if (rs?.[role]) {
        if (!roleSources[role]) roleSources[role] = {};
        Object.entries(rs[role]).forEach(([k, v]) => {
          roleSources[role][k.replace(/_/g, " ")] =
            (roleSources[role][k.replace(/_/g, " ")] || 0) + parseInt(v || 0);
        });
      }
      if (rh?.[role]) {
        if (!roleHours[role]) roleHours[role] = {};
        Object.entries(rh[role]).forEach(([k, v]) => {
          roleHours[role][k] = (roleHours[role][k] || 0) + parseInt(v || 0);
        });
      }
    });
  });

  // Helper: horizontal bar mini-list
  const _miniBar = (data, color, maxItems = 5) => {
    const sorted = Object.entries(data)
      .sort((a, b) => b[1] - a[1])
      .slice(0, maxItems);
    const max = Math.max(...sorted.map(([, v]) => v), 1);
    const total = sorted.reduce((s, [, v]) => s + v, 0);
    if (sorted.length === 0)
      return `<div style="color:#94A3B8;font-size:.75rem;padding:.3rem 0">No data yet</div>`;
    return sorted
      .map(([k, v]) => {
        const pct = total > 0 ? Math.round((v / total) * 100) : 0;
        return `<div style="margin-bottom:.3rem">
        <div style="display:flex;justify-content:space-between;font-size:.73rem;font-weight:700;margin-bottom:.1rem">
          <span style="color:#334155;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:68%">${k}</span>
          <span style="color:${color};white-space:nowrap">${v} <span style="color:#94A3B8;font-weight:500">(${pct}%)</span></span>
        </div>
        <div style="background:#F1F5F9;border-radius:99px;height:5px;overflow:hidden">
          <div style="background:${color};width:${Math.round((v / max) * 100)}%;height:100%;border-radius:99px"></div>
        </div>
      </div>`;
      })
      .join("");
  };

  // Helper: peak hour mini sparkline
  const _hourSparkline = (hours) => {
    const arr = Array.from({ length: 24 }, (_, i) => parseInt(hours?.[i] || 0));
    const max = Math.max(...arr, 1);
    const peak = arr.indexOf(Math.max(...arr));
    return `<div style="display:flex;gap:1px;align-items:flex-end;height:28px;margin:.3rem 0">
      ${arr.map((v, i) => `<div title="${i}:00 — ${v}" style="flex:1;background:${v > 0 ? `rgba(0,82,204,${0.15 + 0.85 * (v / max)})` : "#F1F5F9"};border-radius:2px 2px 0 0;height:${Math.max(3, Math.round((v / max) * 26))}px"></div>`).join("")}
    </div>
    <div style="font-size:.68rem;color:#64748B">Peak: ${peak}:00–${peak + 1}:00 (${arr[peak]} sessions)</div>`;
  };

  // Helper: full role segment panel
  const _rolePanel = (role, label, icon, color, sessions) => {
    const devices = roleDevices[role] || {};
    const countries = roleCountries[role] || {};
    const cities = roleCities[role] || {};
    const sources = roleSources[role] || {};
    const hours = roleHours[role] || {};
    const topDevice =
      Object.entries(devices).sort((a, b) => b[1] - a[1])[0]?.[0] || "—";
    const topCity =
      Object.entries(cities).sort((a, b) => b[1] - a[1])[0]?.[0] || "—";
    const topSource =
      Object.entries(sources).sort((a, b) => b[1] - a[1])[0]?.[0] || "—";

    return `
      <div style="font-size:.82rem;font-weight:900;color:${color};margin-bottom:.6rem">${icon} ${label}</div>
      <div style="font-size:1.8rem;font-weight:900;color:${color};line-height:1;margin-bottom:.2rem">${(sessions || 0).toLocaleString()}</div>
      <div style="font-size:.7rem;color:#94A3B8;margin-bottom:.8rem">sessions in period</div>

      ${
        sessions === 0
          ? `<div style="color:#94A3B8;font-size:.78rem;text-align:center;padding:.8rem">No sessions yet — data builds up as users log in</div>`
          : `
      <div style="display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:.7rem">
        <span style="background:${color}18;color:${color};border-radius:6px;padding:.1rem .45rem;font-size:.7rem;font-weight:800">📱 ${topDevice}</span>
        <span style="background:${color}18;color:${color};border-radius:6px;padding:.1rem .45rem;font-size:.7rem;font-weight:800">📍 ${topCity}</span>
        <span style="background:${color}18;color:${color};border-radius:6px;padding:.1rem .45rem;font-size:.7rem;font-weight:800">🌐 ${topSource}</span>
      </div>

      <div style="font-size:.72rem;font-weight:800;color:#334155;margin-bottom:.3rem">📍 Top Cities</div>
      ${_miniBar(cities, color, 5)}

      <div style="font-size:.72rem;font-weight:800;color:#334155;margin-top:.55rem;margin-bottom:.3rem">🗺️ Countries</div>
      ${_miniBar(countries, color, 4)}

      <div style="font-size:.72rem;font-weight:800;color:#334155;margin-top:.55rem;margin-bottom:.3rem">📱 Devices</div>
      ${_miniBar(devices, color, 3)}

      <div style="font-size:.72rem;font-weight:800;color:#334155;margin-top:.55rem;margin-bottom:.3rem">🌐 Traffic Sources</div>
      ${_miniBar(sources, color, 4)}

      <div style="font-size:.72rem;font-weight:800;color:#334155;margin-top:.55rem;margin-bottom:.2rem">🕐 Active Hours (AEST)</div>
      ${_hourSparkline(hours)}`
      }`;
  };

  // Render the 3 role panels
  const segCustomer = document.getElementById("analytics-seg-customer");
  const segRental = document.getElementById("analytics-seg-rental");
  const segLite = document.getElementById("analytics-seg-lite");
  if (segCustomer)
    segCustomer.innerHTML = _rolePanel(
      "customer",
      "Customers",
      "🧑",
      "#0052CC",
      roleAgg.customer || 0,
    );
  if (segRental)
    segRental.innerHTML = _rolePanel(
      "rental",
      "Rental Companies",
      "🏗️",
      "#16A34A",
      roleAgg.rental || 0,
    );
  if (segLite)
    segLite.innerHTML = _rolePanel(
      "lite",
      "Lite Portal",
      "🔵",
      "#7C3AED",
      roleAgg.lite || 0,
    );

  // Helper: render a horizontal bar list
  const _barList = (title, icon, data, color, note = "") => {
    const sorted = Object.entries(data)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10);
    const max = Math.max(...sorted.map(([, v]) => v), 1);
    const total = sorted.reduce((s, [, v]) => s + v, 0);
    return `
      <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.6rem">${icon} ${title}</div>
      ${note ? `<div style="font-size:.72rem;color:#64748B;margin-bottom:.6rem">${note}</div>` : ""}
      ${
        sorted.length === 0
          ? `<div style="text-align:center;color:#94A3B8;font-size:.82rem;padding:1rem">No data yet — will populate as visitors arrive</div>`
          : sorted
              .map(([k, v]) => {
                const pct = total > 0 ? Math.round((v / total) * 100) : 0;
                return `<div style="margin-bottom:.35rem">
              <div style="display:flex;justify-content:space-between;font-size:.75rem;font-weight:700;margin-bottom:.15rem">
                <span style="color:#334155;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:65%">${k}</span>
                <span style="color:${color};font-weight:900;white-space:nowrap">${v.toLocaleString()} <span style="color:#94A3B8;font-weight:500">(${pct}%)</span></span>
              </div>
              <div style="background:#F1F5F9;border-radius:99px;height:7px;overflow:hidden">
                <div style="background:${color};width:${Math.round((v / max) * 100)}%;height:100%;border-radius:99px"></div>
              </div>
            </div>`;
              })
              .join("")
      }`;
  };

  // Traffic sources
  const tsEl2 = document.getElementById("analytics-traffic-sources");
  if (tsEl2)
    tsEl2.innerHTML =
      _barList(
        `Traffic Sources — ${totalSessions.toLocaleString()} sessions`,
        "🌐",
        sourceAgg,
        "#0052CC",
        "Where visitors come from before landing on Noyo",
      ) +
      `<div style="margin-top:.8rem;border-top:1px solid #F1F5F9;padding-top:.6rem">` +
      _barList("Traffic Medium", "📡", mediumAgg, "#7C3AED") +
      `</div>`;

  // Devices
  const devEl = document.getElementById("analytics-devices");
  if (devEl)
    devEl.innerHTML =
      _barList(
        "Devices",
        "📱",
        deviceAgg,
        "#16A34A",
        "Desktop vs Mobile vs Tablet split",
      ) +
      `<div style="margin-top:.8rem;border-top:1px solid #F1F5F9;padding-top:.6rem">` +
      _barList("Browsers", "🌍", browserAgg, "#0891B2") +
      `</div>`;

  // Countries
  const ctrEl = document.getElementById("analytics-countries");
  if (ctrEl)
    ctrEl.innerHTML = _barList(
      "Countries",
      "🗺️",
      countryAgg,
      "#D97706",
      "Visitor country — detected from IP address",
    );

  // Cities detail
  const citEl = document.getElementById("analytics-cities-detail");
  if (citEl)
    citEl.innerHTML = _barList(
      "Cities",
      "📍",
      cityDetailAgg,
      "#DC2626",
      "City-level breakdown across all visitors",
    );

  // ── 12. Revenue & GMV Intelligence ────────────────────────────────────
  const revEl = document.getElementById("analytics-revenue");
  if (revEl) {
    const allAccepted = recentQuotes.filter((q) => q.acceptedBy);
    const allResponded = recentQuotes.filter(
      (q) => (q.responses || []).length > 0,
    );
    const gmv = allAccepted.reduce(
      (s, q) =>
        s + ((q.responses || []).find((r) => r.accepted)?.grandTotal || 0),
      0,
    );
    const pipeline = allResponded
      .filter((q) => !q.acceptedBy)
      .reduce(
        (s, q) =>
          s +
          Math.min(
            ...(q.responses || [])
              .map(
                (r) =>
                  parseFloat(
                    String(r.grandTotal || 0).replace(/[^0-9.]/g, ""),
                  ) || 0,
              )
              .filter((v) => v > 0),
            0,
          ),
        0,
      );
    const avgDeal = allAccepted.length > 0 ? gmv / allAccepted.length : 0;
    const allQuoteVals = recentQuotes
      .flatMap((q) =>
        (q.responses || []).map(
          (r) =>
            parseFloat(String(r.grandTotal || 0).replace(/[^0-9.]/g, "")) || 0,
        ),
      )
      .filter((v) => v > 0);
    const avgQuote =
      allQuoteVals.length > 0
        ? allQuoteVals.reduce((a, b) => a + b, 0) / allQuoteVals.length
        : 0;
    const conversionAmt =
      gmv > 0 && totalCartAdds > 0 ? gmv / totalCartAdds : 0;

    // GMV by category
    const gmvByCat = {};
    allAccepted.forEach((q) => {
      const resp = (q.responses || []).find((r) => r.accepted);
      if (!resp) return;
      const cat = q.machineType || q.machines?.[0]?.type || "Other";
      gmvByCat[cat] = (gmvByCat[cat] || 0) + (resp.grandTotal || 0);
    });

    const _moneyCard = (icon, val, label, sub, color) =>
      `<div style="background:#fff;border-radius:12px;padding:.8rem 1rem;border-left:4px solid ${color}">
        <div style="font-size:1.6rem;font-weight:900;color:${color}">${val}</div>
        <div style="font-size:.8rem;font-weight:800;color:#0F172A;margin:.15rem 0">${icon} ${label}</div>
        <div style="font-size:.72rem;color:#64748B">${sub}</div>
       </div>`;

    const _fmt = (v) =>
      v >= 1000000
        ? `$${(v / 1000000).toFixed(2)}M`
        : v >= 1000
          ? `$${(v / 1000).toFixed(1)}K`
          : `$${v.toFixed(0)}`;

    revEl.innerHTML =
      _moneyCard(
        "🏆",
        _fmt(gmv),
        "Confirmed GMV",
        `${allAccepted.length} hires confirmed`,
        "#16A34A",
      ) +
      _moneyCard(
        "⏳",
        _fmt(pipeline),
        "Quote Pipeline",
        "Active quotes awaiting acceptance",
        "#D97706",
      ) +
      _moneyCard(
        "📊",
        _fmt(avgDeal),
        "Avg Deal Size",
        "Per confirmed hire",
        "#0052CC",
      ) +
      _moneyCard(
        "💬",
        _fmt(avgQuote),
        "Avg Quote Value",
        "Across all rental co responses",
        "#7C3AED",
      ) +
      (Object.keys(gmvByCat).length > 0
        ? `
        <div style="background:#fff;border-radius:12px;padding:.8rem 1rem;grid-column:1/-1">
          <div style="font-size:.78rem;font-weight:800;color:#14532D;margin-bottom:.5rem">💰 GMV by Category</div>
          ${Object.entries(gmvByCat)
            .sort((a, b) => b[1] - a[1])
            .map(
              ([cat, v]) => `
            <div style="display:flex;justify-content:space-between;font-size:.78rem;padding:.2rem 0;border-bottom:1px solid #F1F5F9">
              <span style="color:#334155;font-weight:600">${cat}</span>
              <span style="font-weight:900;color:#16A34A">${_fmt(v)}</span>
            </div>`,
            )
            .join("")}
        </div>`
        : "");
  }

  // ── 13. Marketplace Health Score ──────────────────────────────────────
  const healthEl = document.getElementById("analytics-health");
  if (healthEl) {
    const liquidity =
      totalQuotes > 0 ? Math.round((totalResponded / totalQuotes) * 100) : 0; // % of enquiries that got ≥1 quote
    const acceptRate =
      totalResponded > 0
        ? Math.round((totalAccepted / totalResponded) * 100)
        : 0;
    const fillRate =
      totalQuotes > 0 ? Math.round((totalAccepted / totalQuotes) * 100) : 0;
    const zeroRatePct =
      totalSearches > 0
        ? Math.round(
            (searchRecs.filter((s) => s.zeroResults).length /
              Math.max(totalSearches, 1)) *
              100,
          )
        : 0;
    const avgRespPerEnq =
      totalResponded > 0
        ? (
            recentQuotes
              .filter((q) => (q.responses || []).length > 0)
              .reduce((s, q) => s + (q.responses || []).length, 0) /
            totalResponded
          ).toFixed(1)
        : "—";

    const _score = (val, good, ok) =>
      val >= good ? "#16A34A" : val >= ok ? "#D97706" : "#DC2626";
    const _healthBar = (label, val, unit, good, ok, note) => {
      const c = _score(val, good, ok);
      return `<div style="margin-bottom:.6rem">
        <div style="display:flex;justify-content:space-between;font-size:.78rem;font-weight:700;margin-bottom:.18rem">
          <span style="color:#334155">${label}</span>
          <span style="color:${c};font-weight:900">${val}${unit} <span style="font-size:.68rem;color:#94A3B8">${note}</span></span>
        </div>
        <div style="background:#F1F5F9;border-radius:99px;height:8px;overflow:hidden">
          <div style="background:${c};width:${Math.min(val, 100)}%;height:100%;border-radius:99px;transition:width .5s"></div>
        </div>
      </div>`;
    };

    const overallScore = Math.round(
      liquidity * 0.3 +
        acceptRate * 0.3 +
        fillRate * 0.2 +
        Math.max(0, 100 - zeroRatePct * 5) * 0.2,
    );
    const scoreColor =
      overallScore >= 70
        ? "#16A34A"
        : overallScore >= 45
          ? "#D97706"
          : "#DC2626";
    const scoreLabel =
      overallScore >= 70
        ? "Healthy"
        : overallScore >= 45
          ? "Growing"
          : "Early Stage";

    healthEl.innerHTML = `
      <div style="display:flex;align-items:center;gap:1rem;margin-bottom:.9rem;flex-wrap:wrap">
        <div>
          <div style="font-weight:900;font-size:.88rem;color:#0F172A">🩺 Marketplace Health Score</div>
          <div style="font-size:.72rem;color:#64748B">How well supply is meeting demand</div>
        </div>
        <div style="margin-left:auto;text-align:center">
          <div style="font-size:2.5rem;font-weight:900;color:${scoreColor};line-height:1">${overallScore}</div>
          <div style="font-size:.72rem;font-weight:800;color:${scoreColor}">${scoreLabel}</div>
        </div>
      </div>
      ${_healthBar("💧 Liquidity — enquiries getting ≥1 quote", liquidity, "%", 80, 50, "(target: 80%+)")}
      ${_healthBar("✅ Accept Rate — quotes leading to hire", acceptRate, "%", 30, 15, "(target: 30%+)")}
      ${_healthBar("📨 Fill Rate — enquiries leading to hire", fillRate, "%", 25, 10, "(target: 25%+)")}
      ${_healthBar("🔍 Search Match Rate — searches finding machines", Math.max(0, 100 - zeroRatePct * 2), "%", 85, 70, "(target: 85%+)")}
      <div style="font-size:.75rem;color:#64748B;margin-top:.3rem">Avg quotes per enquiry: <strong>${avgRespPerEnq}</strong> (healthy = 3+)</div>`;
  }

  // ── 14. Response Time Intelligence ────────────────────────────────────
  const rtEl = document.getElementById("analytics-response-times");
  if (rtEl) {
    const respTimes = [];
    recentQuotes.forEach((q) => {
      if (!q.ts) return;
      (q.responses || []).forEach((r) => {
        if (r.ts && r.ts > q.ts) {
          const hrs = (r.ts - q.ts) / 3600000;
          if (hrs < 336) respTimes.push({ hrs, company: r.company });
        }
      });
    });
    const avg =
      respTimes.length > 0
        ? respTimes.reduce((s, r) => s + r.hrs, 0) / respTimes.length
        : null;
    const med =
      respTimes.length > 0
        ? [...respTimes].sort((a, b) => a.hrs - b.hrs)[
            Math.floor(respTimes.length / 2)
          ].hrs
        : null;
    const u24 = respTimes.filter((r) => r.hrs <= 24).length;
    const u4 = respTimes.filter((r) => r.hrs <= 4).length;

    const byCompany = {};
    respTimes.forEach((r) => {
      if (!byCompany[r.company]) byCompany[r.company] = [];
      byCompany[r.company].push(r.hrs);
    });
    const rcTimes = Object.entries(byCompany)
      .map(([co, hrs]) => ({
        co,
        avg: hrs.reduce((a, b) => a + b, 0) / hrs.length,
        count: hrs.length,
      }))
      .sort((a, b) => a.avg - b.avg)
      .slice(0, 6);

    rtEl.innerHTML = `
      <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.6rem">⏱️ Response Time Intelligence</div>
      ${
        avg === null
          ? `<div style="color:#94A3B8;text-align:center;padding:1rem;font-size:.82rem">No response data yet in this period</div>`
          : `<div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-bottom:.7rem">
            ${[
              [
                "⚡ Avg Response",
                avg
                  ? avg < 1
                    ? Math.round(avg * 60) + "m"
                    : avg.toFixed(1) + "h"
                  : "—",
                avg < 4 ? "#16A34A" : avg < 24 ? "#D97706" : "#DC2626",
              ],
              [
                "📊 Median",
                med
                  ? med < 1
                    ? Math.round(med * 60) + "m"
                    : med.toFixed(1) + "h"
                  : "—",
                med < 4 ? "#16A34A" : med < 24 ? "#D97706" : "#DC2626",
              ],
              [
                "🚀 Under 4hrs",
                u4 +
                  " (" +
                  Math.round((u4 / Math.max(respTimes.length, 1)) * 100) +
                  "%)",
                "#0052CC",
              ],
              [
                "✅ Under 24hrs",
                u24 +
                  " (" +
                  Math.round((u24 / Math.max(respTimes.length, 1)) * 100) +
                  "%)",
                "#7C3AED",
              ],
            ]
              .map(
                ([
                  l,
                  v,
                  c,
                ]) => `<div style="background:#F8FAFC;border-radius:10px;padding:.5rem .7rem;border-left:3px solid ${c}">
                <div style="font-size:1.1rem;font-weight:900;color:${c}">${v}</div>
                <div style="font-size:.7rem;color:#64748B">${l}</div>
              </div>`,
              )
              .join("")}
          </div>
          <div style="font-size:.75rem;font-weight:800;color:#334155;margin-bottom:.4rem">Fastest Responders</div>
          ${rcTimes
            .map(
              (
                r,
              ) => `<div style="display:flex;justify-content:space-between;font-size:.75rem;padding:.2rem 0;border-bottom:1px solid #F8FAFC">
            <span style="color:#334155;font-weight:600">${r.co}</span>
            <span style="font-weight:800;color:${r.avg < 4 ? "#16A34A" : r.avg < 24 ? "#D97706" : "#DC2626"}">${r.avg < 1 ? Math.round(r.avg * 60) + "m" : r.avg.toFixed(1) + "h"} avg</span>
          </div>`,
            )
            .join("")}`
      }`;
  }

  // ── 15. Peak Hours heatmap ─────────────────────────────────────────────
  const phEl = document.getElementById("analytics-peak-hours");
  if (phEl) {
    const hourCounts = Array(24).fill(0);
    const dayCounts = Array(7).fill(0); // 0=Sun
    searchRecs.forEach((s) => {
      if (s.hour != null) hourCounts[s.hour]++;
      if (s.ts) dayCounts[new Date(s.ts).getDay()]++;
    });
    recentQuotes.forEach((q) => {
      if (q.ts) {
        hourCounts[new Date(q.ts).getHours()]++;
        dayCounts[new Date(q.ts).getDay()]++;
      }
    });
    const maxH = Math.max(...hourCounts, 1);
    const maxD = Math.max(...dayCounts, 1);
    const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

    phEl.innerHTML = `
      <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.6rem">🕐 Peak Activity Times</div>
      <div style="font-size:.73rem;font-weight:700;color:#64748B;margin-bottom:.3rem">By hour (AEST)</div>
      <div style="display:flex;gap:2px;align-items:flex-end;height:50px;margin-bottom:.8rem">
        ${hourCounts.map((v, i) => `<div title="${i}:00 — ${v} events" style="flex:1;background:${v > 0 ? `rgba(0,82,204,${0.15 + 0.85 * (v / maxH)})` : "#F1F5F9"};border-radius:3px 3px 0 0;height:${Math.max(4, Math.round((v / maxH) * 46))}px"></div>`).join("")}
      </div>
      <div style="display:flex;font-size:.6rem;color:#94A3B8;margin-bottom:.8rem;gap:2px">
        ${Array.from({ length: 24 }, (_, i) => (i % 4 === 0 ? `<div style="flex:1;text-align:left">${i}</div>` : `<div style="flex:1"></div>`)).join("")}
      </div>
      <div style="font-size:.73rem;font-weight:700;color:#64748B;margin-bottom:.3rem">By day of week</div>
      <div style="display:flex;gap:.3rem">
        ${dayCounts
          .map(
            (v, i) => `<div style="flex:1;text-align:center">
          <div style="background:${v > 0 ? `rgba(124,58,237,${0.15 + 0.85 * (v / maxD)})` : "#F1F5F9"};border-radius:6px;padding:.2rem;font-size:.65rem;font-weight:800;color:${v > maxD * 0.5 ? "#fff" : "#7C3AED"};min-height:28px;display:flex;align-items:center;justify-content:center">${v || ""}</div>
          <div style="font-size:.62rem;color:#94A3B8;margin-top:.15rem">${days[i]}</div>
        </div>`,
          )
          .join("")}
      </div>`;
  }

  // ── 16. Demand Gaps ────────────────────────────────────────────────────
  const dgEl = document.getElementById("analytics-demand-gaps");
  if (dgEl) {
    const zeroHits = searchRecs.filter((s) => s.zeroResults);
    const zrByCat2 = {};
    zeroHits.forEach((s) => {
      const t = s.machineName || s.jobType || "Unknown";
      if (!zrByCat2[t]) zrByCat2[t] = { count: 0, locations: [] };
      zrByCat2[t].count++;
      if (s.city && s.city !== "—") zrByCat2[t].locations.push(s.city);
    });
    const sorted = Object.entries(zrByCat2).sort(
      (a, b) => b[1].count - a[1].count,
    );

    dgEl.innerHTML = `
      <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.7rem">
        <div>
          <div style="font-weight:800;font-size:.88rem;color:#991B1B">🎯 Demand Gaps — Unmet Customer Needs</div>
          <div style="font-size:.72rem;color:#64748B">Searches that returned zero machines — these are your biggest growth opportunities</div>
        </div>
        <span style="margin-left:auto;background:#DC2626;color:#fff;border-radius:20px;padding:.2rem .65rem;font-size:.78rem;font-weight:900">${zeroHits.length} misses</span>
      </div>
      ${
        sorted.length === 0
          ? `<div style="text-align:center;color:#16A34A;padding:.8rem;font-size:.82rem">✅ No unmet demand in this period — great fleet coverage!</div>`
          : `<table style="width:100%;border-collapse:collapse">
            <thead><tr style="background:#FEF2F2">
              <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#991B1B;text-align:left">Category</th>
              <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#991B1B;text-align:right">Missed</th>
              <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#991B1B;text-align:left">Top Locations</th>
              <th style="padding:.3rem .6rem;font-size:.72rem;font-weight:700;color:#991B1B;text-align:left">Action</th>
            </tr></thead><tbody>
            ${sorted
              .slice(0, 10)
              .map(([cat, d]) => {
                const topLoc =
                  [...new Set(d.locations)].slice(0, 2).join(", ") || "—";
                return `<tr style="border-top:1px solid #FEE2E2">
                <td style="padding:.35rem .6rem;font-size:.78rem;font-weight:700;color:#0F172A">${cat}</td>
                <td style="padding:.35rem .6rem;text-align:right;font-weight:900;color:#DC2626">${d.count}</td>
                <td style="padding:.35rem .6rem;font-size:.75rem;color:#64748B">${topLoc}</td>
                <td style="padding:.35rem .6rem;font-size:.72rem;color:#0052CC;font-weight:700">Add to fleet / onboard RC</td>
              </tr>`;
              })
              .join("")}
            </tbody></table>`
      }`;
  }

  // ── 17. User Cohorts (New vs Returning) ────────────────────────────────
  const ucEl = document.getElementById("analytics-user-cohorts");
  if (ucEl) {
    const allEmails = new Set();
    const periodEmails = new Set();
    const returnEmails = new Set();
    adminData.searches.forEach((s) => {
      if (s.email && s.email !== "unknown") allEmails.add(s.email);
    });
    searchRecs.forEach((s) => {
      if (!s.email || s.email === "unknown") return;
      periodEmails.add(s.email);
      if (allEmails.has(s.email) && !periodEmails.has(s.email))
        returnEmails.add(s.email);
    });
    const newUsers = [...periodEmails].filter(
      (e) => !returnEmails.has(e),
    ).length;
    const retUsers = returnEmails.size;
    const totalU = periodEmails.size;

    ucEl.innerHTML = `
      <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.7rem">👥 New vs Returning Users</div>
      <div style="display:flex;gap:.5rem;margin-bottom:.7rem">
        <div style="flex:1;background:#EFF6FF;border-radius:10px;padding:.65rem;text-align:center;border-top:3px solid #0052CC">
          <div style="font-size:1.6rem;font-weight:900;color:#0052CC">${newUsers}</div>
          <div style="font-size:.72rem;color:#64748B">🆕 New Users</div>
        </div>
        <div style="flex:1;background:#F0FDF4;border-radius:10px;padding:.65rem;text-align:center;border-top:3px solid #16A34A">
          <div style="font-size:1.6rem;font-weight:900;color:#16A34A">${retUsers}</div>
          <div style="font-size:.72rem;color:#64748B">🔄 Returning</div>
        </div>
        <div style="flex:1;background:#F8FAFC;border-radius:10px;padding:.65rem;text-align:center;border-top:3px solid #64748B">
          <div style="font-size:1.6rem;font-weight:900;color:#334155">${totalU}</div>
          <div style="font-size:.72rem;color:#64748B">👤 Total</div>
        </div>
      </div>
      <div style="font-size:.75rem;color:#64748B">
        <strong>Retention rate:</strong> ${totalU > 0 ? Math.round((retUsers / totalU) * 100) : 0}% of users in this period are returning visitors.<br>
        <span style="color:#0052CC;font-weight:700">Target: 30%+</span> means your platform is sticky.
      </div>`;
  }

  // ── 18. Top Customers by Enquiry Volume ────────────────────────────────
  const tcEl2 = document.getElementById("analytics-top-customers");
  if (tcEl2) {
    const custActivity = {};
    recentQuotes.forEach((q) => {
      const e = q.email || q.customerEmail || "unknown";
      if (e === "unknown" || !e) return;
      if (!custActivity[e])
        custActivity[e] = {
          name: q.customerName || q.company || e.split("@")[0],
          enquiries: 0,
          accepted: 0,
          value: 0,
        };
      custActivity[e].enquiries++;
      if (q.acceptedBy) {
        custActivity[e].accepted++;
        const v = parseFloat(
          ((q.responses || []).find((r) => r.accepted) || {}).grandTotal || 0,
        );
        custActivity[e].value += v;
      }
    });
    const topCust = Object.entries(custActivity)
      .sort((a, b) => b[1].enquiries - a[1].enquiries)
      .slice(0, 8);
    tcEl2.innerHTML = `
      <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.6rem">🏆 Most Active Customers</div>
      ${
        topCust.length === 0
          ? `<div style="text-align:center;color:#94A3B8;font-size:.82rem;padding:1rem">No customer data in this period</div>`
          : topCust
              .map(
                ([e, c], i) => `
          <div style="display:flex;align-items:center;gap:.5rem;padding:.3rem 0;border-bottom:1px solid #F8FAFC">
            <div style="width:22px;height:22px;background:#EFF6FF;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.68rem;font-weight:900;color:#0052CC;flex-shrink:0">${i + 1}</div>
            <div style="flex:1;min-width:0">
              <div style="font-size:.78rem;font-weight:700;color:#0F172A;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${c.name}</div>
              <div style="font-size:.68rem;color:#94A3B8">${c.enquiries} enquir${c.enquiries !== 1 ? "ies" : "y"} · ${c.accepted} hired</div>
            </div>
            ${c.value > 0 ? `<div style="font-size:.78rem;font-weight:900;color:#16A34A;flex-shrink:0">$${c.value >= 1000 ? (c.value / 1000).toFixed(1) + "K" : c.value.toFixed(0)}</div>` : ""}
          </div>`,
              )
              .join("")
      }`;
  }

  // ── 19. RC Leaderboard ─────────────────────────────────────────────────
  const rcLbEl = document.getElementById("analytics-rc-leaderboard");
  if (rcLbEl) {
    const rcBoard = {};
    recentQuotes.forEach((q) => {
      (q.responses || []).forEach((r) => {
        if (!r.company) return;
        if (!rcBoard[r.company])
          rcBoard[r.company] = {
            quotes: 0,
            wins: 0,
            value: 0,
            avgTime: null,
            times: [],
          };
        rcBoard[r.company].quotes++;
        if (r.accepted) {
          rcBoard[r.company].wins++;
          rcBoard[r.company].value +=
            parseFloat(String(r.grandTotal || 0).replace(/[^0-9.]/g, "")) || 0;
        }
        if (r.ts && q.ts && r.ts > q.ts)
          rcBoard[r.company].times.push((r.ts - q.ts) / 3600000);
      });
    });
    Object.values(rcBoard).forEach((rc) => {
      rc.avgTime =
        rc.times.length > 0
          ? rc.times.reduce((a, b) => a + b, 0) / rc.times.length
          : null;
      rc.winRate = rc.quotes > 0 ? Math.round((rc.wins / rc.quotes) * 100) : 0;
    });
    const sorted = Object.entries(rcBoard)
      .sort((a, b) => b[1].wins - a[1].wins)
      .slice(0, 8);
    rcLbEl.innerHTML = `
      <div style="font-weight:800;font-size:.88rem;color:#0F172A;margin-bottom:.6rem">🏗️ Rental Company Leaderboard</div>
      ${
        sorted.length === 0
          ? `<div style="text-align:center;color:#94A3B8;font-size:.82rem;padding:1rem">No RC activity in this period</div>`
          : `<table style="width:100%;border-collapse:collapse">
            <thead><tr style="background:#F8FAFC">
              <th style="padding:.25rem .4rem;font-size:.68rem;color:#64748B;text-align:left">#</th>
              <th style="padding:.25rem .4rem;font-size:.68rem;color:#64748B;text-align:left">Company</th>
              <th style="padding:.25rem .4rem;font-size:.68rem;color:#64748B;text-align:right">Quotes</th>
              <th style="padding:.25rem .4rem;font-size:.68rem;color:#64748B;text-align:right">Wins</th>
              <th style="padding:.25rem .4rem;font-size:.68rem;color:#64748B;text-align:right">Win%</th>
              <th style="padding:.25rem .4rem;font-size:.68rem;color:#64748B;text-align:right">Avg Resp</th>
            </tr></thead><tbody>
            ${sorted
              .map(
                ([co, rc], i) => `
              <tr style="border-top:1px solid #F1F5F9">
                <td style="padding:.25rem .4rem;font-size:.72rem;color:#94A3B8;font-weight:700">${i + 1}</td>
                <td style="padding:.25rem .4rem;font-size:.75rem;font-weight:700;color:#0F172A">${co}</td>
                <td style="padding:.25rem .4rem;text-align:right;font-size:.78rem;color:#7C3AED;font-weight:700">${rc.quotes}</td>
                <td style="padding:.25rem .4rem;text-align:right;font-size:.78rem;color:#16A34A;font-weight:900">${rc.wins}</td>
                <td style="padding:.25rem .4rem;text-align:right;font-size:.78rem;font-weight:700;color:${rc.winRate >= 30 ? "#16A34A" : rc.winRate >= 15 ? "#D97706" : "#DC2626"}">${rc.winRate}%</td>
                <td style="padding:.25rem .4rem;text-align:right;font-size:.75rem;color:#64748B">${rc.avgTime != null ? (rc.avgTime < 1 ? Math.round(rc.avgTime * 60) + "m" : rc.avgTime.toFixed(1) + "h") : "—"}</td>
              </tr>`,
              )
              .join("")}
            </tbody></table>`
      }`;
  }

  // Store brand rows in window for CSV export
  window._lastBrandReportRows = (_sponsoredAds || []).map((ad) => {
    let imprInRange = 0,
      clicksInRange = 0;
    if (ad.dailyStats)
      Object.entries(ad.dailyStats).forEach(([day, s]) => {
        if (day >= fromDate && day <= toDate) {
          imprInRange += parseInt(s.impressions || 0);
          clicksInRange += parseInt(s.clicks || 0);
        }
      });
    const ctrRange =
      imprInRange > 0
        ? ((clicksInRange / imprInRange) * 100).toFixed(1) + "%"
        : "0%";
    return {
      brand: ad.brand || "—",
      category: ad.category || "All",
      status: ad.active && !_spnIsExpired(ad) ? "Live" : "Inactive",
      imprInRange,
      clicksInRange,
      ctrRange,
      totalImpr: parseInt(ad.impressions) || 0,
      totalClicks: parseInt(ad.clicks) || 0,
    };
  });
  window._lastBrandReportPeriod = `${fromDate}_to_${toDate}`;

  // ── Snapshot all analytics data for Excel/PDF export ──────────────────
  window._noyoAnalyticsSnap = {
    period: { from: fromDate, to: toDate },
    kpis: {
      totalSearches,
      totalCartAdds,
      totalQuotes,
      totalAccepted,
      totalResponded,
      convRate: parseFloat(convRate),
      quoteRate: parseFloat(quoteRate),
    },
    categories: combinedCat,
    cities: cityAgg,
    sources: Object.fromEntries(
      dailyDocs
        .flatMap((d) => Object.entries(d.sources || {}))
        .reduce((m, [k, v]) => {
          m.set(k, (m.get(k) || 0) + parseInt(v || 0));
          return m;
        }, new Map()),
    ),
    devices: Object.fromEntries(
      dailyDocs
        .flatMap((d) => Object.entries(d.devices || {}))
        .reduce((m, [k, v]) => {
          m.set(k, (m.get(k) || 0) + parseInt(v || 0));
          return m;
        }, new Map()),
    ),
    countries: Object.fromEntries(
      dailyDocs
        .flatMap((d) => Object.entries(d.countries || {}))
        .reduce((m, [k, v]) => {
          m.set(
            k.replace(/_/g, " "),
            (m.get(k.replace(/_/g, " ")) || 0) + parseInt(v || 0),
          );
          return m;
        }, new Map()),
    ),
    quotes: recentQuotes,
    brandRows: window._lastBrandReportRows || [],
    machineTop: Object.entries(machineAgg)
      .sort((a, b) => b[1].views - a[1].views)
      .slice(0, 20)
      .map(([id, m]) => ({
        id,
        name: m.name,
        brand: m.brand,
        views: m.views,
        cartAdds: m.cartAdds,
      })),
    dailySeries: dateList.map((d) => ({
      date: d,
      searches: dailySearch[d] || 0,
      cartAdds: dailyCart[d] || 0,
      quotes: dailyQuote[d] || 0,
    })),
  };
}

function exportAnalyticsExcel() {
  if (typeof XLSX === "undefined") {
    showToast("Excel library loading — try again", "#F59E0B");
    return;
  }
  const snap = window._noyoAnalyticsSnap;
  if (!snap) {
    showToast("Run analytics first", "#F59E0B");
    return;
  }
  showToast("Building Excel report...", "#16A34A", 2000);
  const wb = XLSX.utils.book_new();
  const { period, kpis } = snap;
  const S = (rows) => XLSX.utils.aoa_to_sheet(rows);

  // Sheet 1: Summary KPIs
  wb.Sheets["Summary"] = S([
    ["NOYO ANALYTICS REPORT"],
    ["Period: " + period.from + " to " + period.to],
    ["Generated: " + new Date().toLocaleString("en-AU")],
    [],
    ["KPI", "Value", "Notes"],
    ["Total Searches", kpis.totalSearches, "Unique search sessions"],
    ["Cart Adds", kpis.totalCartAdds, "Machines added to hire enquiry"],
    [
      "Quotes Sent",
      kpis.totalQuotes,
      "Enquiries submitted to rental companies",
    ],
    ["Hires Accepted", kpis.totalAccepted, "Confirmed hire outcomes"],
    ["Responded", kpis.totalResponded, "Enquiries with at least 1 quote"],
    ["Search to Cart Rate", kpis.convRate + "%", "Target: 10%+"],
    ["Cart to Quote Rate", kpis.quoteRate + "%", "Target: 60%+"],
    [
      "Match Rate",
      kpis.totalQuotes > 0
        ? Math.round((kpis.totalResponded / kpis.totalQuotes) * 100) + "%"
        : "0%",
      "Target: 80%+",
    ],
  ]);
  wb.SheetNames.push("Summary");

  // Sheet 2: Daily Activity
  wb.Sheets["Daily Activity"] = S([
    ["Date", "Searches", "Cart Adds", "Quotes Sent"],
    ...snap.dailySeries.map((d) => [d.date, d.searches, d.cartAdds, d.quotes]),
  ]);
  wb.SheetNames.push("Daily Activity");

  // Sheet 3: Categories
  wb.Sheets["Categories"] = S([
    ["Category", "Search Count"],
    ...Object.entries(snap.categories)
      .sort((a, b) => b[1] - a[1])
      .map(([k, v]) => [k, v]),
  ]);
  wb.SheetNames.push("Categories");

  // Sheet 4: Geography
  wb.Sheets["Geography"] = S([
    ["City", "Sessions"],
    ...Object.entries(snap.cities)
      .sort((a, b) => b[1] - a[1])
      .map(([k, v]) => [k, Math.round(v)]),
    [],
    ["Country", "Sessions"],
    ...Object.entries(snap.countries || {})
      .sort((a, b) => b[1] - a[1])
      .map(([k, v]) => [k, v]),
  ]);
  wb.SheetNames.push("Geography");

  // Sheet 5: Traffic Sources
  wb.Sheets["Traffic Sources"] = S([
    ["Source", "Sessions"],
    ...Object.entries(snap.sources || {})
      .sort((a, b) => b[1] - a[1])
      .map(([k, v]) => [k.replace(/_/g, " "), v]),
    [],
    ["Device", "Sessions"],
    ...Object.entries(snap.devices || {})
      .sort((a, b) => b[1] - a[1])
      .map(([k, v]) => [k, v]),
  ]);
  wb.SheetNames.push("Traffic Sources");

  // Sheet 6: Top Machines
  wb.Sheets["Top Machines"] = S([
    ["#", "Machine", "Brand", "Views", "Cart Adds", "Conversion %"],
    ...snap.machineTop.map((m, i) => [
      i + 1,
      m.name,
      m.brand || "",
      m.views,
      m.cartAdds,
      m.views > 0 ? ((m.cartAdds / m.views) * 100).toFixed(1) + "%" : "0%",
    ]),
  ]);
  wb.SheetNames.push("Top Machines");

  // Sheet 7: Quotes Pipeline
  wb.Sheets["Quotes"] = S([
    [
      "ID",
      "Date",
      "Customer",
      "Machines",
      "City",
      "Responses",
      "Status",
      "Value AUD",
    ],
    ...snap.quotes.map((q) => {
      const resp = (q.responses || []).find((r) => r.accepted);
      const status = q.acceptedBy
        ? "Accepted"
        : (q.responses || []).length > 0
          ? "Quoted"
          : "Pending";
      return [
        q.id,
        q.ts ? new Date(q.ts).toLocaleDateString("en-AU") : "",
        q.customerName || q.company || "",
        (q.machines || []).map((m) => m.name || m.id).join(", ") ||
          q.machineType ||
          "",
        q.city || q.suburb || "",
        (q.responses || []).length,
        status,
        resp ? (resp.grandTotal || 0).toFixed(2) : "",
      ];
    }),
  ]);
  wb.SheetNames.push("Quotes");

  // Sheet 8: Brand Impressions
  if (snap.brandRows.length > 0) {
    wb.Sheets["Brand Impressions"] = S([
      [
        "Brand",
        "Category",
        "Status",
        "Impressions (Period)",
        "Clicks (Period)",
        "CTR (Period)",
        "Total Impressions",
        "Total Clicks",
      ],
      ...snap.brandRows.map((r) => [
        r.brand,
        r.category,
        r.status,
        r.imprInRange,
        r.clicksInRange,
        r.ctrRange,
        r.totalImpr,
        r.totalClicks,
      ]),
    ]);
    wb.SheetNames.push("Brand Impressions");
  }

  XLSX.writeFile(
    wb,
    "noyo-analytics-" + period.from + "-to-" + period.to + ".xlsx",
  );
  showToast("Excel exported successfully", "#16A34A", 4000);
}

function exportAnalyticsPDF() {
  if (typeof window.jspdf === "undefined") {
    showToast("PDF library loading — try again", "#F59E0B");
    return;
  }
  const snap = window._noyoAnalyticsSnap;
  if (!snap) {
    showToast("Run analytics first", "#F59E0B");
    return;
  }
  showToast("Building PDF report...", "#DC2626", 2000);
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
  const W = 210,
    M = 14;
  let y = 0;

  const addPage = (need = 20) => {
    if (y + need > 278) {
      doc.addPage();
      y = 16;
    }
  };

  // Cover
  doc.setFillColor(15, 23, 42);
  doc.rect(0, 0, W, 50, "F");
  doc.setTextColor(255, 255, 255);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(22);
  doc.text("NOYO Analytics Report", M, 22);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text("Period: " + snap.period.from + "  to  " + snap.period.to, M, 32);
  doc.text("Generated: " + new Date().toLocaleString("en-AU"), M, 40);
  doc.setTextColor(148, 163, 184);
  doc.setFontSize(8);
  doc.text(
    "noyo.com.au  -  Australia's Heavy Equipment Hire Marketplace",
    M,
    47,
  );
  y = 60;

  // KPI tiles
  doc.setTextColor(15, 23, 42);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(12);
  doc.text("Platform KPIs", M, y);
  y += 6;
  const kpiData = [
    ["Total Searches", snap.kpis.totalSearches.toLocaleString(), [0, 82, 204]],
    ["Cart Adds", snap.kpis.totalCartAdds.toLocaleString(), [124, 58, 237]],
    ["Quotes Sent", snap.kpis.totalQuotes.toLocaleString(), [8, 145, 178]],
    [
      "Hires Confirmed",
      snap.kpis.totalAccepted.toLocaleString(),
      [22, 163, 74],
    ],
    ["Search to Cart", snap.kpis.convRate + "%", [217, 119, 6]],
    [
      "Match Rate",
      snap.kpis.totalQuotes > 0
        ? Math.round((snap.kpis.totalResponded / snap.kpis.totalQuotes) * 100) +
          "%"
        : "0%",
      [220, 38, 38],
    ],
  ];
  const colW = (W - M * 2) / 3;
  kpiData.forEach(([label, val, color], i) => {
    const col = i % 3,
      row = Math.floor(i / 3);
    const bx = M + col * colW,
      by = y + row * 18;
    doc.setFillColor(248, 250, 252);
    doc.roundedRect(bx, by, colW - 3, 15, 2, 2, "F");
    doc.setDrawColor(...color);
    doc.setLineWidth(0.8);
    doc.line(bx, by, bx, by + 15);
    doc.setTextColor(...color);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(14);
    doc.text(val, bx + 4, by + 9);
    doc.setTextColor(100, 116, 139);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7);
    doc.text(label, bx + 4, by + 13.5);
  });
  y += 42;

  // Top categories
  addPage(60);
  doc.autoTable({
    startY: y,
    margin: { left: M, right: M },
    head: [["Category", "Searches"]],
    headStyles: { fillColor: [0, 82, 204], fontSize: 8, fontStyle: "bold" },
    body: Object.entries(snap.categories)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 12)
      .map(([k, v]) => [k, v]),
    bodyStyles: { fontSize: 8 },
    alternateRowStyles: { fillColor: [248, 250, 252] },
    columnStyles: { 1: { halign: "right", fontStyle: "bold" } },
  });
  y = doc.lastAutoTable.finalY + 8;

  // Geography - two columns
  addPage(60);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(11);
  doc.setTextColor(15, 23, 42);
  doc.text("Geography", M, y);
  y += 4;
  doc.autoTable({
    startY: y,
    margin: { left: M, right: W / 2 + 1 },
    head: [["City", "Sessions"]],
    headStyles: { fillColor: [20, 184, 166], fontSize: 8, fontStyle: "bold" },
    body: Object.entries(snap.cities)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8)
      .map(([k, v]) => [k, Math.round(v)]),
    bodyStyles: { fontSize: 8 },
    alternateRowStyles: { fillColor: [248, 250, 252] },
  });
  const leftFinal = doc.lastAutoTable.finalY;
  doc.autoTable({
    startY: y,
    margin: { left: W / 2 + 1, right: M },
    head: [["Country", "Sessions"]],
    headStyles: { fillColor: [217, 119, 6], fontSize: 8, fontStyle: "bold" },
    body: Object.entries(snap.countries || {})
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8)
      .map(([k, v]) => [k, v]),
    bodyStyles: { fontSize: 8 },
    alternateRowStyles: { fillColor: [255, 251, 235] },
  });
  y = Math.max(leftFinal, doc.lastAutoTable.finalY) + 8;

  // Traffic sources
  addPage(50);
  doc.autoTable({
    startY: y,
    margin: { left: M, right: W / 2 + 1 },
    head: [["Traffic Source", "Sessions"]],
    headStyles: { fillColor: [124, 58, 237], fontSize: 8, fontStyle: "bold" },
    body: Object.entries(snap.sources || {})
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8)
      .map(([k, v]) => [k.replace(/_/g, " "), v]),
    bodyStyles: { fontSize: 8 },
    alternateRowStyles: { fillColor: [248, 250, 252] },
  });
  const srcFinal = doc.lastAutoTable.finalY;
  doc.autoTable({
    startY: y,
    margin: { left: W / 2 + 1, right: M },
    head: [["Device", "Sessions"]],
    headStyles: { fillColor: [15, 118, 110], fontSize: 8, fontStyle: "bold" },
    body: Object.entries(snap.devices || {})
      .sort((a, b) => b[1] - a[1])
      .map(([k, v]) => [k, v]),
    bodyStyles: { fontSize: 8 },
    alternateRowStyles: { fillColor: [240, 253, 250] },
  });
  y = Math.max(srcFinal, doc.lastAutoTable.finalY) + 8;

  // Top machines
  addPage(60);
  doc.autoTable({
    startY: y,
    margin: { left: M, right: M },
    head: [["#", "Machine", "Brand", "Views", "Cart Adds", "Conv%"]],
    headStyles: { fillColor: [124, 58, 237], fontSize: 8, fontStyle: "bold" },
    body: snap.machineTop
      .slice(0, 10)
      .map((m, i) => [
        i + 1,
        m.name,
        m.brand || "",
        m.views,
        m.cartAdds,
        m.views > 0 ? ((m.cartAdds / m.views) * 100).toFixed(1) + "%" : "0%",
      ]),
    bodyStyles: { fontSize: 7.5 },
    alternateRowStyles: { fillColor: [248, 250, 252] },
    columnStyles: {
      0: { halign: "center", cellWidth: 8 },
      3: { halign: "right" },
      4: { halign: "right" },
      5: { halign: "right", fontStyle: "bold" },
    },
  });
  y = doc.lastAutoTable.finalY + 8;

  // Quotes pipeline
  addPage(40);
  doc.autoTable({
    startY: y,
    margin: { left: M, right: M },
    head: [["Date", "Customer", "Machines", "City", "Status", "Value"]],
    headStyles: { fillColor: [8, 145, 178], fontSize: 8, fontStyle: "bold" },
    body: snap.quotes.slice(0, 20).map((q) => {
      const resp = (q.responses || []).find((r) => r.accepted);
      const s = q.acceptedBy
        ? "Accepted"
        : (q.responses || []).length > 0
          ? "Quoted"
          : "Pending";
      return [
        q.ts
          ? new Date(q.ts).toLocaleDateString("en-AU", {
              day: "2-digit",
              month: "short",
            })
          : "",
        (q.customerName || q.company || "").slice(0, 18),
        (
          (q.machines || []).map((m) => m.name || "").join(", ") ||
          q.machineType ||
          ""
        ).slice(0, 22),
        (q.city || q.suburb || "").slice(0, 14),
        s,
        resp ? "$" + (resp.grandTotal || 0).toFixed(0) : "",
      ];
    }),
    bodyStyles: { fontSize: 7 },
    alternateRowStyles: { fillColor: [248, 250, 252] },
  });
  y = doc.lastAutoTable.finalY + 8;

  // Brand impressions
  if (snap.brandRows.length > 0) {
    addPage(40);
    doc.autoTable({
      startY: y,
      margin: { left: M, right: M },
      head: [
        ["Brand", "Category", "Status", "Impr.", "Clicks", "CTR", "Total Impr"],
      ],
      headStyles: { fillColor: [180, 83, 9], fontSize: 8, fontStyle: "bold" },
      body: snap.brandRows.map((r) => [
        r.brand,
        r.category,
        r.status,
        r.imprInRange,
        r.clicksInRange,
        r.ctrRange,
        r.totalImpr,
      ]),
      bodyStyles: { fontSize: 7.5 },
      alternateRowStyles: { fillColor: [255, 251, 235] },
    });
  }

  // Page footers
  const pages = doc.internal.getNumberOfPages();
  for (let p = 1; p <= pages; p++) {
    doc.setPage(p);
    doc.setFontSize(7);
    doc.setTextColor(148, 163, 184);
    doc.text(
      "Noyo Analytics  |  noyo.com.au  |  Page " +
        p +
        " of " +
        pages +
        "  |  " +
        snap.period.from +
        " to " +
        snap.period.to,
      M,
      292,
    );
  }

  doc.save(
    "noyo-analytics-" + snap.period.from + "-to-" + snap.period.to + ".pdf",
  );
  showToast("PDF exported successfully", "#DC2626", 4000);
}

function exportFullAnalyticsCSV() {
  const from = document.getElementById("analytics-from")?.value || "all";
  const to = document.getElementById("analytics-to")?.value || "now";
  const rows = [
    ["Metric", "Value", "Period"],
    ["Total Enquiries", quoteInbox.length, `${from} to ${to}`],
    [
      "Responded",
      quoteInbox.filter((r) => (r.responses || []).length > 0).length,
      "",
    ],
    ["Accepted", quoteInbox.filter((r) => r.acceptedBy).length, ""],
    [
      "Match Rate %",
      quoteInbox.length > 0
        ? Math.round(
            (quoteInbox.filter((r) => (r.responses || []).length > 0).length /
              quoteInbox.length) *
              100,
          ) + "%"
        : "0%",
      "",
    ],
  ];
  // Add brand rows
  (window._lastBrandReportRows || []).forEach((r) => {
    rows.push([
      `Brand: ${r.brand}`,
      `${r.imprInRange} impressions, ${r.clicksInRange} clicks, CTR ${r.ctrRange}`,
      from + " to " + to,
    ]);
  });
  const csv = rows.map((r) => r.join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `noyo-analytics-${from}-${to}.csv`;
  a.click();
  URL.revokeObjectURL(url);
  showToast("📥 Analytics exported", "#16A34A");
}

function copyAnalyticsSummary() {
  const total = quoteInbox.length;
  const responded = quoteInbox.filter(
    (r) => (r.responses || []).length > 0,
  ).length;
  const accepted = quoteInbox.filter((r) => r.acceptedBy).length;
  const matchRate = total > 0 ? Math.round((responded / total) * 100) : 0;
  const from = document.getElementById("analytics-from")?.value || "—";
  const to = document.getElementById("analytics-to")?.value || "—";
  const text = `📊 NOYO Platform Report (${from} → ${to})
─────────────────────────────
📨 Total Enquiries:    ${total}
💬 Responses Received: ${responded} (${matchRate}% match rate)
✅ Hires Confirmed:    ${accepted}
📍 Active on Platform: ${Object.keys(customerRegistry || {}).length} users registered
─────────────────────────────
Powered by Noyo — noyo.com.au`;
  navigator.clipboard
    .writeText(text)
    .then(() => showToast("📋 Summary copied to clipboard", "#16A34A"))
    .catch(() => showToast("Copy failed", "#EF4444"));
}

function exportBrandReport() {
  const rows = window._lastBrandReportRows || [];
  const period = window._lastBrandReportPeriod || "all";
  if (!rows.length) {
    showToast("No brand data to export", "#EF4444");
    return;
  }
  const headers = [
    "Brand",
    "Category",
    "Status",
    "Impressions (Period)",
    "Clicks (Period)",
    "CTR (Period)",
    "Total Impressions (All Time)",
    "Total Clicks (All Time)",
  ];
  const csv = [
    headers.join(","),
    ...rows.map((r) =>
      [
        `"${r.brand}"`,
        `"${r.category}"`,
        `"${r.status}"`,
        r.imprInRange,
        r.clicksInRange,
        `"${r.ctrRange}"`,
        r.totalImpr,
        r.totalClicks,
      ].join(","),
    ),
  ].join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `noyo-brand-report-${period}.csv`;
  a.click();
  URL.revokeObjectURL(url);
  showToast("📥 Brand report exported", "#16A34A");
}

