// Add cluster to existing RENTAL_COMPANIES based on their address
(function buildRentalCompanyClusters() {
  RENTAL_COMPANIES.forEach((c) => {
    if (!c.cluster) {
      const detected = detectCityFromAddress(c.address || "");
      c.cluster = detected ? detected[0] : (c.cities && c.cities[0]) || "";
    }
  });
})();

